    def resolve_uslci_flow_authoring_bulk_batch_supports(
        self, batch_index: int
    ) -> JsonObject:
        """Resolve one exact Flow authoring bulk batch from immediate-prior authority."""

        if (
            isinstance(batch_index, bool)
            or not isinstance(batch_index, int)
            or batch_index < 2
            or batch_index > 16
        ):
            raise ValueError("Flow authoring support batch index must be between 2 and 16")

        snapshot = self._project(self.events())
        plan = snapshot.get("uslci_flow_authoring_plan")
        supports = snapshot.get("uslci_flow_authoring_canary_supports")
        route_authority = (
            snapshot.get("uslci_elementary_flow_native_qa_harness")
            if batch_index == 2
            else snapshot.get("uslci_flow_authoring_bulk_batch_native_gates")
        )
        runtime = snapshot.get("portable_runtime_closure")
        if not all(isinstance(value, dict) for value in (plan, supports, route_authority, runtime)):
            raise ValueError(
                "Current Flow plan, support authority, typed QA and copied runtime are required"
            )
        if (
            plan.get("status") != "uslci_flow_authoring_plan_compiled"
            or plan.get("authoring_plan_version") != "44d477987db9e8fe"
            or plan.get("authoring_intent_count") != 1456
            or plan.get("authoring_batch_count") != 16
            or supports.get("status")
            != "uslci_flow_authoring_canary_supports_resolved"
            or supports.get("support_resolution_version") != "4575e0df62e45cfa"
            or runtime.get("status")
            != "portable_native_tool_runtime_closure_verified"
        ):
            raise ValueError(f"Current state does not route to Flow authoring batch {batch_index} supports")
        if batch_index == 2:
            authority_valid = (
                route_authority.get("status")
                == "uslci_elementary_flow_native_qa_harness_resolved"
                and route_authority.get("typed_qa_status")
                == "typed_flow_qa_passed_with_scoped_elementary_not_applicable_findings"
                and route_authority.get("bulk_planning_release_authorized") is True
                and route_authority.get("bulk_entity_execution_authorized") is False
                and route_authority.get("next_internal_route")
                == "resolve-uslci-flow-authoring-bulk-batch-2-supports"
            )
        else:
            try:
                validate_uslci_flow_bulk_batch_support_route_authority(
                    route_authority, batch_index=batch_index
                )
            except ValueError:
                authority_valid = False
            else:
                authority_valid = True
        if not authority_valid:
            raise ValueError(f"Immediate-prior authority does not release batch {batch_index}")

        registered_by_path = {
            row.get("workspace_path"): row
            for row in snapshot.get("artifacts", [])
            if isinstance(row, dict) and isinstance(row.get("workspace_path"), str)
        }

        def registered(path_value, label, expected_hash=None):
            relative = _required_text(path_value, f"{label} path")
            record = registered_by_path.get(relative)
            if not isinstance(record, dict):
                raise RuntimeError(f"{label} is not a registered project artifact")
            path = (self.workspace / relative).resolve()
            try:
                path.relative_to(self.workspace)
            except ValueError as error:
                raise ValueError(f"{label} escaped workspace") from error
            if not path.is_file():
                raise RuntimeError(f"{label} is missing")
            content = path.read_bytes()
            digest = hashlib.sha256(content).hexdigest()
            if (
                digest != record.get("sha256")
                or len(content) != record.get("bytes")
                or (expected_hash is not None and digest != expected_hash)
            ):
                raise RuntimeError(f"{label} hash or byte count drifted")
            return path, {"path": relative, "sha256": digest, "bytes": len(content)}

        source_paths = {}
        source_specs = {}

        def bind(name, owner, path_key, hash_key, label):
            source_paths[name], source_specs[name] = registered(
                owner.get(path_key), label, owner.get(hash_key)
            )

        bind(
            "authoring_plan_report",
            plan,
            "report_path",
            "report_sha256",
            "Flow authoring plan report",
        )
        bind(
            "authoring_intents",
            plan,
            "authoring_intents_path",
            "authoring_intents_sha256",
            "Flow authoring intents",
        )
        bind(
            "authoring_batches",
            plan,
            "authoring_batches_path",
            "authoring_batches_sha256",
            "Flow authoring batches",
        )
        try:
            intent_rows = [
                json.loads(line)
                for line in source_paths["authoring_intents"]
                .read_text(encoding="utf-8")
                .splitlines()
                if line.strip()
            ]
            batch_rows = [
                json.loads(line)
                for line in source_paths["authoring_batches"]
                .read_text(encoding="utf-8")
                .splitlines()
                if line.strip()
            ]
            required_source_flow_ids = selected_batch_source_flow_ids(
                intent_rows, batch_rows, batch_index=batch_index
            )
        except (OSError, UnicodeDecodeError, json.JSONDecodeError, ValueError) as error:
            raise RuntimeError(
                f"Flow authoring batch {batch_index} membership is invalid"
            ) from error

        candidate_paths = sorted(
            path
            for path in registered_by_path
            if "/raw-public-responses/" in path and path.endswith(".json")
        )

        def source_envelope_candidates():
            for relative in candidate_paths:
                path = (self.workspace / relative).resolve()
                try:
                    path.relative_to(self.workspace)
                except ValueError as error:
                    raise ValueError(
                        "Registered source envelope escaped workspace"
                    ) from error
                if path.is_file():
                    yield relative, path.read_bytes()

        try:
            selected_source_path = select_complete_source_envelope(
                source_envelope_candidates(), required_source_flow_ids
            )
        except (OSError, ValueError) as error:
            raise RuntimeError(
                f"No registered source envelope completely covers Flow authoring batch {batch_index}"
            ) from error
        source_paths["elementary_source_envelope"], source_specs[
            "elementary_source_envelope"
        ] = registered(selected_source_path, "elementary source envelope")
        bind(
            "support_report",
            supports,
            "report_path",
            "report_sha256",
            "canary support report",
        )
        bind(
            "support_contracts",
            supports,
            "support_contracts_path",
            "support_contracts_sha256",
            "accepted support contracts",
        )
        bind(
            "runtime_evidence",
            supports,
            "runtime_evidence_path",
            "runtime_evidence_sha256",
            "accepted support runtime evidence",
        )
        bind(
            "route_authority",
            route_authority,
            "report_path",
            "report_sha256",
            f"batch-{batch_index} route authority",
        )
        bind(
            "runtime_report",
            runtime,
            "report_path",
            "report_sha256",
            "portable native runtime report",
        )
        bind(
            "runtime_manifest",
            runtime,
            "manifest_path",
            "manifest_sha256",
            "portable native runtime manifest",
        )
        batch_matches = [
            row
            for row in batch_rows
            if isinstance(row, dict) and row.get("batch_index") == batch_index
        ]
        if len(batch_matches) != 1:
            raise RuntimeError(f"Flow authoring batch {batch_index} descriptor is not unique")
        batch_descriptor = batch_matches[0]
        expected_batch_key = _required_text(
            batch_descriptor.get("batch_key"), f"batch {batch_index} key"
        )
        expected_action_count = batch_descriptor.get("action_count")
        if isinstance(expected_action_count, bool) or not isinstance(
            expected_action_count, int
        ):
            raise RuntimeError(f"Flow authoring batch {batch_index} action count is invalid")
        if expected_action_count <= 0 or expected_action_count > 100:
            raise RuntimeError(f"Flow authoring batch {batch_index} action count exceeds bounds")
        authoring_group_counts = batch_descriptor.get("authoring_group_counts")
        if not isinstance(authoring_group_counts, dict):
            raise RuntimeError(f"Flow authoring batch {batch_index} group counts are invalid")
        expected_support_contract_count = len(
            {
                tuple(str(key).split("|")[-2:])
                for key, count in authoring_group_counts.items()
                if isinstance(count, int) and not isinstance(count, bool) and count > 0
            }
        )
        ordered_specs = [
            source_specs[name] for name in USLCI_FLOW_BULK_BATCH_SUPPORT_INPUT_NAMES
        ]
        input_version = uslci_flow_bulk_batch_support_input_version(ordered_specs)
        current = snapshot.get("uslci_flow_authoring_bulk_batch_supports")
        if (
            isinstance(current, dict)
            and current.get("input_version") == input_version
            and current.get("logic_version")
            == USLCI_FLOW_BULK_BATCH_SUPPORT_LOGIC_VERSION
            and current.get("policy_version")
            == USLCI_FLOW_BULK_BATCH_SUPPORT_POLICY_VERSION
        ):
            refs = current.get("activity_artifact_refs")
            if not isinstance(refs, list) or not refs:
                raise RuntimeError("Current bulk support result has no artifacts")
            for row in refs:
                registered(
                    row.get("workspace_path"),
                    "current bulk support artifact",
                    row.get("sha256"),
                )
            return current

        scope_id = _required_text(plan.get("scope_id"), "Flow scope")
        revision = _required_text(plan.get("revision"), "Flow revision")
        scope_key = f"{scope_id}:{revision}"
        base = f"uslci-flow-authoring-bulk-batch-{batch_index}-supports:{scope_key}:{input_version}"
        attempt = self._semantic_attempt(base)
        activity_id = f"{base}:attempt-{attempt}"
        root = (
            self.workspace
            / "artifacts/uslci-flow-authoring-bulk-batch-support-resolutions"
            / f"{scope_id}-{revision}"
            / f"batch-{batch_index}"
            / input_version
            / f"attempt-{attempt}"
        )
        inputs = root / "inputs"
        binding_paths = {
            name: inputs / f"{name.replace('_', '-')}.binding.json"
            for name in USLCI_FLOW_BULK_BATCH_SUPPORT_INPUT_NAMES
        }
        self.record(
            "milestone.started",
            {
                "milestone_id": f"uslci-flow-authoring-bulk-batch-{batch_index}-supports",
                "title": f"消解 Flow authoring batch {batch_index} 分类与支撑合同",
                "status": "running",
                "next_action": (
                    f"按稳定 intent key 绑定 {expected_action_count} 个源 observation、"
                    "TianGong 原生分类路径和对应 FlowProperty/UnitGroup 合同"
                ),
                "terms": [
                    {
                        "term": "stable key（稳定键）",
                        "explanation": "每个 Flow 用内容派生的 authoring_intent_key 识别；顺序和名称都不能替代身份。",
                    },
                    {
                        "term": "support contract（支撑合同）",
                        "explanation": "FlowProperty、参考单位和 UnitGroup 的可寻址证据；它允许编译本地计划，不等于远程实体已经存在。",
                    },
                ],
            },
            actor="controller",
            idempotency_key=(
                f"milestone:uslci-flow-authoring-bulk-batch-{batch_index}-supports:"
                f"{scope_key}:{input_version}:started"
            ),
        )
        if self._completed_activity(activity_id) is None:
            inputs.mkdir(parents=True, exist_ok=True)
            for name, spec in source_specs.items():
                _write_json(binding_paths[name], spec)

        prefix = f"uslci-flow-authoring-bulk-batch-{batch_index}"
        output_names = {
            "report": f"{prefix}-support-resolution.json",
            "selected_batch": f"{prefix}-selection.json",
            "source_observations": f"{prefix}-source-observations.jsonl",
            "classification_policy": f"{prefix}-classification-policy.jsonl",
            "native_classification_probes": f"{prefix}-native-classification-probes.jsonl",
            "classification_decisions": f"{prefix}-classification-decisions.jsonl",
            "support_assignments": f"{prefix}-support-assignments.jsonl",
            "readiness": f"{prefix}-readiness.jsonl",
            "review_markers": f"{prefix}-review-markers.jsonl",
            "failures": f"{prefix}-support-failures.jsonl",
        }
        raw_names = native_probe_filenames_for_batch(batch_index)
        expected = [
            *[
                f"inputs/{binding_paths[name].name}"
                for name in USLCI_FLOW_BULK_BATCH_SUPPORT_INPUT_NAMES
            ],
            *[f"outputs/{name}" for name in output_names.values()],
            *[f"outputs/{name}" for name in raw_names],
        ]
        command = [
            "python3",
            str(
                Path(__file__).with_name(
                    "uslci_flow_authoring_bulk_batch_supports.py"
                )
            ),
        ]
        for name in USLCI_FLOW_BULK_BATCH_SUPPORT_INPUT_NAMES:
            option = name.replace("_", "-")
            command.extend(
                [
                    f"--{option}",
                    str(source_paths[name]),
                    f"--{option}-binding",
                    str(binding_paths[name]),
                ]
            )
        runtime_root = (
            source_paths["runtime_report"].parent.parent
            / "extracted-runtime"
            / "runtime"
        )
        command.extend(
            [
                "--runtime-root",
                str(runtime_root),
                "--out-dir",
                str(root),
                "--batch-index",
                str(batch_index),
            ]
        )
        activity = self.run_activity(
            activity_id=activity_id,
            name=f"消解 Flow authoring batch {batch_index} 分类与支撑合同",
            skill_ref="run-lca-research-project/uslci-flow-authoring-bulk-batch-supports",
            command=command,
            artifact_root=root,
            expected_outputs=expected,
            effect="local_write",
        )
        artifacts = {row["path"]: row for row in activity["artifacts"]}
        report_path = root / "outputs" / output_names["report"]
        try:
            report = json.loads(report_path.read_bytes())
        except (OSError, UnicodeDecodeError, json.JSONDecodeError) as error:
            raise RuntimeError(f"Flow batch-{batch_index} support report is invalid") from error
        zero = (
            "network_read_executed_count",
            "remote_candidate_search_executed_count",
            "saved_flow_plan_compiled_count",
            "flow_creation_executed_count",
            "flow_materialization_executed_count",
            "remote_flow_materialization_executed_count",
            "save_draft_executed_count",
            "process_creation_executed_count",
            "model_connection_executed_count",
            "model_mutation_executed_count",
            "external_write_executed_count",
            "publication_executed_count",
            "comparison_executed_count",
            "lcia_executed_count",
        )
        if (
            not isinstance(report, dict)
            or report.get("contract") != USLCI_FLOW_BULK_BATCH_SUPPORT_CONTRACT
            or report.get("logic_version")
            != USLCI_FLOW_BULK_BATCH_SUPPORT_LOGIC_VERSION
            or report.get("policy_version")
            != USLCI_FLOW_BULK_BATCH_SUPPORT_POLICY_VERSION
            or report.get("status")
            != f"uslci_flow_authoring_bulk_batch_{batch_index}_supports_resolved"
            or report.get("input_version") != input_version
            or report.get("batch_index") != batch_index
            or report.get("batch_key") != expected_batch_key
            or not isinstance(report.get("source_category_counts"), dict)
            or any(
                not str(category).startswith(
                    ("Elementary flows/emission/", "Elementary flows/resource/")
                )
                for category in report.get("source_category_counts", {})
            )
            or sum(report.get("source_category_counts", {}).values())
            != expected_action_count
            or not isinstance(report.get("classification_code_counts"), dict)
            or sum(report.get("classification_code_counts", {}).values())
            != expected_action_count
            or not isinstance(report.get("flow_property_counts"), dict)
            or sum(report.get("flow_property_counts", {}).values())
            != expected_action_count
            or len(report.get("flow_property_counts", {}))
            != expected_support_contract_count
            or report.get("selected_intent_count") != expected_action_count
            or report.get("source_observation_count") != expected_action_count
            or report.get("classification_policy_count")
            != len(native_probe_filenames_for_batch(batch_index))
            or report.get("native_classification_probe_count")
            != len(native_probe_filenames_for_batch(batch_index))
            or report.get("native_invocation_executed_count")
            != len(native_probe_filenames_for_batch(batch_index))
            or report.get("classification_decision_count") != expected_action_count
            or report.get("support_contract_reuse_count")
            != expected_support_contract_count
            or report.get("support_assignment_count") != expected_action_count
            or report.get("ready_intent_count") != expected_action_count
            or report.get("review_marker_count")
            != (
                report.get("low_priority_review_marker_count", 0)
                + report.get("medium_priority_review_marker_count", 0)
                + report.get("high_priority_review_marker_count", 0)
            )
            or report.get("resolution_failure_count") != 0
            or report.get("saved_plan_compilation_authorized") is not True
            or report.get("entity_creation_authorized") is not False
            or report.get("bulk_entity_execution_authorized") is not False
            or any(report.get(key) != 0 for key in zero)
            or report.get("routing", {}).get("pause_internal_work") is not False
            or report.get("routing", {}).get("next_internal_route")
            != f"compile-uslci-flow-authoring-bulk-batch-{batch_index}-saved-plans"
            or report.get("scientific_comparison_ready") is not False
            or report.get("comparative_lcia_allowed") is not False
        ):
            raise RuntimeError(f"Flow batch-{batch_index} support resolution violated boundaries")
        output_keys = {key: f"outputs/{value}" for key, value in output_names.items()}
        for name, output_key in output_keys.items():
            if name == "report":
                continue
            expected_binding = report.get("artifact_bindings", {}).get(name)
            artifact = artifacts.get(output_key)
            if (
                not isinstance(expected_binding, dict)
                or not isinstance(artifact, dict)
                or expected_binding.get("sha256") != artifact.get("sha256")
                or expected_binding.get("bytes") != artifact.get("bytes")
            ):
                raise RuntimeError(f"Flow batch-{batch_index} output drifted: {name}")
        for descriptor in report.get("native_raw_artifact_bindings", []):
            path = descriptor.get("path") if isinstance(descriptor, dict) else None
            artifact = artifacts.get(f"outputs/{path}")
            if (
                not isinstance(artifact, dict)
                or descriptor.get("sha256") != artifact.get("sha256")
                or descriptor.get("bytes") != artifact.get("bytes")
            ):
                raise RuntimeError(f"Flow batch-{batch_index} raw native probe drifted")
        refs = [
            {
                "workspace_path": row["workspace_path"],
                "sha256": row["sha256"],
                "bytes": row["bytes"],
            }
            for row in activity["artifacts"]
        ]
        result = {
            **report,
            "report_path": artifacts[output_keys["report"]]["workspace_path"],
            "report_sha256": artifacts[output_keys["report"]]["sha256"],
            "activity_artifact_refs": refs,
            "artifact_count": len(refs),
            "next_internal_route": f"compile-uslci-flow-authoring-bulk-batch-{batch_index}-saved-plans",
            "next_action": report["routing"]["next_action"],
        }
        for name, output_key in output_keys.items():
            if name != "report":
                result[f"{name}_path"] = artifacts[output_key]["workspace_path"]
                result[f"{name}_sha256"] = artifacts[output_key]["sha256"]
        version = _required_text(
            result.get("resolution_version"), f"Flow batch-{batch_index} support resolution version"
        )
        self.record(
            "decision.recorded",
            {
                "decision_id": f"uslci-flow-authoring-batch-{batch_index}-supports:{scope_key}:{version}",
                "decision_type": "provider.uslci_flow_authoring_batch_supports_resolved",
                "batch_index": batch_index,
                "ready_intent_count": expected_action_count,
                "source_category_counts": result["source_category_counts"],
                "saved_plan_compilation_authorized": True,
                "entity_creation_authorized": False,
                "next_internal_route": result["next_internal_route"],
                "report_sha256": result["report_sha256"],
            },
            actor="controller",
            idempotency_key=f"decision:uslci-flow-authoring-batch-{batch_index}-supports:{scope_key}:{version}",
        )
        self.record(
            "risk.flagged",
            {
                "risk_id": f"uslci-flow-authoring-batch-{batch_index}-classification-review:{scope_key}",
                "severity": (
                    "medium"
                    if result.get("medium_priority_review_marker_count", 0)
                    else "low"
                ),
                "summary": f"Batch {batch_index} retains attributed classification interpretation markers for later review.",
                "risk_type": "classification_review_bundle",
                "affected_intent_count": result["review_marker_count"],
                "review_markers_path": result["review_markers_path"],
                "review_markers_sha256": result["review_markers_sha256"],
                "blocks_saved_plan_compilation": False,
                "blocks_entity_creation": True,
            },
            actor="controller",
            idempotency_key=f"risk:uslci-flow-authoring-batch-{batch_index}-classification-review:{scope_key}:{version}",
        )
        event = self.record(
            "research.uslci_flow_authoring_bulk_batch_supports.resolved",
            result,
            actor="controller",
            idempotency_key=(
                f"uslci-flow-authoring-bulk-batch-supports:{scope_key}:"
                f"batch-{batch_index}:{version}:resolved"
            ),
        )
        self.record(
            "milestone.completed",
            {
                "milestone_id": f"uslci-flow-authoring-bulk-batch-{batch_index}-supports",
                "title": f"Flow authoring batch {batch_index} 分类与支撑合同已消解",
                "status": "completed",
                "next_action": result["next_action"],
            },
            actor="controller",
            idempotency_key=(
                f"milestone:uslci-flow-authoring-bulk-batch-{batch_index}-supports:"
                f"{scope_key}:{version}:completed"
            ),
        )
        self.materialize_views()
        return event["payload"]

