    def compile_uslci_flow_authoring_bulk_batch_saved_plans(
        self, batch_index: int
    ) -> JsonObject:
        """Compile one exact accepted bulk Flow plan set without executing it."""

        if (
            isinstance(batch_index, bool)
            or not isinstance(batch_index, int)
            or batch_index < 2
            or batch_index > 16
        ):
            raise ValueError("Flow authoring saved-plan batch index must be between 2 and 16")

        events = self.events()
        snapshot = self._project(events)
        bulk = snapshot.get("uslci_flow_authoring_bulk_batch_supports")
        plan = snapshot.get("uslci_flow_authoring_plan")
        supports = snapshot.get("uslci_flow_authoring_canary_supports")
        runtime = snapshot.get("portable_runtime_closure")
        if not all(isinstance(value, dict) for value in (bulk, plan, supports, runtime)):
            raise ValueError(
                "Current batch support resolution, authoring plan, support authority and copied runtime are required"
            )
        if bulk.get("batch_index") != batch_index:
            historical = [
                event.get("payload")
                for event in events
                if event.get("event_type")
                == "research.uslci_flow_authoring_bulk_batch_saved_plans.compiled"
                and isinstance(event.get("payload"), dict)
                and event["payload"].get("batch_index") == batch_index
            ]
            if not historical:
                raise ValueError(
                    f"Current state does not expose batch-{batch_index} support or an accepted saved-plan result"
                )
            accepted = historical[-1]
            registered_by_path = {
                row.get("workspace_path"): row
                for row in snapshot.get("artifacts", [])
                if isinstance(row, dict)
                and isinstance(row.get("workspace_path"), str)
            }
            refs = accepted.get("activity_artifact_refs")
            if not isinstance(refs, list) or not refs:
                raise RuntimeError(
                    f"Accepted batch-{batch_index} saved-plan result has no artifacts"
                )
            for row in refs:
                if not isinstance(row, dict):
                    raise RuntimeError("Accepted bulk saved-plan artifact reference drifted")
                relative = _required_text(
                    row.get("workspace_path"), "accepted saved-plan artifact path"
                )
                registered = registered_by_path.get(relative)
                path = (self.workspace / relative).resolve()
                try:
                    path.relative_to(self.workspace)
                except ValueError as error:
                    raise ValueError(
                        "Accepted bulk saved-plan artifact escaped workspace"
                    ) from error
                if (
                    not isinstance(registered, dict)
                    or not path.is_file()
                    or registered.get("sha256") != row.get("sha256")
                    or registered.get("bytes") != row.get("bytes")
                    or hashlib.sha256(path.read_bytes()).hexdigest() != row.get("sha256")
                    or path.stat().st_size != row.get("bytes")
                ):
                    raise RuntimeError(
                        f"Accepted batch-{batch_index} saved-plan artifact drifted"
                    )
            return accepted
        action_count = bulk.get("ready_intent_count")
        review_count = bulk.get("review_marker_count")
        batch_key = bulk.get("batch_key")
        if (
            isinstance(action_count, bool)
            or not isinstance(action_count, int)
            or action_count < 1
            or action_count > 100
            or isinstance(review_count, bool)
            or not isinstance(review_count, int)
            or review_count < 0
            or review_count > action_count
            or not isinstance(batch_key, str)
            or not batch_key
        ):
            raise ValueError("Current bulk support descriptor is invalid")
        validate_uslci_flow_bulk_saved_plan_support_authority(
            bulk,
            batch_index=batch_index,
            action_count=action_count,
            review_count=review_count,
            report_sha256=bulk.get("report_sha256"),
        )
        if (
            bulk.get("status")
            != f"uslci_flow_authoring_bulk_batch_{batch_index}_supports_resolved"
            or bulk.get("next_internal_route")
            != f"compile-uslci-flow-authoring-bulk-batch-{batch_index}-saved-plans"
            or bulk.get("batch_index") != batch_index
            or bulk.get("resolution_failure_count") != 0
            or bulk.get("saved_plan_compilation_authorized") is not True
            or bulk.get("entity_creation_authorized") is not False
            or plan.get("status") != "uslci_flow_authoring_plan_compiled"
            or plan.get("authoring_plan_version") != "44d477987db9e8fe"
            or supports.get("status")
            != "uslci_flow_authoring_canary_supports_resolved"
            or supports.get("support_resolution_version") != "4575e0df62e45cfa"
            or runtime.get("status")
            != "portable_native_tool_runtime_closure_verified"
        ):
            raise ValueError(
                f"Current state does not route to batch-{batch_index} saved-plan compilation"
            )

        registered_by_path = {
            row.get("workspace_path"): row
            for row in snapshot.get("artifacts", [])
            if isinstance(row, dict) and isinstance(row.get("workspace_path"), str)
        }

        def registered(path_value, label, expected_hash=None):
            relative = _required_text(path_value, f"{label} path")
            record = registered_by_path.get(relative)
            if not isinstance(record, dict):
                raise RuntimeError(f"{label} is not a registered project artifact")
            path = (self.workspace / relative).resolve()
            try:
                path.relative_to(self.workspace)
            except ValueError as error:
                raise ValueError(f"{label} escaped workspace") from error
            if not path.is_file():
                raise RuntimeError(f"{label} is missing")
            content = path.read_bytes()
            digest = hashlib.sha256(content).hexdigest()
            if (
                digest != record.get("sha256")
                or len(content) != record.get("bytes")
                or (expected_hash is not None and digest != expected_hash)
            ):
                raise RuntimeError(f"{label} hash or byte count drifted")
            return path, {"path": relative, "sha256": digest, "bytes": len(content)}

        source_paths = {}
        source_specs = {}

        def bind(name, owner, path_key, hash_key, label):
            source_paths[name], source_specs[name] = registered(
                owner.get(path_key), label, owner.get(hash_key)
            )

        bind(
            "bulk_support_report",
            bulk,
            "report_path",
            "report_sha256",
            f"batch-{batch_index} support report",
        )
        for name in (
            "selected_batch",
            "source_observations",
            "classification_decisions",
            "support_assignments",
            "readiness",
            "review_markers",
        ):
            bind(
                name,
                bulk,
                f"{name}_path",
                f"{name}_sha256",
                f"batch-{batch_index} {name.replace('_', ' ')}",
            )
        bind(
            "authoring_plan_report",
            plan,
            "report_path",
            "report_sha256",
            "Flow authoring plan report",
        )
        bind(
            "authoring_intents",
            plan,
            "authoring_intents_path",
            "authoring_intents_sha256",
            "Flow authoring intents",
        )
        bind(
            "support_report",
            supports,
            "report_path",
            "report_sha256",
            "accepted support report",
        )
        bind(
            "support_contracts",
            supports,
            "support_contracts_path",
            "support_contracts_sha256",
            "accepted support contracts",
        )
        bind(
            "runtime_report",
            runtime,
            "report_path",
            "report_sha256",
            "portable native runtime report",
        )
        bind(
            "runtime_manifest",
            runtime,
            "manifest_path",
            "manifest_sha256",
            "portable native runtime manifest",
        )

        try:
            bulk_report_value = json.loads(source_paths["bulk_support_report"].read_bytes())
        except (OSError, UnicodeDecodeError, json.JSONDecodeError) as error:
            raise RuntimeError(
                f"Batch-{batch_index} support report cannot recover source binding"
            ) from error
        source_binding = (
            bulk_report_value.get("input_bindings", {}).get(
                "elementary_source_envelope"
            )
            if isinstance(bulk_report_value, dict)
            else None
        )
        if not isinstance(source_binding, dict):
            raise RuntimeError(
                f"Batch-{batch_index} support report has no elementary source binding"
            )
        registered(
            source_binding.get("path"),
            "bound elementary source envelope",
            source_binding.get("sha256"),
        )

        support_events = [
            event
            for event in events
            if event.get("event_type")
            == "research.uslci_flow_authoring_bulk_batch_supports.resolved"
            and isinstance(event.get("payload"), dict)
            and event["payload"].get("resolution_version")
            == bulk.get("resolution_version")
            and event["payload"].get("report_sha256") == bulk.get("report_sha256")
        ]
        if not support_events:
            raise RuntimeError(
                f"Accepted batch-{batch_index} support event is unavailable"
            )
        support_event = support_events[-1]
        planning_anchor = {
            "schema_version": 1,
            "contract": "lca_research_kernel.uslci_flow_authoring_bulk_saved_plan_anchor/v1",
            "source_event_id": support_event.get("event_id"),
            "source_event_sequence": support_event.get("sequence"),
            "occurred_at": support_event.get("occurred_at"),
            "resolution_version": bulk.get("resolution_version"),
            "support_resolution_report_sha256": bulk.get("report_sha256"),
        }
        planning_bytes = _json_bytes(planning_anchor)
        source_specs["planning_anchor"] = {
            "path": f"uslci-flow-authoring-bulk-batch-{batch_index}-saved-plan-anchor.json",
            "sha256": hashlib.sha256(planning_bytes).hexdigest(),
            "bytes": len(planning_bytes),
        }
        ordered_specs = [
            source_specs[name]
            for name in USLCI_FLOW_BULK_BATCH_SAVED_PLAN_INPUT_NAMES
        ]
        input_version = uslci_flow_bulk_batch_saved_plan_input_version(ordered_specs)
        current = snapshot.get("uslci_flow_authoring_bulk_batch_saved_plans")
        if (
            isinstance(current, dict)
            and current.get("input_version") == input_version
            and current.get("logic_version")
            == USLCI_FLOW_BULK_BATCH_SAVED_PLAN_LOGIC_VERSION
            and current.get("policy_version")
            == USLCI_FLOW_BULK_BATCH_SAVED_PLAN_POLICY_VERSION
        ):
            refs = current.get("activity_artifact_refs")
            if not isinstance(refs, list) or not refs:
                raise RuntimeError("Current bulk saved-plan result has no artifacts")
            for row in refs:
                registered(
                    row.get("workspace_path"),
                    "current bulk saved-plan artifact",
                    row.get("sha256"),
                )
            return current

        scope_id = _required_text(bulk.get("scope_id"), "Flow scope")
        revision = _required_text(bulk.get("revision"), "Flow revision")
        scope_key = f"{scope_id}:{revision}"
        base = (
            f"uslci-flow-authoring-bulk-batch-{batch_index}-saved-plans:"
            f"{scope_key}:{input_version}"
        )
        attempt = self._semantic_attempt(base)
        activity_id = f"{base}:attempt-{attempt}"
        root = (
            self.workspace
            / "artifacts/uslci-flow-authoring-bulk-batch-saved-plans"
            / f"{scope_id}-{revision}"
            / f"batch-{batch_index}"
            / input_version
            / f"attempt-{attempt}"
        )
        inputs = root / "inputs"
        planning_path = (
            inputs
            / f"uslci-flow-authoring-bulk-batch-{batch_index}-saved-plan-anchor.json"
        )
        binding_paths = {
            name: inputs / f"{name.replace('_', '-')}.binding.json"
            for name in USLCI_FLOW_BULK_BATCH_SAVED_PLAN_INPUT_NAMES
        }
        self.record(
            "milestone.started",
            {
                "milestone_id": f"uslci-flow-authoring-bulk-batch-{batch_index}-saved-plans",
                "title": f"编译 USLCI Flow authoring batch {batch_index} saved plans",
                "status": "running",
                "next_action": (
                    f"把 {action_count} 个稳定 intent 渲染为精确、内容寻址且不可静默重算的 "
                    "TianGong Flow plans"
                ),
                "terms": [
                    {
                        "term": "content descriptor（内容描述符）",
                        "explanation": "用媒体类型、路径、字节数和 SHA-256 指向一份精确计划；未来门禁只能消费这些相同字节。",
                    },
                    {
                        "term": "saved plan（冻结计划）",
                        "explanation": "已经绑定来源与决定的执行输入，不等于 Flow 已经创建或保存。",
                    },
                ],
            },
            actor="controller",
            idempotency_key=(
                f"milestone:uslci-flow-authoring-bulk-batch-{batch_index}-saved-plans:"
                f"{scope_key}:{input_version}:started"
            ),
        )
        if self._completed_activity(activity_id) is None:
            inputs.mkdir(parents=True, exist_ok=True)
            planning_path.write_bytes(planning_bytes)
            for name, spec in source_specs.items():
                _write_json(binding_paths[name], spec)
        source_paths["planning_anchor"] = planning_path

        try:
            decision_rows = [
                json.loads(line)
                for line in source_paths["classification_decisions"]
                .read_text(encoding="utf-8")
                .splitlines()
                if line.strip()
            ]
        except (OSError, UnicodeDecodeError, json.JSONDecodeError) as error:
            raise RuntimeError(
                f"Batch-{batch_index} classification decisions are invalid"
            ) from error
        plan_files = []
        for row in sorted(decision_rows, key=lambda value: value.get("batch_position", 0)):
            if not isinstance(row, dict):
                raise RuntimeError(
                    f"Batch-{batch_index} classification decision row is invalid"
                )
            batch_position = row.get("batch_position")
            target_id = row.get("target_flow_id")
            if (
                isinstance(batch_position, bool)
                or not isinstance(batch_position, int)
                or not isinstance(target_id, str)
                or not target_id
            ):
                raise RuntimeError(
                    f"Batch-{batch_index} plan filename identity is invalid"
                )
            plan_files.append(
                f"{batch_position:03d}-{target_id}-flow-build-plan.json"
            )
        if len(plan_files) != action_count or len(set(plan_files)) != action_count:
            raise RuntimeError(f"Batch-{batch_index} plan filename set is not exact")

        output_prefix = f"uslci-flow-authoring-bulk-batch-{batch_index}-saved-plan"
        output_names = {
            "report": f"uslci-flow-authoring-bulk-batch-{batch_index}-saved-plans.json",
            "plan_index": f"{output_prefix}-index.json",
            "field_assertions": f"{output_prefix}-field-assertions.jsonl",
            "execution_descriptors": f"{output_prefix}-execution-descriptors.jsonl",
            "review_marker_carry_forward": f"{output_prefix}-review-markers.jsonl",
            "execution_dag": f"{output_prefix}-execution-dag.json",
            "failures": f"{output_prefix}-failures.jsonl",
        }
        expected = [
            f"inputs/{planning_path.name}",
            *[
                f"inputs/{binding_paths[name].name}"
                for name in USLCI_FLOW_BULK_BATCH_SAVED_PLAN_INPUT_NAMES
            ],
            *[f"outputs/{name}" for name in output_names.values()],
            *[f"outputs/plans/{name}" for name in plan_files],
        ]
        command = [
            "python3",
            str(
                Path(__file__).with_name(
                    "uslci_flow_authoring_bulk_batch_saved_plans.py"
                )
            ),
        ]
        for name in USLCI_FLOW_BULK_BATCH_SAVED_PLAN_INPUT_NAMES:
            option = name.replace("_", "-")
            command.extend(
                [
                    f"--{option}",
                    str(source_paths[name]),
                    f"--{option}-binding",
                    str(binding_paths[name]),
                ]
            )
        command.extend(["--out-dir", str(root)])
        activity = self.run_activity(
            activity_id=activity_id,
            name=f"编译 USLCI Flow authoring batch {batch_index} saved plans",
            skill_ref="run-lca-research-project/uslci-flow-authoring-bulk-batch-saved-plans",
            command=command,
            artifact_root=root,
            expected_outputs=expected,
            effect="local_write",
        )
        artifacts = {row["path"]: row for row in activity["artifacts"]}
        report_path = root / "outputs" / output_names["report"]
        try:
            report = json.loads(report_path.read_bytes())
        except (OSError, UnicodeDecodeError, json.JSONDecodeError) as error:
            raise RuntimeError(
                f"Flow batch-{batch_index} saved-plan report is invalid"
            ) from error
        zero = (
            "native_invocation_executed_count",
            "network_read_executed_count",
            "remote_candidate_search_executed_count",
            "flow_creation_executed_count",
            "flow_materialization_executed_count",
            "remote_flow_materialization_executed_count",
            "save_draft_executed_count",
            "process_creation_executed_count",
            "model_connection_executed_count",
            "model_mutation_executed_count",
            "external_write_executed_count",
            "publication_executed_count",
            "comparison_executed_count",
            "lcia_executed_count",
        )
        if (
            not isinstance(report, dict)
            or report.get("contract") != USLCI_FLOW_BULK_BATCH_SAVED_PLAN_CONTRACT
            or report.get("logic_version")
            != USLCI_FLOW_BULK_BATCH_SAVED_PLAN_LOGIC_VERSION
            or report.get("policy_version")
            != USLCI_FLOW_BULK_BATCH_SAVED_PLAN_POLICY_VERSION
            or report.get("status")
            != f"uslci_flow_authoring_bulk_batch_{batch_index}_saved_plans_compiled"
            or report.get("input_version") != input_version
            or report.get("batch_index") != batch_index
            or report.get("batch_key") != batch_key
            or report.get("saved_flow_plan_count") != action_count
            or report.get("content_descriptor_count") != action_count
            or report.get("complete_plan_count") != action_count
            or report.get("unique_intent_count") != action_count
            or report.get("unique_source_flow_count") != action_count
            or report.get("unique_target_flow_count") != action_count
            or report.get("classification_path_bound_count") != action_count
            or report.get("support_contract_bound_count") != action_count
            or report.get("source_artifact_bound_count") != action_count
            or report.get("represented_support_contract_count")
            != bulk.get("support_contract_reuse_count")
            or report.get("source_category_counts")
            != bulk.get("source_category_counts")
            or report.get("classification_code_counts")
            != bulk.get("classification_code_counts")
            or report.get("flow_property_counts")
            != bulk.get("flow_property_counts")
            or report.get("review_marker_carry_forward_count") != review_count
            or report.get("low_priority_review_marker_count")
            != bulk.get("low_priority_review_marker_count", review_count)
            or report.get("medium_priority_review_marker_count", 0)
            != bulk.get("medium_priority_review_marker_count", 0)
            or report.get("missing_required_field_count") != 0
            or report.get("execution_dag_node_count") != action_count * 2 + 1
            or report.get("execution_dag_edge_count") != action_count * 2
            or report.get("planning_failure_count") != 0
            or report.get("entity_creation_authorized_count") != 0
            or report.get("batch_entity_release_authorized") is not False
            or any(report.get(key) != 0 for key in zero)
            or report.get("routing", {}).get("pause_internal_work") is not False
            or report.get("routing", {}).get("next_internal_route")
            != f"execute-uslci-flow-authoring-bulk-batch-{batch_index}-native-gates"
            or report.get("scientific_comparison_ready") is not False
            or report.get("comparative_lcia_allowed") is not False
        ):
            raise RuntimeError(
                f"Flow batch-{batch_index} saved plans violated acceptance boundaries"
            )
        output_keys = {key: f"outputs/{value}" for key, value in output_names.items()}
        for name, output_key in output_keys.items():
            if name == "report":
                continue
            expected_binding = report.get("artifact_bindings", {}).get(name)
            artifact = artifacts.get(output_key)
            if (
                not isinstance(expected_binding, dict)
                or not isinstance(artifact, dict)
                or expected_binding.get("sha256") != artifact.get("sha256")
                or expected_binding.get("bytes") != artifact.get("bytes")
            ):
                raise RuntimeError(
                    f"Flow batch-{batch_index} saved-plan output drifted: {name}"
                )
        saved_bindings = report.get("saved_plan_bindings")
        if (
            not isinstance(saved_bindings, list)
            or len(saved_bindings) != action_count
        ):
            raise RuntimeError(
                f"Flow batch-{batch_index} saved-plan manifest is incomplete"
            )
        for binding in saved_bindings:
            output_key = binding.get("path") if isinstance(binding, dict) else None
            artifact = artifacts.get(output_key)
            if (
                not isinstance(binding, dict)
                or not isinstance(artifact, dict)
                or binding.get("media_type")
                != "application/vnd.tiangong.flow-build-plan.v1+json"
                or binding.get("digest") != f"sha256:{binding.get('sha256')}"
                or binding.get("size") != binding.get("bytes")
                or binding.get("sha256") != artifact.get("sha256")
                or binding.get("bytes") != artifact.get("bytes")
            ):
                raise RuntimeError(
                    f"Flow batch-{batch_index} exact saved-plan bytes drifted"
                )
        _audit_bulk_saved_plan_outputs(
            root,
            report,
            batch_index=batch_index,
            action_count=action_count,
            review_count=review_count,
        )
        refs = [
            {
                "workspace_path": row["workspace_path"],
                "sha256": row["sha256"],
                "bytes": row["bytes"],
            }
            for row in activity["artifacts"]
        ]
        result = {
            **report,
            "report_path": artifacts[output_keys["report"]]["workspace_path"],
            "report_sha256": artifacts[output_keys["report"]]["sha256"],
            "activity_artifact_refs": refs,
            "artifact_count": len(refs),
            "saved_plan_artifact_refs": [
                {
                    **binding,
                    "workspace_path": artifacts[binding["path"]]["workspace_path"],
                }
                for binding in saved_bindings
            ],
            "next_internal_route": (
                f"execute-uslci-flow-authoring-bulk-batch-{batch_index}-native-gates"
            ),
        }
        for name, output_key in output_keys.items():
            if name != "report":
                result[f"{name}_path"] = artifacts[output_key]["workspace_path"]
                result[f"{name}_sha256"] = artifacts[output_key]["sha256"]
        version = _required_text(
            result.get("saved_plan_set_version"),
            f"batch-{batch_index} saved-plan set version",
        )
        self.record(
            "decision.recorded",
            {
                "decision_id": (
                    f"uslci-flow-authoring-batch-{batch_index}-saved-plans:"
                    f"{scope_key}:{version}"
                ),
                "decision_type": "provider.uslci_flow_authoring_bulk_batch_saved_plans_compiled",
                "batch_index": batch_index,
                "saved_flow_plan_count": action_count,
                "content_descriptor_count": action_count,
                "review_marker_carry_forward_count": review_count,
                "batch_entity_release_authorized": False,
                "next_internal_route": result["next_internal_route"],
                "report_sha256": result["report_sha256"],
            },
            actor="controller",
            idempotency_key=(
                f"decision:uslci-flow-authoring-batch-{batch_index}-saved-plans:"
                f"{scope_key}:{version}"
            ),
        )
        event = self.record(
            "research.uslci_flow_authoring_bulk_batch_saved_plans.compiled",
            result,
            actor="controller",
            idempotency_key=(
                "uslci-flow-authoring-bulk-batch-saved-plans:"
                f"{scope_key}:batch-{batch_index}:{version}:compiled"
            ),
        )
        self.record(
            "milestone.completed",
            {
                "milestone_id": f"uslci-flow-authoring-bulk-batch-{batch_index}-saved-plans",
                "title": f"USLCI Flow authoring batch {batch_index} saved plans 已编译",
                "status": "completed",
                "next_action": result["next_action"],
            },
            actor="controller",
            idempotency_key=(
                f"milestone:uslci-flow-authoring-bulk-batch-{batch_index}-saved-plans:"
                f"{scope_key}:{version}:completed"
            ),
        )
        self.materialize_views()
        return event["payload"]

