        scope_id = _required_text(probe.get("scope_id"), "USLCI normalization scope_id")
        revision = _required_text(probe.get("revision"), "USLCI normalization revision")
        scope_key = f"{scope_id}:{revision}"
        base_id = f"uslci-provider-normalization:{scope_key}:{input_version}"
