    @staticmethod
    def _inventory_search_records_match(
        records: List[JsonObject], compiled: JsonObject
    ) -> bool:
        """Require native normalization to retain each decision-bearing source URL."""

        search_contract = compiled.get("evidence_search")
        if not isinstance(search_contract, dict):
            return False
        required_sources = search_contract.get("required_sources")
        if not isinstance(required_sources, list) or not required_sources:
            return False

        def normalize_url(value: object) -> str:
            return str(value or "").strip().rstrip("/").lower()

        return all(
            isinstance(source, dict)
            and any(
                isinstance(record, dict)
                and normalize_url(record.get("url"))
                == normalize_url(source.get("url"))
                and record.get("title") == source.get("title")
                and isinstance(record.get("snippet"), str)
                and bool(record["snippet"].strip())
                for record in records
            )
            for source in required_sources
        )

    @classmethod
    def _inventory_evidence_report_is_valid(
        cls,
        report: JsonObject,
        records: List[JsonObject],
        compiled: JsonObject,
    ) -> bool:
        evidence_quality = report.get("evidence_quality")
        run = report.get("run")
        required_sources = compiled.get("evidence_search", {}).get(
            "required_sources", []
        )
        normalized_count = (
            run.get("normalized_result_count")
            if isinstance(run, dict)
            else None
        )
        authoritative_count = (
            run.get("authoritative_result_count")
            if isinstance(run, dict)
            else None
        )
        valid_count = lambda value: isinstance(value, int) and not isinstance(
            value, bool
        )
        return (
            report.get("schema_version") == 1
            and report.get("status") == "completed_with_evidence"
            and report.get("profile") == "deep"
            and report.get("field")
            == {
                "dataset_type": "process",
                "field_path": "processDataSet.exchanges.exchange",
            }
            and isinstance(evidence_quality, dict)
            and evidence_quality.get("sufficient") is True
            and isinstance(required_sources, list)
            and bool(required_sources)
            and valid_count(normalized_count)
            and normalized_count == len(records)
            and valid_count(authoritative_count)
            and len(required_sources)
            <= authoritative_count
            <= normalized_count
            and cls._inventory_search_records_match(records, compiled)
        )

    def plan_inventory_evidence(
        self,
        evidence: JsonObject,
        search_results: JsonObject,
        *,
        command_prefix: Optional[List[str]] = None,
        evidence_source_ref: Optional[JsonObject] = None,
        search_results_source_ref: Optional[JsonObject] = None,
    ) -> JsonObject:
        """Compile and native-normalize a source-bound screening inventory plan."""

        snapshot = self._project(self.events())
        materialization = snapshot.get("process_materialization")
        if (
            not isinstance(materialization, dict)
            or materialization.get("status")
            != "schema_valid_inventory_incomplete"
        ):
            raise ValueError(
                "A schema-valid inventory-incomplete process materialization is "
                "required before inventory evidence planning"
            )
        compiled = compile_inventory_evidence(evidence, evidence_source_ref)
        scope_id = str(materialization.get("scope_id", ""))
        revision = str(materialization.get("revision", ""))
        if (
            compiled.get("scope_id") != scope_id
            or compiled.get("revision") != revision
        ):
            raise ValueError(
                "Inventory evidence scope_id/revision must match the current "
                "process materialization"
            )
        search_source = _verified_json_source(
            search_results,
            search_results_source_ref,
            "inventory_search_results_source_ref",
        )
        prefix = command_prefix or [
            "npm",
            "exec",
            "--yes",
            f"--package={self.TIANGONG_CLI_PACKAGE}",
            "--",
            "tiangong-lca",
        ]
        scope_key = f"{scope_id}:{revision}"
        plan_hash = hashlib.sha256(_json_bytes(compiled)).hexdigest()
        search_hash = hashlib.sha256(_json_bytes(search_results)).hexdigest()
        request = inventory_evidence_search_request(compiled)
        request_hash = hashlib.sha256(_json_bytes(request)).hexdigest()
        evidence_version = hashlib.sha256(
            (
                f"{plan_hash}|{search_hash}|{request_hash}|"
                f"{self.TIANGONG_CLI_PACKAGE}|inventory-evidence-search/v1"
            ).encode("ascii")
        ).hexdigest()[:16]
        activity_base_id = (
            f"inventory-evidence:{scope_key}:{evidence_version}"
        )
        attempt = self._semantic_attempt(activity_base_id)
        activity_id = f"{activity_base_id}:attempt-{attempt}"
        artifact_root = (
            self.workspace
            / "artifacts"
            / "inventory-evidence"
            / f"{scope_id}-{revision}"
            / evidence_version
            / f"attempt-{attempt}"
        )
        input_dir = artifact_root / "inputs"
        evidence_path = input_dir / "inventory-evidence.json"
        plan_path = input_dir / "compiled-inventory-plan.json"
        search_results_path = input_dir / "search-results.json"
        search_request_path = input_dir / "evidence-search-request.json"
        self.record(
            "milestone.started",
            {
                "milestone_id": "source-bound-screening-inventory",
                "title": "编译双路线筛查代理清单证据",
                "status": "running",
                "next_action": (
                    "用 TianGong evidence-search 规范化来源，再保留代理偏差与碳包覆缺口"
                ),
                "terms": [
                    {
                        "term": "筛查代理清单",
                        "explanation": (
                            "用于尽早暴露量级和数据缺口的来源绑定清单；它不是最终性能对齐模型。"
                        ),
                    },
                    {
                        "term": "Exchange",
                        "explanation": (
                            "过程与原材料、能源、排放、产品或副产品之间带方向和数量的连接。"
                        ),
                    },
                ],
            },
            actor="controller",
            idempotency_key=(
                f"milestone:inventory-evidence:{scope_key}:{evidence_version}:started"
            ),
        )
        if self._completed_activity(activity_id) is None:
            input_dir.mkdir(parents=True, exist_ok=True)
            _write_json(evidence_path, compiled["provenance"]["original_input"])
            _write_json(plan_path, compiled)
            _write_json(search_results_path, search_results)
            _write_json(search_request_path, request)
        activity = self.run_activity(
            activity_id=activity_id,
            name="用 TianGong 规范化双路线清单证据",
            skill_ref="process-automated-builder/dataset-evidence-search",
            command=[
                *prefix,
                "dataset",
                "evidence-search",
                "run",
                "--input",
                str(search_request_path),
                "--results",
                str(search_results_path),
                "--out-dir",
                str(artifact_root),
                "--profile",
                "deep",
                "--json",
            ],
            artifact_root=artifact_root,
            expected_outputs=[
                "inputs/inventory-evidence.json",
                "inputs/compiled-inventory-plan.json",
                "inputs/search-results.json",
                "inputs/evidence-search-request.json",
                "outputs/evidence-search-plan.json",
                "outputs/evidence-search-results.jsonl",
                "outputs/evidence-search-report.json",
            ],
            effect="local_write",
        )
        artifacts = {
            artifact["path"]: artifact for artifact in activity["artifacts"]
        }
        report_artifact = artifacts["outputs/evidence-search-report.json"]
        report = self._load_native_json_report(
            report_path=artifact_root / "outputs" / "evidence-search-report.json",
            report_artifact=report_artifact,
            activity_base_id=activity_base_id,
            activity_id=activity_id,
            attempt=attempt,
            scope_key=scope_key,
            gate="inventory-evidence-search",
        )
        normalized_artifact = artifacts[
            "outputs/evidence-search-results.jsonl"
        ]
        try:
            normalized_records = self._load_jsonl_objects(
                artifact_root / "outputs" / "evidence-search-results.jsonl"
            )
            if not normalized_records:
                raise ValueError("evidence-search results contain no records")
        except (OSError, UnicodeError, ValueError) as error:
            self._record_native_semantic_failure(
                activity_base_id=activity_base_id,
                activity_id=activity_id,
                attempt=attempt,
                scope_key=scope_key,
                gate="inventory-evidence-search",
                summary=(
                    "TianGong 清单 evidence-search 规范化结果不是有效 JSONL "
                    f"object 记录：{error}"
                ),
                report_path=normalized_artifact["workspace_path"],
                report_sha256=normalized_artifact["sha256"],
            )
            raise RuntimeError(
                "Native inventory evidence-search results are invalid"
            ) from error
        native_valid = self._inventory_evidence_report_is_valid(
            report, normalized_records, compiled
        )
        if not native_valid:
            self._record_native_semantic_failure(
                activity_base_id=activity_base_id,
                activity_id=activity_id,
                attempt=attempt,
                scope_key=scope_key,
                gate="inventory-evidence-search",
                summary=(
                    "TianGong 清单 evidence-search 未保留合同声明的全部决策来源。"
                ),
                report_path=report_artifact["workspace_path"],
                report_sha256=report_artifact["sha256"],
            )
            raise RuntimeError(
                "Native inventory evidence search did not preserve required sources"
            )
        self._record_native_semantic_acceptance(
            activity_base_id=activity_base_id,
            activity_id=activity_id,
            attempt=attempt,
            scope_key=scope_key,
            gate="inventory-evidence-search",
            report_path=report_artifact["workspace_path"],
            report_sha256=report_artifact["sha256"],
        )
        result = {
            **compiled,
            "plan_path": artifacts[
                "inputs/compiled-inventory-plan.json"
            ]["workspace_path"],
            "plan_sha256": artifacts[
                "inputs/compiled-inventory-plan.json"
            ]["sha256"],
            "native_evidence_search": {
                "status": report["status"],
                "report_path": report_artifact["workspace_path"],
                "report_sha256": report_artifact["sha256"],
                "normalized_results_path": normalized_artifact[
                    "workspace_path"
                ],
                "normalized_results_sha256": normalized_artifact["sha256"],
                "search_results_source": search_source,
            },
            "next_action": (
                "用 TianGong dataset patch apply 把筛查代理 exchange plan 应用到独立 "
                "scenario rows，再运行 validation/QA；不得覆盖性能对齐主模型。"
            ),
        }
        for risk in compiled["risk_register"]:
            self.record(
                "risk.flagged",
                {
                    **risk,
                    "plan_path": result["plan_path"],
                    "plan_sha256": result["plan_sha256"],
                    "search_report_path": report_artifact["workspace_path"],
                    "search_report_sha256": report_artifact["sha256"],
                },
                actor="controller",
                idempotency_key=(
                    f"risk:{risk['risk_id']}:{result['plan_sha256'][:16]}:"
                    f"{report_artifact['sha256'][:16]}"
                ),
            )
        result_version = hashlib.sha256(_json_bytes(result)).hexdigest()[:16]
        self.record(
            "decision.recorded",
            {
                "decision_id": (
                    f"inventory-screening-plan:{scope_key}:{result_version}"
                ),
                "decision_type": "inventory.screening_plan.compiled",
                "scope_id": scope_id,
                "revision": revision,
                "status": result["status"],
                "scientific_comparison_ready": False,
                "plan_path": result["plan_path"],
                "plan_sha256": result["plan_sha256"],
                "search_report_path": report_artifact["workspace_path"],
                "search_report_sha256": report_artifact["sha256"],
            },
            actor="controller",
            idempotency_key=(
                f"decision:inventory-screening-plan:{scope_key}:{result_version}"
            ),
        )
        event = self.record(
            "research.inventory_evidence.planned",
            result,
            actor="controller",
            idempotency_key=(
                f"inventory-evidence:{scope_key}:{result_version}:planned"
            ),
        )
        self.record(
            "milestone.completed",
            {
                "milestone_id": "source-bound-screening-inventory",
                "title": "双路线筛查代理清单已编译并绑定原生证据报告",
                "status": "completed",
                "next_action": result["next_action"],
            },
            actor="controller",
            idempotency_key=(
                f"milestone:inventory-evidence:{scope_key}:{result_version}:completed"
            ),
        )
        self.materialize_views()
        return event["payload"]

    @staticmethod
    def _scenario_patch_report_is_valid(
        report: JsonObject,
        evidence_rows: List[JsonObject],
        compiled_patch: JsonObject,
    ) -> bool:
        patch_sets = compiled_patch.get("patch_sets")
        if not isinstance(patch_sets, list) or len(patch_sets) != 2:
            return False
        operation_count = sum(
            len(patch_set.get("operations", []))
            for patch_set in patch_sets
            if isinstance(patch_set, dict)
        )
        expected_evidence: List[JsonObject] = []
        for patch_index, patch_set in enumerate(patch_sets):
            if not isinstance(patch_set, dict):
                return False
            operations = patch_set.get("operations")
            if not isinstance(operations, list):
                return False
            for operation_index, operation in enumerate(operations):
                if not isinstance(operation, dict):
                    return False
                if operation.get("op") == "test":
                    continue
                expected_evidence.append(
                    {
                        "row_index": patch_set.get("row_index"),
                        "dataset_id": patch_set.get("dataset_id"),
                        "dataset_version": patch_set.get("dataset_version"),
                        "patch_index": patch_index,
                        "operation_index": operation_index,
                        "op": operation.get("op"),
                        "path": operation.get("path"),
                        "basis": operation.get("basis"),
                        "evidence": operation.get("evidence"),
                        "resolution": operation.get("resolution"),
                    }
                )
        if (
            report.get("schema_version") != 1
            or report.get("status") != "completed"
            or report.get("row_count") != 2
            or report.get("patch_count") != 2
            or report.get("operation_count") != operation_count
            or report.get("applied_operation_count") != len(expected_evidence)
            or report.get("evidence_count") != len(expected_evidence)
            or report.get("closed_action_item_count") != 0
            or report.get("blockers") != []
            or len(evidence_rows) != len(expected_evidence)
        ):
            return False
        for actual, expected in zip(evidence_rows, expected_evidence):
            if not isinstance(actual, dict) or any(
                actual.get(key) != value for key, value in expected.items()
            ):
                return False
            if actual.get("closes_action_items") != []:
                return False
        return True

    @staticmethod
    def _tool_invocation_sha256(command_prefix: List[str]) -> str:
        if not command_prefix or not all(
            isinstance(part, str) and part for part in command_prefix
        ):
            raise ValueError("command_prefix must be a non-empty list of strings")
        return hashlib.sha256(
            _json_bytes({"command_prefix": command_prefix})
        ).hexdigest()

    @staticmethod
    def _scenario_qa_matches_expectations(
        report: JsonObject,
        findings: List[JsonObject],
        profile: JsonObject,
        scenario_ref: JsonObject,
    ) -> bool:
        totals = report.get("totals")
        expected_totals = scenario_ref.get("expected_qa_totals")
        if not isinstance(totals, dict) or not isinstance(expected_totals, dict):
            return False
        for native_key, expected_key in (
            ("raw_input", "raw_input"),
            ("product_plus_byproduct_plus_waste", "product_output"),
            ("energy_excluded", "energy_excluded"),
        ):
            actual = totals.get(native_key)
            expected = expected_totals.get(expected_key)
            if (
                isinstance(actual, bool)
                or not isinstance(actual, (int, float))
                or isinstance(expected, bool)
                or not isinstance(expected, (int, float))
                or not math.isclose(
                    float(actual),
                    float(expected),
                    rel_tol=1e-12,
                    abs_tol=1e-12,
                )
            ):
                return False
        expected_raw = float(expected_totals["raw_input"])
        expected_output = float(expected_totals["product_output"])
        expects_balance_finding = (
            expected_raw > 0
            and abs(expected_output - expected_raw) / expected_raw > 0.05
        )
        balance_finding_count = sum(
            isinstance(finding, dict)
            and finding.get("code") == "process_material_balance_deviation"
            for finding in findings
        )
        return (
            profile.get("has_positive_input") is True
            and profile.get("has_positive_output") is True
            and profile.get("positive_input_exchange_count")
            == scenario_ref.get("positive_input_exchange_count")
            and profile.get("positive_output_exchange_count")
            == scenario_ref.get("positive_output_exchange_count")
            and balance_finding_count == (1 if expects_balance_finding else 0)
        )

    @staticmethod
    def _process_qa_target_is_valid(
        materialization_summary: JsonObject,
        *,
        expected_process_id: str,
        expected_version: str,
        expected_input_path: Path,
    ) -> bool:
        items = materialization_summary.get("items")
        if not isinstance(items, list) or len(items) != 1:
            return False
        item = items[0]
        if not isinstance(item, dict):
            return False
        source_rows_file = materialization_summary.get("source_rows_file")
        process_file = item.get("file")
        if not isinstance(source_rows_file, str) or not isinstance(
            process_file, str
        ):
            return False
        expected_filename = f"{expected_process_id}__{expected_version}.json"
        return (
            materialization_summary.get("input_row_count") == 1
            and materialization_summary.get("materialized_process_count") == 1
            and materialization_summary.get("duplicate_input_rows_collapsed") == 0
            and Path(source_rows_file).resolve() == expected_input_path.resolve()
            and item.get("process_key")
            == f"{expected_process_id}@{expected_version}"
            and Path(process_file).name == expected_filename
        )

    def _sync_screening_scenario_qa_risk(
        self,
        *,
        scope_key: str,
        total_findings: int,
        total_blockers: int,
        route_qa: List[JsonObject],
        result_version: str,
    ) -> None:
        risk_id = f"screening-scenario-native-qa:{scope_key}"
        current_risk_ids = {
            risk.get("risk_id")
            for risk in self._project(self.events())["unresolved_risks"]
        }
        if total_findings:
            self.record(
                "risk.flagged",
                {
                    "risk_id": risk_id,
                    "severity": "high" if total_blockers else "medium",
                    "summary": (
                        f"两条隔离场景共有 {total_findings} 条原生 QA finding、"
                        f"{total_blockers} 个 blocker；finding 已逐路线保留。"
                    ),
                    "route_qa": route_qa,
                },
                actor="controller",
                idempotency_key=(
                    f"risk:screening-scenario-native-qa:{scope_key}:"
                    f"{result_version}"
                ),
            )
        elif risk_id in current_risk_ids:
            self.record(
                "risk.resolved",
                {
                    "risk_id": risk_id,
                    "resolution": "native_scenario_qa_findings_cleared",
                    "result_version": result_version,
                },
                actor="controller",
                idempotency_key=(
                    f"risk:{risk_id}:resolved:{result_version}"
                ),
            )

    @staticmethod
    def _scenario_status_and_next_action(
        *, total_findings: int, total_blockers: int
    ) -> tuple[str, str]:
        if total_blockers:
            return (
                "screening_scenarios_qa_blocked",
                "先修复逐路线 TianGong Process QA blocker，再以新 attempt 重跑 "
                "2/2 validation 与逐路线 QA；不得越过 blocker 进入身份治理。",
            )
        status = (
            "screening_scenarios_schema_valid_qa_needs_review"
            if total_findings
            else "screening_scenarios_schema_valid_qa_passed"
        )
        return (
            status,
            "对所有 provisional flow/source 运行 TianGong 原生身份预检，"
            "在不改变来源绑定数量的前提下替换本地引用；并按科学缺口优先级继续补证据。",
        )

    def _record_screening_scenario_milestone(
        self,
        *,
        scope_key: str,
        result_version: str,
        total_blockers: int,
        next_action: str,
    ) -> None:
        if total_blockers:
            self.record(
                "milestone.started",
                {
                    "milestone_id": "native-screening-scenario-qa-repair",
                    "title": "隔离筛查场景需要修复原生 QA blocker",
                    "status": "running",
                    "next_action": next_action,
                },
                actor="controller",
                idempotency_key=(
                    f"milestone:inventory-scenario-qa-repair:{scope_key}:"
                    f"{result_version}:started"
                ),
            )
            return
        self.record(
            "milestone.completed",
            {
                "milestone_id": "native-screening-scenario-patch",
                "title": "双路线隔离筛查场景已完成原生写入与逐路线 QA",
                "status": "completed",
                "next_action": next_action,
            },
            actor="controller",
            idempotency_key=(
                f"milestone:inventory-scenario-patch:{scope_key}:"
                f"{result_version}:completed"
            ),
        )

    def apply_inventory_scenarios(
        self, *, command_prefix: Optional[List[str]] = None
    ) -> JsonObject:
        """Patch source-bound exchanges into isolated rows and run native QA."""

        snapshot = self._project(self.events())
        materialization = snapshot.get("process_materialization")
        inventory_plan = snapshot.get("inventory_evidence_plan")
        if (
            not isinstance(materialization, dict)
            or materialization.get("status")
            != "schema_valid_inventory_incomplete"
        ):
            raise ValueError(
                "A schema-valid inventory-incomplete process materialization is required"
            )
        if (
            not isinstance(inventory_plan, dict)
            or inventory_plan.get("status") != "screening_proxy_plan_ready"
        ):
            raise ValueError("A source-bound screening inventory plan is required")
        scope_id = str(materialization.get("scope_id", ""))
        revision = str(materialization.get("revision", ""))
        if (
            inventory_plan.get("scope_id") != scope_id
            or inventory_plan.get("revision") != revision
        ):
            raise ValueError(
                "Inventory plan scope_id/revision must match process materialization"
            )
        scope_key = f"{scope_id}:{revision}"
        process_refs = materialization.get("processes")
        if not isinstance(process_refs, list) or len(process_refs) != 2:
            raise ValueError("Exactly two registered base processes are required")

        base_processes: List[JsonObject] = []
        for process_ref in process_refs:
            if not isinstance(process_ref, dict):
                raise ValueError("Registered base process references must be objects")
            process_path = (self.workspace / str(process_ref.get("process_path", ""))).resolve()
            try:
                process_path.relative_to(self.workspace)
            except ValueError as error:
                raise ValueError("Registered process path escaped project workspace") from error
            process_bytes = process_path.read_bytes()
            process_sha256 = hashlib.sha256(process_bytes).hexdigest()
            if process_sha256 != process_ref.get("process_sha256"):
                raise RuntimeError(
                    f"Registered process hash drifted for route '{process_ref.get('route_id')}'"
                )
            process = json.loads(process_bytes)
            if not isinstance(process, dict):
                raise RuntimeError("Registered base process is not a JSON object")
            base_processes.append(process)

        plan_path = (self.workspace / str(inventory_plan.get("plan_path", ""))).resolve()
        try:
            plan_path.relative_to(self.workspace)
        except ValueError as error:
            raise ValueError("Registered inventory plan path escaped project workspace") from error
        plan_bytes = plan_path.read_bytes()
        if hashlib.sha256(plan_bytes).hexdigest() != inventory_plan.get("plan_sha256"):
            raise RuntimeError("Registered inventory plan hash drifted")

        compiled_patch = compile_screening_scenario_patch(
            base_processes,
            [
                {
                    "route_id": process_ref["route_id"],
                    "process_id": process_ref["process_id"],
                }
                for process_ref in process_refs
            ],
            inventory_plan,
        )
        prefix = command_prefix or [
            "npm",
            "exec",
            "--yes",
            f"--package={self.TIANGONG_CLI_PACKAGE}",
            "--",
            "tiangong-lca",
        ]
        tool_invocation_sha256 = self._tool_invocation_sha256(prefix)
        base_rows_sha256 = hashlib.sha256(_jsonl_bytes(base_processes)).hexdigest()
        patch_sha256 = hashlib.sha256(_json_bytes(compiled_patch)).hexdigest()
        scenario_version = hashlib.sha256(
            (
                f"{base_rows_sha256}|{inventory_plan['plan_sha256']}|"
                f"{inventory_plan['native_evidence_search']['report_sha256']}|"
                f"{patch_sha256}|{self.TIANGONG_CLI_PACKAGE}|"
                f"{SCENARIO_PATCH_CONTRACT}|{tool_invocation_sha256}"
            ).encode("ascii")
        ).hexdigest()[:16]
        activity_base_id = f"inventory-scenario-patch:{scope_key}:{scenario_version}"
        attempt = self._semantic_attempt(activity_base_id)
        activity_id = f"{activity_base_id}:attempt-{attempt}"
        artifact_root = (
            self.workspace
            / "artifacts"
            / "inventory-scenarios"
            / f"{scope_id}-{revision}"
            / scenario_version
            / f"attempt-{attempt}"
        )
        inputs = artifact_root / "inputs"
        outputs = artifact_root / "outputs"
        base_rows_path = inputs / "base-processes.jsonl"
        plan_copy_path = inputs / "compiled-inventory-plan.json"
        patch_path = inputs / "scenario-patches.json"
        flow_registry_path = inputs / "provisional-flow-registry.json"
        source_registry_path = inputs / "provisional-source-registry.json"
        patched_rows_path = outputs / "patched-scenario-processes.jsonl"
        self.record(
            "milestone.started",
            {
                "milestone_id": "native-screening-scenario-patch",
                "title": "用 TianGong 原生 patch 写入隔离筛查场景",
                "status": "running",
                "next_action": (
                    "对克隆场景逐条写入 exchange，再做 2/2 schema validation 与逐路线 Process QA"
                ),
                "terms": [
                    {
                        "term": "隔离筛查场景",
                        "explanation": (
                            "从性能对齐主过程复制出的独立代理过程；可用于验证清单结构，"
                            "但不会把代理数据伪装成最终模型。"
                        ),
                    },
                    {
                        "term": "流身份预检",
                        "explanation": (
                            "在正式连接供应链前，判断一个 flow 应复用已有对象还是创建新对象。"
                        ),
                    },
                ],
            },
            actor="controller",
            idempotency_key=(
                f"milestone:inventory-scenario-patch:{scope_key}:{scenario_version}:started"
            ),
        )
        if self._completed_activity(activity_id) is None:
            inputs.mkdir(parents=True, exist_ok=True)
            base_rows_path.write_bytes(_jsonl_bytes(base_processes))
            plan_copy_path.write_bytes(plan_bytes)
            _write_json(patch_path, compiled_patch)
            _write_json(
                flow_registry_path,
                {"flows": compiled_patch["flow_registry"]},
            )
            _write_json(
                source_registry_path,
                {"sources": compiled_patch["source_registry"]},
            )
        patch_activity = self.run_activity(
            activity_id=activity_id,
            name="用 TianGong dataset patch apply 生成隔离筛查场景",
            skill_ref="process-automated-builder/dataset-patch-apply",
            command=[
                *prefix,
                "dataset",
                "patch",
                "apply",
                "--input",
                str(base_rows_path),
                "--patch",
                str(patch_path),
                "--out",
                str(patched_rows_path),
                "--out-dir",
                str(artifact_root),
                "--json",
            ],
            artifact_root=artifact_root,
            expected_outputs=[
                "inputs/base-processes.jsonl",
                "inputs/compiled-inventory-plan.json",
                "inputs/scenario-patches.json",
                "inputs/provisional-flow-registry.json",
                "inputs/provisional-source-registry.json",
                "outputs/patched-scenario-processes.jsonl",
                "outputs/patch-evidence.jsonl",
                "outputs/dataset-patch-apply-report.json",
            ],
            effect="local_write",
        )
        patch_artifacts = {
            artifact["path"]: artifact
            for artifact in patch_activity.get("artifacts", [])
        }
        patch_report_artifact = patch_artifacts[
            "outputs/dataset-patch-apply-report.json"
        ]
        patch_report = self._load_native_json_report(
            report_path=outputs / "dataset-patch-apply-report.json",
            report_artifact=patch_report_artifact,
            activity_base_id=activity_base_id,
            activity_id=activity_id,
            attempt=attempt,
            scope_key=scope_key,
            gate="dataset-patch-apply",
        )
        try:
            patch_evidence = self._load_jsonl_objects(
                outputs / "patch-evidence.jsonl"
            )
            scenario_rows = self._load_jsonl_objects(patched_rows_path)
        except (OSError, UnicodeError, ValueError) as error:
            self._record_native_semantic_failure(
                activity_base_id=activity_base_id,
                activity_id=activity_id,
                attempt=attempt,
                scope_key=scope_key,
                gate="dataset-patch-apply",
                summary=f"TianGong patch 输出不是有效 JSONL：{error}",
                report_path=patch_report_artifact["workspace_path"],
                report_sha256=patch_report_artifact["sha256"],
            )
            raise RuntimeError("Native scenario patch output is invalid") from error
        if not (
            self._scenario_patch_report_is_valid(
                patch_report, patch_evidence, compiled_patch
            )
            and screening_scenario_rows_are_valid(
                scenario_rows, compiled_patch
            )
        ):
            self._record_native_semantic_failure(
                activity_base_id=activity_base_id,
                activity_id=activity_id,
                attempt=attempt,
                scope_key=scope_key,
                gate="dataset-patch-apply",
                summary=(
                    "TianGong patch 报告、逐操作证据或隔离场景内容未匹配编译合同。"
                ),
                report_path=patch_report_artifact["workspace_path"],
                report_sha256=patch_report_artifact["sha256"],
            )
            raise RuntimeError("Native scenario patch failed semantic validation")
        self._record_native_semantic_acceptance(
            activity_base_id=activity_base_id,
            activity_id=activity_id,
            attempt=attempt,
            scope_key=scope_key,
            gate="dataset-patch-apply",
            report_path=patch_report_artifact["workspace_path"],
            report_sha256=patch_report_artifact["sha256"],
        )

        patched_rows_artifact = patch_artifacts[
            "outputs/patched-scenario-processes.jsonl"
        ]
        validation_version = hashlib.sha256(
            (
                f"{patched_rows_artifact['sha256']}|{self.TIANGONG_CLI_PACKAGE}|"
                "screening-scenario-dataset-validation/v1|"
                f"{tool_invocation_sha256}"
            ).encode("ascii")
        ).hexdigest()[:16]
        validation_base_id = (
            f"inventory-scenario-validation:{scope_key}:{validation_version}"
        )
        validation_attempt = self._semantic_attempt(validation_base_id)
        validation_activity_id = (
            f"{validation_base_id}:attempt-{validation_attempt}"
        )
        validation_root = (
            artifact_root
            / "dataset-validation"
            / validation_version
            / f"attempt-{validation_attempt}"
        )
        validation_input = validation_root / "inputs" / "scenario-processes.jsonl"
        if self._completed_activity(validation_activity_id) is None:
            validation_input.parent.mkdir(parents=True, exist_ok=True)
            validation_input.write_bytes(patched_rows_path.read_bytes())
        validation_activity = self.run_activity(
            activity_id=validation_activity_id,
            name="验证双路线隔离筛查场景 TIDAS schema",
            skill_ref="tidas-data-import/dataset-validate",
            command=[
                *prefix,
                "dataset",
                "validate",
                "--input",
                str(validation_input),
                "--type",
                "process",
                "--out-dir",
                str(validation_root),
                "--json",
            ],
            artifact_root=validation_root,
            expected_outputs=[
                "inputs/scenario-processes.jsonl",
                "outputs/validation-report.json",
                "outputs/valid-rows.jsonl",
                "outputs/invalid-rows.jsonl",
            ],
            effect="local_write",
            accepted_exit_codes={0, 1},
        )
        validation_artifacts = {
            artifact["path"]: artifact
            for artifact in validation_activity.get("artifacts", [])
        }
        validation_report_artifact = validation_artifacts[
            "outputs/validation-report.json"
        ]
        validation_report = self._load_native_json_report(
            report_path=validation_root / "outputs" / "validation-report.json",
            report_artifact=validation_report_artifact,
            activity_base_id=validation_base_id,
            activity_id=validation_activity_id,
            attempt=validation_attempt,
            scope_key=scope_key,
            gate="scenario-dataset-validate",
        )
        validation_counts = validation_report.get("counts")
        validation_rows = validation_report.get("rows")
        scenario_ids = {
            row["scenario_process_id"]
            for row in compiled_patch["scenario_processes"]
        }
        try:
            valid_rows = self._load_jsonl_objects(
                validation_root / "outputs" / "valid-rows.jsonl"
            )
            invalid_rows = self._load_jsonl_objects(
                validation_root / "outputs" / "invalid-rows.jsonl"
            )
        except (OSError, UnicodeError, ValueError):
            valid_rows = []
            invalid_rows = [{}]
        validation_valid = (
            validation_report.get("requested_type") == "process"
            and validation_report.get("status") == "completed"
            and isinstance(validation_counts, dict)
            and validation_counts.get("total") == 2
            and validation_counts.get("valid") == 2
            and validation_counts.get("invalid") == 0
            and isinstance(validation_rows, list)
            and len(validation_rows) == 2
            and {
                row.get("id")
                for row in validation_rows
                if isinstance(row, dict)
                and row.get("type") == "process"
                and row.get("status") == "valid"
                and row.get("issue_count") == 0
                and row.get("issues") == []
            }
            == scenario_ids
            and len(valid_rows) == 2
            and self._process_rows_match(scenario_rows, valid_rows)
            and invalid_rows == []
        )
        if not validation_valid:
            self._record_native_semantic_failure(
                activity_base_id=validation_base_id,
                activity_id=validation_activity_id,
                attempt=validation_attempt,
                scope_key=scope_key,
                gate="scenario-dataset-validate",
                summary="隔离筛查场景未得到结构完整且 2/2 valid 的原生报告。",
                report_path=validation_report_artifact["workspace_path"],
                report_sha256=validation_report_artifact["sha256"],
            )
            raise RuntimeError("Screening scenarios failed dataset validation")
        self._record_native_semantic_acceptance(
            activity_base_id=validation_base_id,
            activity_id=validation_activity_id,
            attempt=validation_attempt,
            scope_key=scope_key,
            gate="scenario-dataset-validate",
            report_path=validation_report_artifact["workspace_path"],
            report_sha256=validation_report_artifact["sha256"],
        )

        rows_by_id = {
            self._process_payload_id(row): row for row in scenario_rows
        }
        route_qa: List[JsonObject] = []
        qa_expected_outputs = [
            "inputs/scenario-process.jsonl",
            "qa-input-summary.json",
            "qa-input/materialization-summary.json",
            "one_flow_rerun_timing.md",
            "one_flow_rerun_qa_v2_1_zh.md",
            "one_flow_rerun_qa_v2_1_en.md",
            "flow_unit_issue_log.md",
            "qa_summary_v2_1.json",
            "process-qa-rule-findings.jsonl",
            "process-qa-ruleset-gate.json",
            "process-qa-report.json",
        ]
        for scenario_ref in compiled_patch["scenario_processes"]:
            route_id = scenario_ref["route_id"]
            scenario_id = scenario_ref["scenario_process_id"]
            scenario_row = rows_by_id.get(scenario_id)
            if not isinstance(scenario_row, dict):
                raise RuntimeError(f"Patched scenario row missing for route '{route_id}'")
            row_sha256 = hashlib.sha256(_json_bytes(scenario_row)).hexdigest()
            qa_version = hashlib.sha256(
                (
                    f"{row_sha256}|{self.TIANGONG_CLI_PACKAGE}|"
                    f"{PROCESS_QA_LOGIC_VERSION}|{PROCESS_QA_RULESET_ID}/"
                    f"{PROCESS_QA_RULESET_VERSION}|per-route-v1"
                    f"|{tool_invocation_sha256}"
                ).encode("ascii")
            ).hexdigest()[:16]
            qa_base_id = f"inventory-scenario-qa:{scope_key}:{route_id}:{qa_version}"
            qa_attempt = self._semantic_attempt(qa_base_id)
            qa_activity_id = f"{qa_base_id}:attempt-{qa_attempt}"
            qa_root = (
                artifact_root
                / "process-qa"
                / route_id
                / qa_version
                / f"attempt-{qa_attempt}"
            )
            qa_input = qa_root / "inputs" / "scenario-process.jsonl"
            if self._completed_activity(qa_activity_id) is None:
                qa_input.parent.mkdir(parents=True, exist_ok=True)
                qa_input.write_bytes(_jsonl_bytes([scenario_row]))
            qa_activity = self.run_activity(
                activity_id=qa_activity_id,
                name=f"运行 {route_id} 隔离筛查场景 Process QA",
                skill_ref="lifecycleinventory-review/process",
                command=[
                    *prefix,
                    "qa",
                    "process",
                    "--rows-file",
                    str(qa_input),
                    "--out-dir",
                    str(qa_root),
                    "--logic-version",
                    PROCESS_QA_LOGIC_VERSION,
                    "--json",
                ],
                artifact_root=qa_root,
                expected_outputs=qa_expected_outputs,
                effect="local_write",
            )
            qa_artifacts = {
                artifact["path"]: artifact
                for artifact in qa_activity.get("artifacts", [])
            }
            qa_report_artifact = qa_artifacts["process-qa-report.json"]
            qa_report = self._load_native_json_report(
                report_path=qa_root / "process-qa-report.json",
                report_artifact=qa_report_artifact,
                activity_base_id=qa_base_id,
                activity_id=qa_activity_id,
                attempt=qa_attempt,
                scope_key=scope_key,
                gate="scenario-process-qa",
                route_id=route_id,
            )
            ruleset_artifact = qa_artifacts["process-qa-ruleset-gate.json"]
            ruleset_payload = self._load_native_json_report(
                report_path=qa_root / "process-qa-ruleset-gate.json",
                report_artifact=ruleset_artifact,
                activity_base_id=qa_base_id,
                activity_id=qa_activity_id,
                attempt=qa_attempt,
                scope_key=scope_key,
                gate="scenario-process-qa",
                route_id=route_id,
            )
            materialization_artifact = qa_artifacts[
                "qa-input/materialization-summary.json"
            ]
            materialization_summary = self._load_native_json_report(
                report_path=qa_root
                / "qa-input"
                / "materialization-summary.json",
                report_artifact=materialization_artifact,
                activity_base_id=qa_base_id,
                activity_id=qa_activity_id,
                attempt=qa_attempt,
                scope_key=scope_key,
                gate="scenario-process-qa",
                route_id=route_id,
            )
            try:
                findings = self._load_jsonl_objects(
                    qa_root / "process-qa-rule-findings.jsonl"
                )
            except (OSError, UnicodeError, ValueError):
                findings = [{}]
            profile = self._process_inventory_profiles([scenario_row])[0]
            qa_valid = self._process_qa_report_is_valid(
                qa_report,
                findings,
                ruleset_payload,
                {scenario_id},
            )
            if not (
                qa_valid
                and self._process_qa_target_is_valid(
                    materialization_summary,
                    expected_process_id=scenario_id,
                    expected_version=scenario_ref["dataset_version"],
                    expected_input_path=qa_input,
                )
                and self._scenario_qa_matches_expectations(
                    qa_report, findings, profile, scenario_ref
                )
            ):
                self._record_native_semantic_failure(
                    activity_base_id=qa_base_id,
                    activity_id=qa_activity_id,
                    attempt=qa_attempt,
                    scope_key=scope_key,
                    gate="scenario-process-qa",
                    route_id=route_id,
                    summary=(
                        f"{route_id} 原生 QA 报告、目标绑定或路线汇总不符合预期。"
                    ),
                    report_path=qa_report_artifact["workspace_path"],
                    report_sha256=qa_report_artifact["sha256"],
                )
                raise RuntimeError(f"Scenario Process QA failed for route '{route_id}'")
            self._record_native_semantic_acceptance(
                activity_base_id=qa_base_id,
                activity_id=qa_activity_id,
                attempt=qa_attempt,
                scope_key=scope_key,
                gate="scenario-process-qa",
                route_id=route_id,
                report_path=qa_report_artifact["workspace_path"],
                report_sha256=qa_report_artifact["sha256"],
            )
            totals = qa_report["totals"]
            route_qa.append(
                {
                    "route_id": route_id,
                    "scenario_process_id": scenario_id,
                    "status": qa_report["status"],
                    "gate_status": qa_report["ruleset_gate"]["status"],
                    "finding_count": qa_report["rule_finding_count"],
                    "blocker_count": qa_report["blocker_count"],
                    "raw_input": totals["raw_input"],
                    "product_output": totals[
                        "product_plus_byproduct_plus_waste"
                    ],
                    "energy_excluded": totals["energy_excluded"],
                    "positive_input_exchange_count": profile[
                        "positive_input_exchange_count"
                    ],
                    "positive_output_exchange_count": profile[
                        "positive_output_exchange_count"
                    ],
                    "has_positive_input": profile["has_positive_input"],
                    "has_positive_output": profile["has_positive_output"],
                    "report_path": qa_report_artifact["workspace_path"],
                    "report_sha256": qa_report_artifact["sha256"],
                    "findings_path": qa_artifacts[
                        "process-qa-rule-findings.jsonl"
                    ]["workspace_path"],
                    "ruleset_gate_path": ruleset_artifact["workspace_path"],
                }
            )

        total_findings = sum(row["finding_count"] for row in route_qa)
        total_blockers = sum(row["blocker_count"] for row in route_qa)
        for process_ref in process_refs:
            process_path = self.workspace / process_ref["process_path"]
            if (
                hashlib.sha256(process_path.read_bytes()).hexdigest()
                != process_ref["process_sha256"]
            ):
                raise RuntimeError(
                    "A performance-aligned base process changed during scenario patching"
                )
        status, next_action = self._scenario_status_and_next_action(
            total_findings=total_findings,
            total_blockers=total_blockers,
        )
        result = {
            "schema_version": 1,
            "contract": SCENARIO_PATCH_CONTRACT,
            "scope_id": scope_id,
            "revision": revision,
            "status": status,
            "scenario_kind": compiled_patch["scenario_kind"],
            "scientific_comparison_ready": False,
            "flow_identity_gate": compiled_patch["flow_identity_gate"],
            "source_identity_gate": compiled_patch["source_identity_gate"],
            "tool_invocation_sha256": tool_invocation_sha256,
            "base_processes": [
                {
                    "route_id": row["route_id"],
                    "process_id": row["process_id"],
                    "process_path": row["process_path"],
                    "process_sha256": row["process_sha256"],
                }
                for row in process_refs
            ],
            "scenario_processes": compiled_patch["scenario_processes"],
            "flow_count": len(compiled_patch["flow_registry"]),
            "source_count": len(compiled_patch["source_registry"]),
            "patch_apply": {
                "status": patch_report["status"],
                "operation_count": patch_report["operation_count"],
                "applied_operation_count": patch_report[
                    "applied_operation_count"
                ],
                "evidence_count": patch_report["evidence_count"],
                "patch_path": patch_artifacts[
                    "inputs/scenario-patches.json"
                ]["workspace_path"],
                "patch_sha256": patch_artifacts[
                    "inputs/scenario-patches.json"
                ]["sha256"],
                "report_path": patch_report_artifact["workspace_path"],
                "report_sha256": patch_report_artifact["sha256"],
                "evidence_path": patch_artifacts[
                    "outputs/patch-evidence.jsonl"
                ]["workspace_path"],
                "evidence_sha256": patch_artifacts[
                    "outputs/patch-evidence.jsonl"
                ]["sha256"],
            },
            "scenario_rows_path": patched_rows_artifact["workspace_path"],
            "scenario_rows_sha256": patched_rows_artifact["sha256"],
            "flow_registry_path": patch_artifacts[
                "inputs/provisional-flow-registry.json"
            ]["workspace_path"],
            "flow_registry_sha256": patch_artifacts[
                "inputs/provisional-flow-registry.json"
            ]["sha256"],
            "source_registry_path": patch_artifacts[
                "inputs/provisional-source-registry.json"
            ]["workspace_path"],
            "source_registry_sha256": patch_artifacts[
                "inputs/provisional-source-registry.json"
            ]["sha256"],
            "dataset_validation": {
                "status": validation_report["status"],
                "total": validation_counts["total"],
                "valid": validation_counts["valid"],
                "invalid": validation_counts["invalid"],
                "report_path": validation_report_artifact["workspace_path"],
                "report_sha256": validation_report_artifact["sha256"],
            },
            "route_qa": route_qa,
            "qa_finding_count": total_findings,
            "qa_blocker_count": total_blockers,
            "next_action": next_action,
        }
        result_version = hashlib.sha256(_json_bytes(result)).hexdigest()[:16]
        self.record(
            "risk.flagged",
            {
                "risk_id": f"screening-scenario-identity:{scope_key}",
                "severity": "medium",
                "summary": (
                    f"隔离场景中的 {result['flow_count']} 个 flow 与 {result['source_count']} 个 source "
                    "目前使用确定性本地 UUID；在完成原生身份预检前不得连接正式供应链。"
                ),
                "flow_registry_path": result["flow_registry_path"],
                "source_registry_path": result["source_registry_path"],
            },
            actor="controller",
            idempotency_key=(
                f"risk:screening-scenario-identity:{scope_key}:{result_version}"
            ),
        )
        self.record(
            "risk.flagged",
            {
                "risk_id": f"screening-scenario-scientific-boundary:{scope_key}",
                "severity": "high",
                "summary": (
                    "隔离场景已经结构可计算，但仍是未包覆路线核心代理；"
                    "不得把 schema/QA 通过误读为可比较 LCIA 或性能对齐结论。"
                ),
                "scenario_rows_path": result["scenario_rows_path"],
                "scenario_rows_sha256": result["scenario_rows_sha256"],
            },
            actor="controller",
            idempotency_key=(
                f"risk:screening-scenario-scientific-boundary:{scope_key}:"
                f"{result_version}"
            ),
        )
        self._sync_screening_scenario_qa_risk(
            scope_key=scope_key,
            total_findings=total_findings,
            total_blockers=total_blockers,
            route_qa=route_qa,
            result_version=result_version,
        )
        self.record(
            "decision.recorded",
            {
                "decision_id": f"screening-scenario-patch:{scope_key}:{result_version}",
                "decision_type": "inventory.screening_scenarios.native_patched",
                "status": status,
                "scientific_comparison_ready": False,
                "patch_report_path": result["patch_apply"]["report_path"],
                "patch_report_sha256": result["patch_apply"]["report_sha256"],
                "scenario_rows_path": result["scenario_rows_path"],
                "scenario_rows_sha256": result["scenario_rows_sha256"],
            },
            actor="controller",
            idempotency_key=(
                f"decision:screening-scenario-patch:{scope_key}:{result_version}"
            ),
        )
        event = self.record(
            "research.inventory_scenarios.validated",
            result,
            actor="controller",
            idempotency_key=(
                f"inventory-scenarios:{scope_key}:{result_version}:validated"
            ),
        )
        self._record_screening_scenario_milestone(
            scope_key=scope_key,
            result_version=result_version,
            total_blockers=total_blockers,
            next_action=next_action,
        )
        self.materialize_views()
        return event["payload"]

    @staticmethod
    def _identity_report_matches_request(
        report: JsonObject, request: JsonObject
    ) -> bool:
        target = report.get("target")
        requested = request.get("target")
        if not isinstance(target, dict) or not isinstance(requested, dict):
            return False
        fields = target.get("fields")
        if not isinstance(fields, dict):
            return False
        names = target.get("names")
        categories = fields.get("categories")
        reference_flow_ids = fields.get("reference_flow_ids")
        reference_flow_names = fields.get("reference_flow_names")
        if not all(
            isinstance(value, list)
            for value in (
                names,
                categories,
                reference_flow_ids,
                reference_flow_names,
            )
        ):
            return False
        if not all(
            isinstance(item, str)
            for values in (
                names,
                categories,
                reference_flow_ids,
                reference_flow_names,
            )
            for item in values
        ):
            return False
        checks = [
            target.get("id") == requested.get("id"),
            requested.get("name") in names,
            reference_flow_ids == [requested.get("reference_flow_id")],
            reference_flow_names == [requested.get("reference_flow_name")],
            fields.get("operation") == requested.get("operation"),
            fields.get("quantitative_reference")
            == requested.get("quantitative_reference"),
            fields.get("geography") == requested.get("geography"),
            str(fields.get("time")) == str(requested.get("reference_year")),
            fields.get("technology_route")
            == requested.get("technology_route"),
            fields.get("system_boundary") == requested.get("system_boundary"),
            fields.get("provider_role") == requested.get("provider_role"),
            set(categories) == set(requested.get("classification", [])),
        ]
        return all(checks)

    @staticmethod
    def _flow_identity_report_matches_request(
        report: JsonObject,
        request: JsonObject,
        request_path: Path,
        candidate_rows: List[JsonObject],
        candidate_sources: List[JsonObject],
        report_path: Path,
        candidates_path: Path,
        candidate_sources_path: Path,
    ) -> bool:
        target = report.get("target")
        requested = request.get("target")
        if not isinstance(target, dict) or not isinstance(requested, dict):
            return False
        names = target.get("names")
        fields = target.get("fields")
        input_path = report.get("input_path")
        blockers = report.get("blockers")
        decision = report.get("decision")
        status = report.get("status")
        automatic_decisions = {
            "reuse",
            "update_same_row",
            "version_bump",
            "create_new",
        }
        status_consistent = (
            status == "passed"
            and decision in automatic_decisions
            and blockers == []
        ) or (
            status == "blocked"
            and isinstance(blockers, list)
            and (len(blockers) > 0 or decision == "block_duplicate")
        ) or (
            status == "needs_review"
            and decision == "manual_review"
            and blockers == []
        )
        remote_config = request.get("remote_candidate_search")
        remote_requested = (
            isinstance(remote_config, dict)
            and remote_config.get("enabled") is True
        )
        remote_coverage_present = any(
            isinstance(source, dict) and source.get("kind") == "remote_search"
            for source in candidate_sources
        )
        files = report.get("files")
        files_match = (
            isinstance(files, dict)
            and isinstance(files.get("identity_decision"), str)
            and Path(files["identity_decision"]).resolve() == report_path.resolve()
            and isinstance(files.get("candidates"), str)
            and Path(files["candidates"]).resolve() == candidates_path.resolve()
            and isinstance(files.get("candidate_sources"), str)
            and Path(files["candidate_sources"]).resolve()
            == candidate_sources_path.resolve()
        )
        return (
            target.get("id") == requested.get("id")
            and names == [requested.get("name")]
            and isinstance(fields, dict)
            and fields.get("type_of_dataset")
            == requested.get("type_of_dataset")
            and fields.get("flow_property")
            == requested.get("flow_property")
            and fields.get("reference_unit")
            == requested.get("reference_unit")
            and isinstance(input_path, str)
            and Path(input_path).resolve() == request_path.resolve()
            and report.get("candidates") == candidate_rows
            and report.get("candidate_sources") == candidate_sources
            and status_consistent
            and (not remote_requested or remote_coverage_present)
            and files_match
        )

    def preflight_inventory_identities(
        self,
        *,
        command_prefix: Optional[List[str]] = None,
        remote_candidates: bool = False,
    ) -> JsonObject:
        """Run native flow identity preflight and retain the source capability gap."""

        snapshot = self._project(self.events())
        scenarios = snapshot.get("inventory_scenarios")
        if (
            not isinstance(scenarios, dict)
            or scenarios.get("status")
            not in {
                "screening_scenarios_schema_valid_qa_needs_review",
                "screening_scenarios_schema_valid_qa_passed",
            }
            or scenarios.get("qa_blocker_count") != 0
        ):
            raise ValueError(
                "Inventory identities require schema-valid scenarios with no QA blocker"
            )
        scope_id = scenarios["scope_id"]
        revision = scenarios["revision"]
        scope_key = f"{scope_id}:{revision}"

        scenario_rows_path_value = scenarios.get("scenario_rows_path")
        scenario_rows_sha256 = scenarios.get("scenario_rows_sha256")
        if not isinstance(scenario_rows_path_value, str) or not isinstance(
            scenario_rows_sha256, str
        ):
            raise ValueError("Scenario rows reference is missing")
        scenario_rows_path = (self.workspace / scenario_rows_path_value).resolve()
        try:
            scenario_rows_path.relative_to(self.workspace)
        except ValueError as error:
            raise ValueError("Scenario rows point outside workspace") from error
        if not scenario_rows_path.is_file():
            raise FileNotFoundError(scenario_rows_path)
        if (
            hashlib.sha256(scenario_rows_path.read_bytes()).hexdigest()
            != scenario_rows_sha256
        ):
            raise RuntimeError("Scenario rows hash drifted")

        registries: Dict[str, JsonObject] = {}
        for kind in ("flow", "source"):
            relative_path = scenarios.get(f"{kind}_registry_path")
            expected_hash = scenarios.get(f"{kind}_registry_sha256")
            if not isinstance(relative_path, str) or not isinstance(
                expected_hash, str
            ):
                raise ValueError(f"Scenario {kind} registry reference is missing")
            path = (self.workspace / relative_path).resolve()
            try:
                path.relative_to(self.workspace)
            except ValueError as error:
                raise ValueError(
                    f"Scenario {kind} registry points outside workspace"
                ) from error
            if not path.is_file():
                raise FileNotFoundError(path)
            content = path.read_bytes()
            if hashlib.sha256(content).hexdigest() != expected_hash:
                raise RuntimeError(f"Scenario {kind} registry hash drifted")
            try:
                registry = json.loads(content)
            except (UnicodeError, json.JSONDecodeError) as error:
                raise ValueError(
                    f"Scenario {kind} registry is not valid JSON"
                ) from error
            if not isinstance(registry, dict):
                raise ValueError(f"Scenario {kind} registry must be an object")
            registries[kind] = registry

        compiled = compile_inventory_identity_preflight(
            registries["flow"],
            registries["source"],
            remote_candidates=remote_candidates,
        )
        if (
            compiled["flow_count"] != scenarios["flow_count"]
            or compiled["source_count"] != scenarios["source_count"]
        ):
            raise ValueError("Identity compiler counts do not match scenario registries")
        prefix = command_prefix or [
            "npm",
            "exec",
            "--yes",
            f"--package={self.TIANGONG_CLI_PACKAGE}",
            "--",
            "tiangong-lca",
        ]
        tool_invocation_sha256 = self._tool_invocation_sha256(prefix)
        batch_version = hashlib.sha256(
            _json_bytes(
                {
                    "compiled": compiled,
                    "flow_registry_sha256": scenarios["flow_registry_sha256"],
                    "source_registry_sha256": scenarios[
                        "source_registry_sha256"
                    ],
                    "scenario_rows_sha256": scenarios[
                        "scenario_rows_sha256"
                    ],
                    "tool_invocation_sha256": tool_invocation_sha256,
                    "package": self.TIANGONG_CLI_PACKAGE,
                }
            )
        ).hexdigest()[:16]
        self.record(
            "milestone.started",
            {
                "milestone_id": "inventory-entity-identity-preflight",
                "title": "运行筛查清单 flow/source 身份预检",
                "status": "running",
                "next_action": (
                    "逐 flow 调用 TianGong 原生 identity-preflight，并明确记录 source 原生能力缺口"
                ),
                "terms": [
                    {
                        "term": "实体消歧",
                        "explanation": (
                            "先用稳定标识和结构化字段判断一个对象应复用、更新还是新建，"
                            "避免只按名称产生重复数据。"
                        ),
                    }
                ],
            },
            actor="controller",
            idempotency_key=(
                f"milestone:inventory-identity:{scope_key}:{batch_version}:started"
            ),
        )

        decisions: List[JsonObject] = []
        for flow_request in compiled["flow_requests"]:
            flow_key = flow_request["flow_key"]
            request = flow_request["request"]
            request_sha256 = hashlib.sha256(_json_bytes(request)).hexdigest()
            flow_version = hashlib.sha256(
                (
                    f"{request_sha256}|{tool_invocation_sha256}|"
                    f"{self.TIANGONG_CLI_PACKAGE}|{IDENTITY_PREFLIGHT_CONTRACT}"
                ).encode("ascii")
            ).hexdigest()[:16]
            base_id = (
                f"inventory-flow-identity:{scope_key}:{flow_key}:{flow_version}"
            )
            attempt = self._semantic_attempt(base_id)
            activity_id = f"{base_id}:attempt-{attempt}"
            root = (
                self.workspace
                / "artifacts"
                / "inventory-identities"
                / f"{scope_id}-{revision}"
                / "flows"
                / flow_key
                / flow_version
                / f"attempt-{attempt}"
            ).resolve()
            try:
                root.relative_to(self.workspace.resolve())
            except ValueError as error:
                raise ValueError(
                    f"Flow identity artifact root escapes workspace: {flow_key}"
                ) from error
            input_path = root / "inputs" / "flow-preflight.json"
            if self._completed_activity(activity_id) is None:
                input_path.parent.mkdir(parents=True, exist_ok=True)
                _write_json(input_path, request)
            command = [
                *prefix,
                "flow",
                "identity-preflight",
                "--input",
                str(input_path),
                "--out-dir",
                str(root),
            ]
            if remote_candidates:
                command.append("--remote-candidates")
            command.append("--json")
            activity = self.run_activity(
                activity_id=activity_id,
                name=f"运行 {flow_request['name']} flow identity-preflight",
                skill_ref="flow-automated-builder/identity-preflight",
                command=command,
                artifact_root=root,
                expected_outputs=[
                    "inputs/flow-preflight.json",
                    "outputs/identity-decision.json",
                    "outputs/identity-candidates.jsonl",
                    "outputs/identity-candidate-sources.json",
                ],
                effect="external_read",
            )
            artifacts = {
                artifact["path"]: artifact
                for artifact in activity["artifacts"]
            }
            report_artifact = artifacts["outputs/identity-decision.json"]
            report = self._load_native_json_report(
                report_path=root / "outputs" / "identity-decision.json",
                report_artifact=report_artifact,
                activity_base_id=base_id,
                activity_id=activity_id,
                attempt=attempt,
                scope_key=scope_key,
                gate="inventory-flow-identity-preflight",
                route_id=flow_key,
            )
            sources_artifact = artifacts[
                "outputs/identity-candidate-sources.json"
            ]
            candidates_artifact = artifacts["outputs/identity-candidates.jsonl"]
            candidates_path = root / "outputs" / "identity-candidates.jsonl"
            candidate_sources_path = (
                root / "outputs" / "identity-candidate-sources.json"
            )
            try:
                candidate_sources = json.loads(
                    candidate_sources_path.read_text(encoding="utf-8")
                )
                candidate_rows = [
                    json.loads(line)
                    for line in candidates_path.read_text(
                        encoding="utf-8"
                    ).splitlines()
                    if line.strip()
                ]
            except (OSError, UnicodeError, json.JSONDecodeError) as error:
                self._record_native_semantic_failure(
                    activity_base_id=base_id,
                    activity_id=activity_id,
                    attempt=attempt,
                    scope_key=scope_key,
                    gate="inventory-flow-identity-preflight",
                    route_id=flow_key,
                    summary=(
                        f"{flow_key} 的原生 flow identity 候选工件无法解析。"
                    ),
                    report_path=report_artifact["workspace_path"],
                    report_sha256=report_artifact["sha256"],
                )
                raise RuntimeError(
                    f"Flow identity candidate artifacts are invalid for '{flow_key}'"
                ) from error
            blockers = report.get("blockers")
            report_sources = report.get("candidate_sources")
            candidates = report.get("candidates")
            findings = report.get("findings")
            valid = (
                report.get("schema_version") == 1
                and report.get("kind") == "flow"
                and report.get("status")
                in {"passed", "blocked", "needs_review"}
                and report.get("decision")
                in {
                    "reuse",
                    "update_same_row",
                    "version_bump",
                    "create_new",
                    "manual_review",
                    "block_duplicate",
                }
                and report.get("confidence") in {"low", "medium", "high"}
                and isinstance(blockers, list)
                and isinstance(candidates, list)
                and isinstance(report_sources, list)
                and isinstance(findings, list)
                and isinstance(candidate_sources, list)
                and all(isinstance(row, dict) for row in candidate_rows)
                and all(isinstance(row, dict) for row in candidate_sources)
                and self._flow_identity_report_matches_request(
                    report,
                    request,
                    input_path,
                    candidate_rows,
                    candidate_sources,
                    root / "outputs" / "identity-decision.json",
                    candidates_path,
                    candidate_sources_path,
                )
            )
            if not valid:
                self._record_native_semantic_failure(
                    activity_base_id=base_id,
                    activity_id=activity_id,
                    attempt=attempt,
                    scope_key=scope_key,
                    gate="inventory-flow-identity-preflight",
                    route_id=flow_key,
                    summary=(
                        f"{flow_key} 的原生 flow identity 报告无效或未绑定目标。"
                    ),
                    report_path=report_artifact["workspace_path"],
                    report_sha256=report_artifact["sha256"],
                )
                raise RuntimeError(
                    f"Native flow identity report failed semantic binding: {flow_key}"
                )
            self._record_native_semantic_acceptance(
                activity_base_id=base_id,
                activity_id=activity_id,
                attempt=attempt,
                scope_key=scope_key,
                gate="inventory-flow-identity-preflight",
                route_id=flow_key,
                report_path=report_artifact["workspace_path"],
                report_sha256=report_artifact["sha256"],
            )
            decisions.append(
                {
                    "flow_key": flow_key,
                    "flow_id": flow_request["flow_id"],
                    "decision": report["decision"],
                    "confidence": report["confidence"],
                    "status": report["status"],
                    "candidate_count": len(candidates),
                    "candidate_source_count": len(report_sources),
                    "remote_candidate_source_count": sum(
                        isinstance(source, dict)
                        and source.get("kind") == "remote_search"
                        for source in report_sources
                    ),
                    "blocker_count": len(blockers),
                    "report_path": report_artifact["workspace_path"],
                    "report_sha256": report_artifact["sha256"],
                    "candidates_path": candidates_artifact["workspace_path"],
                    "candidates_sha256": candidates_artifact["sha256"],
                    "candidate_sources_path": sources_artifact[
                        "workspace_path"
                    ],
                    "candidate_sources_sha256": sources_artifact["sha256"],
                }
            )

        blocker_count = sum(row["blocker_count"] for row in decisions)
        automatic_decisions = {
            "reuse",
            "update_same_row",
            "version_bump",
            "create_new",
        }
        resolution_required_count = sum(
            row["decision"] not in automatic_decisions
            or row["status"] != "passed"
            or row["blocker_count"] > 0
            for row in decisions
        )
        flow_candidate_count = sum(row["candidate_count"] for row in decisions)
        flow_source_count = sum(
            row["candidate_source_count"] for row in decisions
        )
        flow_remote_source_count = sum(
            row["remote_candidate_source_count"] for row in decisions
        )
        decision_counts: Dict[str, int] = {}
        for row in decisions:
            decision = row["decision"]
            decision_counts[decision] = decision_counts.get(decision, 0) + 1
        flow_report_set_sha256 = hashlib.sha256(
            _json_bytes(
                {
                    row["flow_key"]: row["report_sha256"]
                    for row in decisions
                }
            )
        ).hexdigest()
        source_identifier_counts: Dict[str, int] = {}
        for row in compiled["source_assessments"]:
            identifier_kind = row["identifier_kind"]
            source_identifier_counts[identifier_kind] = (
                source_identifier_counts.get(identifier_kind, 0) + 1
            )
        if resolution_required_count:
            status = "flow_identity_candidates_require_resolution"
            flow_gate = "blocked_by_native_identity_candidates"
            next_action = (
                "AI 先解析原生 duplicate/manual-review candidates 并重跑 flow identity；"
                "不得越过 blocker 物化重复 flow。"
            )
        else:
            status = "flow_preflight_complete_source_capability_gap"
            flow_gate = (
                "native_preflight_passed_remote_candidates_checked"
                if remote_candidates
                else "native_preflight_passed_local_only_remote_coverage_missing"
            )
            next_action = (
                "用已接受的 create/reuse 决定生成 canonical TIDAS flow rows；"
                "同时通过 source contract/validation/curation 组合补齐 source 身份能力。"
            )
        result = {
            "schema_version": 1,
            "contract": IDENTITY_PREFLIGHT_CONTRACT,
            "scope_id": scope_id,
            "revision": revision,
            "status": status,
            "tool_invocation_sha256": tool_invocation_sha256,
            "remote_candidates_requested": remote_candidates,
            "flow_identity_gate": flow_gate,
            "source_identity_gate": compiled["source_identity_capability"][
                "status"
            ],
            "flow_count": len(decisions),
            "source_count": compiled["source_count"],
            "flow_candidate_count": flow_candidate_count,
            "flow_candidate_source_count": flow_source_count,
            "flow_remote_candidate_source_count": flow_remote_source_count,
            "flow_blocker_count": blocker_count,
            "flow_resolution_required_count": resolution_required_count,
            "flow_decision_counts": decision_counts,
            "flow_report_set_sha256": flow_report_set_sha256,
            "flow_decisions": decisions,
            "source_identifier_counts": source_identifier_counts,
            "source_identifier_collision_count": 0,
            "source_assessments": compiled["source_assessments"],
            "source_identity_capability": compiled[
                "source_identity_capability"
            ],
            "engineering_basis": compiled["engineering_basis"],
            "scenario_rows_path": scenarios["scenario_rows_path"],
            "scenario_rows_sha256": scenarios["scenario_rows_sha256"],
            "scientific_comparison_ready": False,
            "next_action": next_action,
        }
        result_version = hashlib.sha256(_json_bytes(result)).hexdigest()[:16]
        if not remote_candidates:
            self.record(
                "risk.flagged",
                {
                    "risk_id": f"inventory-flow-remote-coverage:{scope_key}",
                    "severity": "medium",
                    "summary": (
                        f"{len(decisions)} 个 flow 已取得原生本地 create/reuse 决定，"
                        "但本轮没有远程或本地候选集合；"
                        "正式入库前仍需带凭证重跑候选覆盖。"
                    ),
                    "flow_count": len(decisions),
                },
                actor="controller",
                idempotency_key=(
                    f"risk:inventory-flow-remote-coverage:{scope_key}:"
                    f"{result_version}"
                ),
            )
        else:
            self.record(
                "risk.resolved",
                {
                    "risk_id": f"inventory-flow-remote-coverage:{scope_key}",
                    "resolution": "native_remote_candidate_source_recorded_per_flow",
                    "flow_count": len(decisions),
                    "remote_candidate_source_count": flow_remote_source_count,
                },
                actor="controller",
                idempotency_key=(
                    f"risk:inventory-flow-remote-coverage:{scope_key}:"
                    f"{result_version}:resolved"
                ),
            )
        self.record(
            "risk.flagged",
            {
                "risk_id": f"inventory-source-identity-capability:{scope_key}",
                "severity": "medium",
                "summary": (
                    "TianGong CLI 0.0.25 没有 source identity-preflight；"
                    f"{compiled['source_count']} 个 source 仅完成 DOI/URL 精确标识碰撞检查，"
                    "不得声称原生消歧完成。"
                ),
                "source_count": compiled["source_count"],
                "capability_status": result["source_identity_gate"],
            },
            actor="controller",
            idempotency_key=(
                f"risk:inventory-source-identity-capability:{scope_key}:"
                f"{result_version}"
            ),
        )
        if resolution_required_count:
            self.record(
                "risk.flagged",
                {
                    "risk_id": f"inventory-flow-identity-blockers:{scope_key}",
                    "severity": "high",
                    "summary": (
                        "原生 flow identity-preflight 返回需要解析的决定："
                        f"{resolution_required_count} 个 flow，{blocker_count} 个 blocker；"
                        "AI 必须先解析候选，不能物化重复 flow。"
                    ),
                    "flow_count": len(decisions),
                    "resolution_required_count": resolution_required_count,
                    "blocker_count": blocker_count,
                    "flow_report_set_sha256": flow_report_set_sha256,
                    "snapshot_pointer": self.SNAPSHOT_FILE,
                },
                actor="controller",
                idempotency_key=(
                    f"risk:inventory-flow-identity-blockers:{scope_key}:"
                    f"{result_version}"
                ),
            )
        else:
            self.record(
                "risk.resolved",
                {
                    "risk_id": f"inventory-flow-identity-blockers:{scope_key}",
                    "resolution": "all_native_flow_decisions_automatic",
                    "flow_count": len(decisions),
                    "flow_report_set_sha256": flow_report_set_sha256,
                },
                actor="controller",
                idempotency_key=(
                    f"risk:inventory-flow-identity-blockers:{scope_key}:"
                    f"{result_version}:resolved"
                ),
            )
        event = self.record(
            "research.inventory_identities.preflighted",
            result,
            actor="controller",
            idempotency_key=(
                f"inventory-identities:{scope_key}:{result_version}:preflighted"
            ),
        )
        self.record(
            (
                "milestone.started"
                if resolution_required_count
                else "milestone.completed"
            ),
            {
                "milestone_id": (
                    "inventory-flow-identity-resolution"
                    if resolution_required_count
                    else "inventory-entity-identity-preflight"
                ),
                "title": (
                    "筛查 flow 身份候选需要解析"
                    if resolution_required_count
                    else "筛查 flow 原生身份预检完成，source 能力缺口已显式保留"
                ),
                "status": (
                    "running" if resolution_required_count else "completed"
                ),
                "next_action": next_action,
            },
            actor="controller",
            idempotency_key=(
                f"milestone:inventory-identity:{scope_key}:{result_version}:"
                f"{'started' if resolution_required_count else 'completed'}"
            ),
        )
        self.materialize_views()
        return event["payload"]

    @staticmethod
    def _flow_payload_id(flow: JsonObject) -> Optional[str]:
        try:
            value = flow["flowDataSet"]["flowInformation"][
                "dataSetInformation"
            ]["common:UUID"]
        except (KeyError, TypeError):
            return None
        return value if isinstance(value, str) and value else None

    @staticmethod
    def _source_payload_id(source: JsonObject) -> Optional[str]:
        try:
            value = source["sourceDataSet"]["sourceInformation"][
                "dataSetInformation"
            ]["common:UUID"]
        except (KeyError, TypeError):
            return None
        return value if isinstance(value, str) and value else None

    @classmethod
    def _entity_rows_match(
        cls,
        kind: str,
        expected_rows: List[JsonObject],
        actual_rows: List[JsonObject],
    ) -> bool:
        id_getter = (
            cls._flow_payload_id if kind == "flow" else cls._source_payload_id
        )

        def indexed(rows: List[JsonObject]) -> Optional[Dict[str, str]]:
            result: Dict[str, str] = {}
            for row in rows:
                row_id = id_getter(row)
                if row_id is None or row_id in result:
                    return None
                result[row_id] = hashlib.sha256(_json_bytes(row)).hexdigest()
            return result

        expected = indexed(expected_rows)
        actual = indexed(actual_rows)
        return expected is not None and actual is not None and expected == actual

    @staticmethod
    def _materialized_flow_matches_plan(
        flow: JsonObject, plan: JsonObject
    ) -> bool:
        try:
            dataset = flow["flowDataSet"]
            information = dataset["flowInformation"]
            data_set_information = information["dataSetInformation"]
            base_names = data_set_information["name"]["baseName"]
            quantitative_reference = information["quantitativeReference"]
            modelling = dataset["modellingAndValidation"]["LCIMethod"]
            administration = dataset["administrativeInformation"]
            version = administration["publicationAndOwnership"][
                "common:dataSetVersion"
            ]
            timestamp = administration["dataEntryBy"]["common:timeStamp"]
            flow_property = dataset["flowProperties"]["flowProperty"]
            property_reference = flow_property["referenceToFlowPropertyDataSet"]
        except (KeyError, TypeError):
            return False
        if isinstance(base_names, dict):
            base_names = [base_names]
        if not isinstance(base_names, list) or not base_names:
            return False
        base_name = base_names[0]
        if not isinstance(base_name, dict):
            return False
        property_plan = plan.get("flow_property_plan")
        if not isinstance(property_plan, dict):
            return False
        property_id = property_reference.get("@refObjectId")
        try:
            uuid.UUID(str(property_id))
        except ValueError:
            return False
        expected_property_id = property_plan.get("reference_property_id")
        short_description = property_reference.get("common:shortDescription")
        if isinstance(short_description, list):
            short_description = (
                short_description[0] if short_description else None
            )
        return all(
            (
                data_set_information.get("common:UUID")
                == plan.get("target", {}).get("uuid"),
                base_name.get("#text")
                == plan.get("name_plan", {}).get("base_name"),
                modelling.get("typeOfDataSet")
                == plan.get("target", {}).get("flow_type"),
                version == plan.get("target", {}).get("version"),
                timestamp
                == plan.get("administrative_information", {}).get(
                    "time_stamp"
                ),
                quantitative_reference.get(
                    "referenceToReferenceFlowProperty"
                )
                == str(flow_property.get("@dataSetInternalID")),
                _decimal_equal(flow_property.get("meanValue"), 1),
                isinstance(short_description, dict)
                and short_description.get("#text")
                == property_plan.get("reference_property"),
                expected_property_id is None
                or property_id == expected_property_id,
            )
        )

    @staticmethod
    def _save_draft_report_is_valid(
        report: JsonObject,
        *,
        kind: str,
        count: int,
        input_path: Path,
    ) -> bool:
        counts = report.get("counts")
        rows = report.get("rows")
        files = report.get("files")
        return (
            report.get("schema_version") == 1
            and report.get("requested_type") == kind
            and report.get("commit") is False
            and report.get("mode") == "dry_run"
            and report.get("status") == "completed"
            and isinstance(report.get("input_path"), str)
            and Path(str(report["input_path"])).resolve()
            == input_path.resolve()
            and isinstance(counts, dict)
            and counts.get("selected") == count
            and counts.get("prepared") == count
            and counts.get("executed") == 0
            and counts.get("failed") == 0
            and counts.get("by_table") == {f"{kind}s": count}
            and counts.get("operations") == {"would_sync": count}
            and isinstance(rows, list)
            and len(rows) == count
            and all(
                isinstance(row, dict)
                and row.get("type") == kind
                and row.get("status") == "prepared"
                and row.get("operation") == "would_sync"
                and isinstance(row.get("validation"), dict)
                and row["validation"].get("ok") is True
                and row["validation"].get("issue_count") == 0
                for row in rows
            )
            and isinstance(files, dict)
        )

    def materialize_inventory_entities(
        self,
        *,
        command_prefix: Optional[List[str]] = None,
    ) -> JsonObject:
        """Materialize local TIDAS flow/source drafts and native authoring gates."""

        events = self.events()
        snapshot = self._project(events)
        identities = snapshot.get("inventory_identities")
        scenarios = snapshot.get("inventory_scenarios")
        if (
            not isinstance(identities, dict)
            or identities.get("status")
            != "flow_preflight_complete_source_capability_gap"
            or identities.get("flow_resolution_required_count") != 0
            or identities.get("flow_blocker_count") != 0
        ):
            raise ValueError(
                "Inventory entity authoring requires accepted automatic flow identities"
            )
        if not isinstance(scenarios, dict):
            raise ValueError("Inventory entity authoring requires validated scenarios")
        if identities.get("scenario_rows_sha256") != scenarios.get(
            "scenario_rows_sha256"
        ):
            raise ValueError("Identity decisions do not bind the current scenarios")
        scope_id = _required_text(identities.get("scope_id"), "scope_id")
        revision = _required_text(identities.get("revision"), "revision")
        scope_key = f"{scope_id}:{revision}"

        def verified_file(
            relative_path: object, expected_hash: object, label: str
        ) -> tuple[Path, bytes]:
            if not isinstance(relative_path, str) or not isinstance(
                expected_hash, str
            ):
                raise ValueError(f"{label} reference is missing")
            path = (self.workspace / relative_path).resolve()
            try:
                path.relative_to(self.workspace)
            except ValueError as error:
                raise ValueError(f"{label} escaped the project workspace") from error
            if not path.is_file():
                raise FileNotFoundError(path)
            content = path.read_bytes()
            if hashlib.sha256(content).hexdigest() != expected_hash:
                raise RuntimeError(f"{label} hash drifted")
            return path, content

        _, scenario_rows_bytes = verified_file(
            scenarios.get("scenario_rows_path"),
            scenarios.get("scenario_rows_sha256"),
            "scenario rows",
        )
        registries: Dict[str, JsonObject] = {}
        for kind in ("flow", "source"):
            _, content = verified_file(
                scenarios.get(f"{kind}_registry_path"),
                scenarios.get(f"{kind}_registry_sha256"),
                f"{kind} registry",
            )
            try:
                registry = json.loads(content)
            except (UnicodeError, json.JSONDecodeError) as error:
                raise ValueError(f"{kind} registry is not valid JSON") from error
            if not isinstance(registry, dict):
                raise ValueError(f"{kind} registry must be a JSON object")
            registries[kind] = registry

        decisions = identities.get("flow_decisions")
        if not isinstance(decisions, list) or not decisions:
            raise ValueError("Inventory flow decisions are missing")
        for decision in decisions:
            if not isinstance(decision, dict):
                raise ValueError("Inventory flow decision must be an object")
            for path_key, hash_key in (
                ("report_path", "report_sha256"),
                ("candidates_path", "candidates_sha256"),
                ("candidate_sources_path", "candidate_sources_sha256"),
            ):
                verified_file(
                    decision.get(path_key),
                    decision.get(hash_key),
                    f"{decision.get('flow_key')} {path_key}",
                )
        report_set_sha256 = hashlib.sha256(
            _json_bytes(
                {
                    row["flow_key"]: row["report_sha256"]
                    for row in decisions
                    if isinstance(row, dict)
                }
            )
        ).hexdigest()
        if report_set_sha256 != identities.get("flow_report_set_sha256"):
            raise RuntimeError("Flow identity report set hash drifted")
        compiled_identities = compile_inventory_identity_preflight(
            registries["flow"],
            registries["source"],
            remote_candidates=bool(identities.get("remote_candidates_requested")),
        )
        if compiled_identities.get("source_assessments") != identities.get(
            "source_assessments"
        ):
            raise RuntimeError("Source identity assessments drifted")
        authored_event = next(
            (
                event
                for event in reversed(events)
                if event.get("event_type")
                == "research.inventory_identities.preflighted"
                and event.get("payload") == identities
            ),
            None,
        )
        if authored_event is None:
            raise RuntimeError("Accepted identity event timestamp is missing")
        authored_at_utc = _required_text(
            authored_event.get("occurred_at"), "identity occurred_at"
        )

        prefix = command_prefix or [
            "npm",
            "exec",
            "--yes",
            f"--package={self.TIANGONG_CLI_PACKAGE}",
            "--",
            "tiangong-lca",
        ]
        tool_invocation_sha256 = self._tool_invocation_sha256(prefix)

        contract_version = hashlib.sha256(
            (
                f"source|{self.TIANGONG_CLI_PACKAGE}|"
                f"{tool_invocation_sha256}|dataset-contract/v2-source-schema-capability"
            ).encode("ascii")
        ).hexdigest()[:16]
        contract_base_id = f"inventory-source-contract:{contract_version}"
        contract_attempt = self._semantic_attempt(contract_base_id)
        contract_activity_id = (
            f"{contract_base_id}:attempt-{contract_attempt}"
        )
        contract_root = (
            self.workspace
            / "artifacts"
            / "inventory-entity-authoring"
            / "source-contract"
            / contract_version
            / f"attempt-{contract_attempt}"
        )
        contract_activity = self.run_activity(
            activity_id=contract_activity_id,
            name="固定 TianGong source TIDAS 权威合同",
            skill_ref="tidas-data-import/dataset-contract",
            command=[
                *prefix,
                "dataset",
                "contract",
                "get",
                "--type",
                "source",
                "--out-dir",
                str(contract_root),
                "--json",
            ],
            artifact_root=contract_root,
            expected_outputs=[
                "outputs/contract-manifest.json",
                "outputs/schema.json",
                "outputs/contract-report.json",
            ],
            effect="external_read",
        )
        contract_artifacts = {
            row["path"]: row for row in contract_activity["artifacts"]
        }
        contract_manifest_artifact = contract_artifacts[
            "outputs/contract-manifest.json"
        ]
        contract_report_artifact = contract_artifacts[
            "outputs/contract-report.json"
        ]
        contract_manifest = self._load_native_json_report(
            report_path=contract_root / "outputs" / "contract-manifest.json",
            report_artifact=contract_manifest_artifact,
            activity_base_id=contract_base_id,
            activity_id=contract_activity_id,
            attempt=contract_attempt,
            scope_key=scope_key,
            gate="source-contract",
        )
        contract_report = self._load_native_json_report(
            report_path=contract_root / "outputs" / "contract-report.json",
            report_artifact=contract_report_artifact,
            activity_base_id=contract_base_id,
            activity_id=contract_activity_id,
            attempt=contract_attempt,
            scope_key=scope_key,
            gate="source-contract",
        )
        schema_contract_record = contract_manifest.get("schema")
        schema_contract_matches = False
        if isinstance(schema_contract_record, dict):
            schema_bytes = (
                contract_root / "outputs" / "schema.json"
            ).read_bytes()
            schema_candidates = [schema_bytes]
            if schema_bytes.endswith(b"\n"):
                schema_candidates.append(schema_bytes[:-1])
            schema_contract_matches = any(
                schema_contract_record.get("bytes") == len(candidate)
                and schema_contract_record.get("sha256")
                == hashlib.sha256(candidate).hexdigest()
                for candidate in schema_candidates
            )
        contract_valid = (
            contract_manifest.get("schema_version") == 1
            and contract_manifest.get("kind") == "source"
            and contract_report.get("schema_version") == 1
            and contract_report.get("status") == "completed"
            and contract_report.get("type") == "source"
            and contract_report.get("manifest") == contract_manifest
            and isinstance(contract_manifest.get("schema"), dict)
            and isinstance(contract_manifest["schema"].get("sha256"), str)
            and schema_contract_matches
            and all(
                contract_manifest.get(key) is None
                or (
                    isinstance(contract_manifest.get(key), dict)
                    and isinstance(contract_manifest[key].get("sha256"), str)
                )
                for key in ("methodology", "ruleset")
            )
        )
        if not contract_valid:
            self._record_native_semantic_failure(
                activity_base_id=contract_base_id,
                activity_id=contract_activity_id,
                attempt=contract_attempt,
                scope_key=scope_key,
                gate="source-contract",
                summary="TianGong source contract manifest/report 未相互绑定。",
                report_path=contract_report_artifact["workspace_path"],
                report_sha256=contract_report_artifact["sha256"],
            )
            raise RuntimeError("Native source contract failed semantic binding")
        self._record_native_semantic_acceptance(
            activity_base_id=contract_base_id,
            activity_id=contract_activity_id,
            attempt=contract_attempt,
            scope_key=scope_key,
            gate="source-contract",
            report_path=contract_report_artifact["workspace_path"],
            report_sha256=contract_report_artifact["sha256"],
        )

        authoring = compile_inventory_entity_authoring(
            compiled_identities,
            identities,
            contract_manifest,
            authored_at_utc=authored_at_utc,
        )
        authoring_version = hashlib.sha256(
            _json_bytes(
                {
                    "authoring": authoring,
                    "scenario_rows_sha256": scenarios["scenario_rows_sha256"],
                    "flow_report_set_sha256": report_set_sha256,
                    "source_contract_manifest_sha256": (
                        contract_manifest_artifact["sha256"]
                    ),
                    "tool_invocation_sha256": tool_invocation_sha256,
                    "package": self.TIANGONG_CLI_PACKAGE,
                }
            )
        ).hexdigest()[:16]
        self.record(
            "milestone.started",
            {
                "milestone_id": "inventory-entity-authoring",
                "title": "物化并验证筛查清单的 TIDAS flow/source rows",
                "status": "running",
                "next_action": (
                    "运行 11 个 flow build-plan materialize、双类型 validation/QA、"
                    "save-draft dry-run 与 curation queue"
                ),
                "terms": [
                    {
                        "term": "本地 canonical draft",
                        "explanation": (
                            "已符合 TIDAS 结构并通过本地确定性校验的权威草稿；"
                            "远程去重和支撑引用解析完成前，不等于可发布数据库记录。"
                        ),
                    }
                ],
            },
            actor="controller",
            idempotency_key=(
                f"milestone:inventory-entity-authoring:{scope_key}:"
                f"{authoring_version}:started"
            ),
        )

        source_rows = [
            row["payload"] for row in authoring["source_rows"]
        ]
        flow_rows: List[JsonObject] = []
        flow_results: List[JsonObject] = []
        required_flow_paths = {
            "target",
            "identity_decision.decision",
            "unit_of_analysis",
            "name_plan.base_name",
            "target.flow_type",
            "flow_property_plan.reference_property",
            "flow_property_plan.reference_unit",
        }
        for flow_entry in authoring["flow_plans"]:
            flow_key = flow_entry["flow_key"]
            plan = flow_entry["plan"]
            flow_version = hashlib.sha256(
                _json_bytes(
                    {
                        "plan": plan,
                        "tool_invocation_sha256": tool_invocation_sha256,
                        "package": self.TIANGONG_CLI_PACKAGE,
                        "contract": ENTITY_AUTHORING_CONTRACT,
                    }
                )
            ).hexdigest()[:16]
            base_id = (
                f"inventory-flow-materialize:{scope_key}:{flow_key}:{flow_version}"
            )
            attempt = self._semantic_attempt(base_id)
            activity_id = f"{base_id}:attempt-{attempt}"
            root = (
                self.workspace
                / "artifacts"
                / "inventory-entity-authoring"
                / f"{scope_id}-{revision}"
                / authoring_version
                / "flows"
                / flow_key
                / flow_version
                / f"attempt-{attempt}"
            )
            input_path = root / "inputs" / "flow-build-plan.json"
            if self._completed_activity(activity_id) is None:
                input_path.parent.mkdir(parents=True, exist_ok=True)
                _write_json(input_path, plan)
            activity = self.run_activity(
                activity_id=activity_id,
                name=f"物化 {flow_key} TianGong flow",
                skill_ref="flow-automated-builder/build-plan",
                command=[
                    *prefix,
                    "flow",
                    "build-plan",
                    "materialize",
                    "--input",
                    str(input_path.relative_to(self.workspace)),
                    "--out-dir",
                    str(root),
                    "--report-only",
                    "--json",
                ],
                artifact_root=root,
                expected_outputs=[
                    "inputs/flow-build-plan.json",
                    "outputs/build-plan-gate-report.json",
                    "outputs/materialized-flow.json",
                ],
                effect="local_write",
            )
            artifacts = {row["path"]: row for row in activity["artifacts"]}
            gate_artifact = artifacts["outputs/build-plan-gate-report.json"]
            flow_artifact = artifacts["outputs/materialized-flow.json"]
            gate_report = self._load_native_json_report(
                report_path=root / "outputs" / "build-plan-gate-report.json",
                report_artifact=gate_artifact,
                activity_base_id=base_id,
                activity_id=activity_id,
                attempt=attempt,
                scope_key=scope_key,
                gate="flow-materialize",
                route_id=flow_key,
            )
            flow = self._load_native_json_report(
                report_path=root / "outputs" / "materialized-flow.json",
                report_artifact=flow_artifact,
                activity_base_id=base_id,
                activity_id=activity_id,
                attempt=attempt,
                scope_key=scope_key,
                gate="flow-materialize",
                route_id=flow_key,
            )
            required_fields = gate_report.get("required_fields")
            schema_validation = gate_report.get("schema_validation")
            valid = (
                gate_report.get("schema_version") == 1
                and gate_report.get("kind") == "flow"
                and gate_report.get("action") == "materialize"
                and gate_report.get("status") == "passed"
                and isinstance(required_fields, dict)
                and set(required_fields.get("required", []))
                == required_flow_paths
                and set(required_fields.get("satisfied", []))
                == required_flow_paths
                and required_fields.get("missing") == []
                and isinstance(schema_validation, dict)
                and schema_validation.get("status") == "passed"
                and schema_validation.get("issue_count") == 0
                and schema_validation.get("issues") == []
                and gate_report.get("blockers") == []
                and self._materialized_flow_matches_plan(flow, plan)
            )
            if not valid:
                self._record_native_semantic_failure(
                    activity_base_id=base_id,
                    activity_id=activity_id,
                    attempt=attempt,
                    scope_key=scope_key,
                    gate="flow-materialize",
                    route_id=flow_key,
                    summary=(
                        f"{flow_key} flow materialize 未通过 schema/identity/property 回绑。"
                    ),
                    report_path=gate_artifact["workspace_path"],
                    report_sha256=gate_artifact["sha256"],
                )
                raise RuntimeError(
                    f"Native flow materialization failed: {flow_key}"
                )
            self._record_native_semantic_acceptance(
                activity_base_id=base_id,
                activity_id=activity_id,
                attempt=attempt,
                scope_key=scope_key,
                gate="flow-materialize",
                route_id=flow_key,
                report_path=gate_artifact["workspace_path"],
                report_sha256=gate_artifact["sha256"],
            )
            result = {
                "flow_key": flow_key,
                "flow_id": flow_entry["flow_id"],
                "version": plan["target"]["version"],
                "plan_path": artifacts["inputs/flow-build-plan.json"][
                    "workspace_path"
                ],
                "plan_sha256": artifacts["inputs/flow-build-plan.json"][
                    "sha256"
                ],
                "flow_path": flow_artifact["workspace_path"],
                "flow_sha256": flow_artifact["sha256"],
                "gate_report_path": gate_artifact["workspace_path"],
                "gate_report_sha256": gate_artifact["sha256"],
                "reference_property_status": plan["flow_property_plan"][
                    "support_reference_status"
                ],
            }
            self.record(
                "decision.recorded",
                {
                    "decision_id": (
                        f"inventory-flow-materialized:{scope_key}:{flow_key}:"
                        f"{flow_artifact['sha256'][:16]}"
                    ),
                    "decision_type": "inventory.flow.materialized",
                    **result,
                },
                actor="controller",
                idempotency_key=(
                    f"decision:inventory-flow-materialized:{scope_key}:{flow_key}:"
                    f"{flow_artifact['sha256'][:16]}"
                ),
            )
            flow_rows.append(flow)
            flow_results.append(result)

        def validate_rows(
            kind: str, rows: List[JsonObject]
        ) -> tuple[JsonObject, List[JsonObject]]:
            rows_sha256 = hashlib.sha256(_jsonl_bytes(rows)).hexdigest()
            base_id = (
                f"inventory-{kind}-validate:{scope_key}:{rows_sha256[:16]}"
            )
            attempt = self._semantic_attempt(base_id)
            activity_id = f"{base_id}:attempt-{attempt}"
            root = (
                self.workspace
                / "artifacts"
                / "inventory-entity-authoring"
                / f"{scope_id}-{revision}"
                / authoring_version
                / f"{kind}-validation"
                / f"attempt-{attempt}"
            )
            input_path = root / "inputs" / f"canonical-{kind}s.jsonl"
            if self._completed_activity(activity_id) is None:
                input_path.parent.mkdir(parents=True, exist_ok=True)
                input_path.write_bytes(_jsonl_bytes(rows))
            activity = self.run_activity(
                activity_id=activity_id,
                name=f"运行 canonical {kind} TIDAS dataset validation",
                skill_ref="tidas-data-import/dataset-validate",
                command=[
                    *prefix,
                    "dataset",
                    "validate",
                    "--input",
                    str(input_path),
                    "--type",
                    kind,
                    "--out-dir",
                    str(root),
                    "--json",
                ],
                artifact_root=root,
                expected_outputs=[
                    f"inputs/canonical-{kind}s.jsonl",
                    "outputs/validation-report.json",
                    "outputs/valid-rows.jsonl",
                    "outputs/invalid-rows.jsonl",
                ],
                effect="local_write",
                accepted_exit_codes={0, 1},
            )
            artifacts = {row["path"]: row for row in activity["artifacts"]}
            report_artifact = artifacts["outputs/validation-report.json"]
            report = self._load_native_json_report(
                report_path=root / "outputs" / "validation-report.json",
                report_artifact=report_artifact,
                activity_base_id=base_id,
                activity_id=activity_id,
                attempt=attempt,
                scope_key=scope_key,
                gate=f"{kind}-dataset-validate",
            )
            try:
                valid_rows = self._load_jsonl_objects(
                    root / "outputs" / "valid-rows.jsonl"
                )
                invalid_rows = self._load_jsonl_objects(
                    root / "outputs" / "invalid-rows.jsonl"
                )
            except (OSError, UnicodeError, ValueError):
                valid_rows = []
                invalid_rows = [{}]
            counts = report.get("counts")
            report_rows = report.get("rows")
            id_getter = (
                self._flow_payload_id
                if kind == "flow"
                else self._source_payload_id
            )
            expected_ids = {id_getter(row) for row in rows}
            valid = (
                report.get("requested_type") == kind
                and report.get("status") == "completed"
                and isinstance(counts, dict)
                and counts.get("total") == len(rows)
                and counts.get("valid") == len(rows)
                and counts.get("invalid") == 0
                and isinstance(report_rows, list)
                and len(report_rows) == len(rows)
                and {
                    row.get("id")
                    for row in report_rows
                    if isinstance(row, dict)
                    and row.get("type") == kind
                    and row.get("status") == "valid"
                    and row.get("issue_count") == 0
                    and row.get("issues") == []
                }
                == expected_ids
                and self._entity_rows_match(kind, rows, valid_rows)
                and invalid_rows == []
            )
            if not valid:
                self._record_native_semantic_failure(
                    activity_base_id=base_id,
                    activity_id=activity_id,
                    attempt=attempt,
                    scope_key=scope_key,
                    gate=f"{kind}-dataset-validate",
                    summary=f"Canonical {kind} rows 未全部通过原生 TIDAS validation。",
                    report_path=report_artifact["workspace_path"],
                    report_sha256=report_artifact["sha256"],
                )
                raise RuntimeError(f"Canonical {kind} rows failed validation")
            self._record_native_semantic_acceptance(
                activity_base_id=base_id,
                activity_id=activity_id,
                attempt=attempt,
                scope_key=scope_key,
                gate=f"{kind}-dataset-validate",
                report_path=report_artifact["workspace_path"],
                report_sha256=report_artifact["sha256"],
            )
            return (
                {
                    "count": len(rows),
                    "rows_sha256": rows_sha256,
                    "input_path": artifacts[f"inputs/canonical-{kind}s.jsonl"][
                        "workspace_path"
                    ],
                    "input_sha256": artifacts[
                        f"inputs/canonical-{kind}s.jsonl"
                    ]["sha256"],
                    "report_path": report_artifact["workspace_path"],
                    "report_sha256": report_artifact["sha256"],
                    "valid_rows_path": artifacts[
                        "outputs/valid-rows.jsonl"
                    ]["workspace_path"],
                    "valid_rows_sha256": artifacts[
                        "outputs/valid-rows.jsonl"
                    ]["sha256"],
                },
                valid_rows,
            )

        source_validation, validated_sources = validate_rows(
            "source", source_rows
        )
        flow_validation, validated_flows = validate_rows("flow", flow_rows)

        def save_draft_dry_run(
            kind: str, rows: List[JsonObject], rows_hash: str
        ) -> JsonObject:
            base_id = (
                f"inventory-{kind}-save-draft-dry-run:{scope_key}:"
                f"{rows_hash[:16]}"
            )
            attempt = self._semantic_attempt(base_id)
            activity_id = f"{base_id}:attempt-{attempt}"
            root = (
                self.workspace
                / "artifacts"
                / "inventory-entity-authoring"
                / f"{scope_id}-{revision}"
                / authoring_version
                / f"{kind}-save-draft-dry-run"
                / f"attempt-{attempt}"
            )
            input_path = root / "inputs" / f"validated-{kind}s.jsonl"
            if self._completed_activity(activity_id) is None:
                input_path.parent.mkdir(parents=True, exist_ok=True)
                input_path.write_bytes(_jsonl_bytes(rows))
            activity = self.run_activity(
                activity_id=activity_id,
                name=f"运行 canonical {kind} save-draft dry-run",
                skill_ref="tidas-data-import/dataset-save-draft",
                command=[
                    *prefix,
                    "dataset",
                    "save-draft",
                    "--input",
                    str(input_path),
                    "--type",
                    kind,
                    "--out-dir",
                    str(root),
                    "--dry-run",
                    "--json",
                ],
                artifact_root=root,
                expected_outputs=[
                    f"inputs/validated-{kind}s.jsonl",
                    "outputs/dataset-save-draft/selected-rows.jsonl",
                    "outputs/dataset-save-draft/progress.jsonl",
                    "outputs/dataset-save-draft/failures.jsonl",
                    "outputs/dataset-save-draft/summary.json",
                ],
                effect="local_write",
            )
            artifacts = {row["path"]: row for row in activity["artifacts"]}
            report_artifact = artifacts[
                "outputs/dataset-save-draft/summary.json"
            ]
            report = self._load_native_json_report(
                report_path=root
                / "outputs"
                / "dataset-save-draft"
                / "summary.json",
                report_artifact=report_artifact,
                activity_base_id=base_id,
                activity_id=activity_id,
                attempt=attempt,
                scope_key=scope_key,
                gate=f"{kind}-save-draft-dry-run",
            )
            try:
                selected = self._load_jsonl_objects(
                    root
                    / "outputs"
                    / "dataset-save-draft"
                    / "selected-rows.jsonl"
                )
                progress = self._load_jsonl_objects(
                    root
                    / "outputs"
                    / "dataset-save-draft"
                    / "progress.jsonl"
                )
                failures = self._load_jsonl_objects(
                    root
                    / "outputs"
                    / "dataset-save-draft"
                    / "failures.jsonl"
                )
            except (OSError, UnicodeError, ValueError):
                selected = []
                progress = []
                failures = [{}]
            selected_payloads = [
                row.get("payload") for row in selected if isinstance(row, dict)
            ]
            valid = (
                self._save_draft_report_is_valid(
                    report, kind=kind, count=len(rows), input_path=input_path
                )
                and len(selected_payloads) == len(rows)
                and all(isinstance(row, dict) for row in selected_payloads)
                and self._entity_rows_match(kind, rows, selected_payloads)
                and progress == report.get("rows")
                and failures == []
            )
            if not valid:
                self._record_native_semantic_failure(
                    activity_base_id=base_id,
                    activity_id=activity_id,
                    attempt=attempt,
                    scope_key=scope_key,
                    gate=f"{kind}-save-draft-dry-run",
                    summary=f"Canonical {kind} save-draft dry-run 未完全 prepared。",
                    report_path=report_artifact["workspace_path"],
                    report_sha256=report_artifact["sha256"],
                )
                raise RuntimeError(f"Canonical {kind} save-draft dry-run failed")
            self._record_native_semantic_acceptance(
                activity_base_id=base_id,
                activity_id=activity_id,
                attempt=attempt,
                scope_key=scope_key,
                gate=f"{kind}-save-draft-dry-run",
                report_path=report_artifact["workspace_path"],
                report_sha256=report_artifact["sha256"],
            )
            return {
                "status": report["status"],
                "mode": report["mode"],
                "prepared": report["counts"]["prepared"],
                "failed": report["counts"]["failed"],
                "report_path": report_artifact["workspace_path"],
                "report_sha256": report_artifact["sha256"],
                "selected_rows_path": artifacts[
                    "outputs/dataset-save-draft/selected-rows.jsonl"
                ]["workspace_path"],
                "selected_rows_sha256": artifacts[
                    "outputs/dataset-save-draft/selected-rows.jsonl"
                ]["sha256"],
            }

        source_save_draft = save_draft_dry_run(
            "source",
            validated_sources,
            source_validation["valid_rows_sha256"],
        )
        flow_save_draft = save_draft_dry_run(
            "flow",
            validated_flows,
            flow_validation["valid_rows_sha256"],
        )

        qa_input_sha256 = flow_validation["valid_rows_sha256"]
        qa_base_id = f"inventory-flow-qa:{scope_key}:{qa_input_sha256[:16]}"
        qa_attempt = self._semantic_attempt(qa_base_id)
        qa_activity_id = f"{qa_base_id}:attempt-{qa_attempt}"
        qa_root = (
            self.workspace
            / "artifacts"
            / "inventory-entity-authoring"
            / f"{scope_id}-{revision}"
            / authoring_version
            / "flow-qa"
            / f"attempt-{qa_attempt}"
        )
        qa_input = qa_root / "inputs" / "validated-flows.jsonl"
        if self._completed_activity(qa_activity_id) is None:
            qa_input.parent.mkdir(parents=True, exist_ok=True)
            qa_input.write_bytes(_jsonl_bytes(validated_flows))
        flow_file_outputs = [
            f"qa-input/flows/{flow_result['flow_id']}__{flow_result['version']}.json"
            for flow_result in flow_results
        ]
        qa_activity = self.run_activity(
            activity_id=qa_activity_id,
            name="运行 canonical inventory flow QA",
            skill_ref="flow-governance/qa",
            command=[
                *prefix,
                "qa",
                "flow",
                "--rows-file",
                str(qa_input),
                "--out-dir",
                str(qa_root),
                "--logic-version",
                "flow-v1.0-cli",
                "--json",
            ],
            artifact_root=qa_root,
            expected_outputs=[
                "inputs/validated-flows.jsonl",
                "qa-input/materialization-summary.json",
                *flow_file_outputs,
                "qa-input-summary.json",
                "rule_findings.jsonl",
                "llm_findings.jsonl",
                "findings.jsonl",
                "flow-qa-ruleset-gate.json",
                "flow_summaries.jsonl",
                "similarity_pairs.jsonl",
                "flow_qa_summary.json",
                "flow_qa_zh.md",
                "flow_qa_en.md",
                "flow_qa_timing.md",
                "flow_qa_report.json",
            ],
            effect="local_write",
        )
        qa_artifacts = {row["path"]: row for row in qa_activity["artifacts"]}
        qa_report_artifact = qa_artifacts["flow_qa_report.json"]
        qa_gate_artifact = qa_artifacts["flow-qa-ruleset-gate.json"]
        qa_report = self._load_native_json_report(
            report_path=qa_root / "flow_qa_report.json",
            report_artifact=qa_report_artifact,
            activity_base_id=qa_base_id,
            activity_id=qa_activity_id,
            attempt=qa_attempt,
            scope_key=scope_key,
            gate="flow-qa",
        )
        qa_gate = self._load_native_json_report(
            report_path=qa_root / "flow-qa-ruleset-gate.json",
            report_artifact=qa_gate_artifact,
            activity_base_id=qa_base_id,
            activity_id=qa_activity_id,
            attempt=qa_attempt,
            scope_key=scope_key,
            gate="flow-qa",
        )
        try:
            qa_materialization = json.loads(
                (qa_root / "qa-input" / "materialization-summary.json").read_text(
                    encoding="utf-8"
                )
            )
            qa_summaries = self._load_jsonl_objects(
                qa_root / "flow_summaries.jsonl"
            )
        except (OSError, UnicodeError, json.JSONDecodeError, ValueError):
            qa_materialization = {}
            qa_summaries = []
        expected_flow_ids = {row["flow_id"] for row in flow_results}
        qa_valid = (
            qa_report.get("schema_version") == 1
            and qa_report.get("status") == "completed_local_flow_qa"
            and qa_report.get("logic_version") == "flow-v1.0-cli"
            and qa_report.get("flow_count") == len(flow_results)
            and qa_report.get("blocker_count") == 0
            and qa_report.get("ruleset_gate") == qa_gate
            and qa_gate.get("status") in {"passed", "needs_review"}
            and qa_gate.get("counts", {}).get("blockers") == 0
            and qa_report.get("with_reference_context") is False
            and isinstance(qa_materialization, dict)
            and qa_materialization.get("source_rows_file")
            == str(qa_input.resolve())
            and qa_materialization.get("input_row_count") == len(flow_results)
            and qa_materialization.get("materialized_flow_count")
            == len(flow_results)
            and qa_materialization.get("duplicate_input_rows_collapsed") == 0
            and {
                row.get("flow_uuid")
                for row in qa_summaries
                if isinstance(row, dict)
            }
            == expected_flow_ids
        )
        if not qa_valid:
            self._record_native_semantic_failure(
                activity_base_id=qa_base_id,
                activity_id=qa_activity_id,
                attempt=qa_attempt,
                scope_key=scope_key,
                gate="flow-qa",
                summary="Canonical inventory flows 未通过目标绑定的原生 Flow QA。",
                report_path=qa_report_artifact["workspace_path"],
                report_sha256=qa_report_artifact["sha256"],
            )
            raise RuntimeError("Canonical inventory flows failed native QA")
        self._record_native_semantic_acceptance(
            activity_base_id=qa_base_id,
            activity_id=qa_activity_id,
            attempt=qa_attempt,
            scope_key=scope_key,
            gate="flow-qa",
            report_path=qa_report_artifact["workspace_path"],
            report_sha256=qa_report_artifact["sha256"],
        )
        flow_qa = {
            "status": qa_gate["status"],
            "flow_count": qa_report["flow_count"],
            "finding_count": qa_report["finding_count"],
            "blocker_count": qa_report["blocker_count"],
            "with_reference_context": qa_report["with_reference_context"],
            "report_path": qa_report_artifact["workspace_path"],
            "report_sha256": qa_report_artifact["sha256"],
            "ruleset_gate_path": qa_gate_artifact["workspace_path"],
            "ruleset_gate_sha256": qa_gate_artifact["sha256"],
        }

        curation_input_sha256 = hashlib.sha256(
            (
                f"{scenarios['scenario_rows_sha256']}|"
                f"{flow_validation['valid_rows_sha256']}|"
                f"{source_validation['valid_rows_sha256']}"
            ).encode("ascii")
        ).hexdigest()
        curation_base_id = (
            f"inventory-curation-queue:{scope_key}:"
            f"{curation_input_sha256[:16]}"
        )
        curation_attempt = self._semantic_attempt(curation_base_id)
        curation_activity_id = (
            f"{curation_base_id}:attempt-{curation_attempt}"
        )
        curation_root = (
            self.workspace
            / "artifacts"
            / "inventory-entity-authoring"
            / f"{scope_id}-{revision}"
            / authoring_version
            / "curation-queue"
            / f"attempt-{curation_attempt}"
        )
        curation_processes = curation_root / "inputs" / "scenario-processes.jsonl"
        curation_flows = curation_root / "inputs" / "canonical-flows.jsonl"
        curation_sources = curation_root / "inputs" / "canonical-sources.jsonl"
        if self._completed_activity(curation_activity_id) is None:
            curation_processes.parent.mkdir(parents=True, exist_ok=True)
            curation_processes.write_bytes(scenario_rows_bytes)
            curation_flows.write_bytes(_jsonl_bytes(validated_flows))
            curation_sources.write_bytes(_jsonl_bytes(validated_sources))
        curation_activity = self.run_activity(
            activity_id=curation_activity_id,
            name="构建 source→flow→scenario process curation queue",
            skill_ref="tidas-data-import/curation-queue",
            command=[
                *prefix,
                "dataset",
                "curation-queue",
                "build",
                "--processes",
                str(curation_processes),
                "--flows",
                str(curation_flows),
                "--support",
                str(curation_sources),
                "--out-dir",
                str(curation_root),
                "--json",
            ],
            artifact_root=curation_root,
            expected_outputs=[
                "inputs/scenario-processes.jsonl",
                "inputs/canonical-flows.jsonl",
                "inputs/canonical-sources.jsonl",
                "outputs/curation-queue-manifest.json",
                "outputs/curation-queue-tasks.jsonl",
                "outputs/curation-queue-locks.json",
                "outputs/curation-queue-blockers.jsonl",
            ],
            effect="local_write",
        )
        curation_artifacts = {
            row["path"]: row for row in curation_activity["artifacts"]
        }
        curation_report_artifact = curation_artifacts[
            "outputs/curation-queue-manifest.json"
        ]
        curation_report = self._load_native_json_report(
            report_path=curation_root
            / "outputs"
            / "curation-queue-manifest.json",
            report_artifact=curation_report_artifact,
            activity_base_id=curation_base_id,
            activity_id=curation_activity_id,
            attempt=curation_attempt,
            scope_key=scope_key,
            gate="inventory-curation-queue",
        )
        try:
            curation_tasks = self._load_jsonl_objects(
                curation_root / "outputs" / "curation-queue-tasks.jsonl"
            )
            curation_blockers = self._load_jsonl_objects(
                curation_root / "outputs" / "curation-queue-blockers.jsonl"
            )
        except (OSError, UnicodeError, ValueError):
            curation_tasks = []
            curation_blockers = [{}]
        curation_counts = curation_report.get("counts")
        expected_task_count = len(source_rows) + len(flow_rows) + 2
        curation_valid = (
            curation_report.get("schema_version") == 1
            and curation_report.get("status") == "ready"
            and isinstance(curation_counts, dict)
            and curation_counts.get("support_rows") == len(source_rows)
            and curation_counts.get("flow_rows") == len(flow_rows)
            and curation_counts.get("process_rows") == 2
            and curation_counts.get("tasks") == expected_task_count
            and curation_counts.get("blockers") == 0
            and len(curation_tasks) == expected_task_count
            and curation_report.get("tasks") == curation_tasks
            and curation_report.get("blockers") == []
            and curation_blockers == []
        )
        if not curation_valid:
            self._record_native_semantic_failure(
                activity_base_id=curation_base_id,
                activity_id=curation_activity_id,
                attempt=curation_attempt,
                scope_key=scope_key,
                gate="inventory-curation-queue",
                summary="Curation queue 未形成 4 source→11 flow→2 process 的无阻塞顺序。",
                report_path=curation_report_artifact["workspace_path"],
                report_sha256=curation_report_artifact["sha256"],
            )
            raise RuntimeError("Inventory curation queue is not ready")
        self._record_native_semantic_acceptance(
            activity_base_id=curation_base_id,
            activity_id=curation_activity_id,
            attempt=curation_attempt,
            scope_key=scope_key,
            gate="inventory-curation-queue",
            report_path=curation_report_artifact["workspace_path"],
            report_sha256=curation_report_artifact["sha256"],
        )
        curation = {
            "status": curation_report["status"],
            "support_rows": curation_counts["support_rows"],
            "flow_rows": curation_counts["flow_rows"],
            "process_rows": curation_counts["process_rows"],
            "task_count": curation_counts["tasks"],
            "blocker_count": curation_counts["blockers"],
            "task_order_sha256": curation_report["hashes"]["task_order"],
            "report_path": curation_report_artifact["workspace_path"],
            "report_sha256": curation_report_artifact["sha256"],
        }

        source_results = [
            {
                "source_id": row["source_id"],
                "tidas_source_id": row["tidas_source_id"],
                "version": "00.00.001",
                "canonical_identifier": row["canonical_identifier"],
            }
            for row in authoring["source_rows"]
        ]
        result = {
            "schema_version": 1,
            "contract": ENTITY_AUTHORING_CONTRACT,
            "scope_id": scope_id,
            "revision": revision,
            "status": (
                "local_entity_rows_validated_qa_ready_support_resolution_pending"
            ),
            "tool_invocation_sha256": tool_invocation_sha256,
            "source_contract_manifest_path": contract_manifest_artifact[
                "workspace_path"
            ],
            "source_contract_manifest_sha256": contract_manifest_artifact[
                "sha256"
            ],
            "source_contract": authoring["source_contract"],
            "flow_count": len(flow_results),
            "source_count": len(source_results),
            "flow_results": flow_results,
            "source_results": source_results,
            "flow_validation": flow_validation,
            "source_validation": source_validation,
            "flow_qa": flow_qa,
            "flow_save_draft": flow_save_draft,
            "source_save_draft": source_save_draft,
            "curation": curation,
            "support_reference_status": authoring["support_reference_status"],
            "remote_duplicate_coverage": (
                "missing" if not identities["remote_candidates_requested"] else "checked"
            ),
            "scenario_rows_path": scenarios["scenario_rows_path"],
            "scenario_rows_sha256": scenarios["scenario_rows_sha256"],
            "scenario_rows_changed": False,
            "remote_save_authorized": False,
            "scientific_comparison_ready": False,
            "next_action": (
                "用 11 个 flow 与四个 source 的 00.00.001 本地 canonical refs "
                "改写隔离场景引用，再重跑 2/2 validation 与逐路线 QA。"
            ),
        }
        result_version = hashlib.sha256(_json_bytes(result)).hexdigest()[:16]
        self.record(
            "risk.flagged",
            {
                "risk_id": f"inventory-entity-support-references:{scope_key}",
                "severity": "medium",
                "summary": (
                    "本地 flow/source rows 已通过 schema、QA 与 dry-run；"
                    "format source、owner contact 和 Energy flow property 仍需远程解析，"
                    "因此 remote save 保持关闭。"
                ),
                "support_reference_status": result["support_reference_status"],
                "flow_count": result["flow_count"],
                "source_count": result["source_count"],
            },
            actor="controller",
            idempotency_key=(
                f"risk:inventory-entity-support-references:{scope_key}:"
                f"{result_version}"
            ),
        )
        event = self.record(
            "research.inventory_entities.materialized",
            result,
            actor="controller",
            idempotency_key=(
                f"inventory-entities:{scope_key}:{result_version}:materialized"
            ),
        )
        self.record(
            "milestone.completed",
            {
                "milestone_id": "inventory-entity-authoring",
                "title": "本地 TIDAS flow/source drafts 已通过原生验证与 curation",
                "status": "completed",
                "next_action": result["next_action"],
            },
            actor="controller",
            idempotency_key=(
                f"milestone:inventory-entity-authoring:{scope_key}:"
                f"{result_version}:completed"
            ),
        )
        self.materialize_views()
        return event["payload"]

    def integrate_inventory_references(
        self,
        *,
        command_prefix: Optional[List[str]] = None,
    ) -> JsonObject:
        """Rewrite isolated scenarios to validated local canonical references."""

        snapshot = self._project(self.events())
        scenarios = snapshot.get("inventory_scenarios")
        identities = snapshot.get("inventory_identities")
        entities = snapshot.get("inventory_entities")
        if not isinstance(scenarios, dict):
            raise ValueError("Reference integration requires validated scenarios")
        if (
            not isinstance(identities, dict)
            or identities.get("flow_resolution_required_count") != 0
            or identities.get("flow_blocker_count") != 0
        ):
            raise ValueError("Reference integration requires accepted flow identities")
        if (
            not isinstance(entities, dict)
            or entities.get("status")
            != "local_entity_rows_validated_qa_ready_support_resolution_pending"
            or entities.get("flow_count") != 11
            or entities.get("source_count") != 4
        ):
            raise ValueError("Reference integration requires validated canonical entities")
        if entities.get("scenario_rows_sha256") != scenarios.get(
            "scenario_rows_sha256"
        ):
            raise RuntimeError("Canonical entities do not bind the current scenarios")
        scope_id = _required_text(entities.get("scope_id"), "scope_id")
        revision = _required_text(entities.get("revision"), "revision")
        scope_key = f"{scope_id}:{revision}"

        def verified_file(
            relative_path: object, expected_hash: object, label: str
        ) -> tuple[Path, bytes]:
            if not isinstance(relative_path, str) or not isinstance(
                expected_hash, str
            ):
                raise ValueError(f"{label} reference is missing")
            path = (self.workspace / relative_path).resolve()
            try:
                path.relative_to(self.workspace)
            except ValueError as error:
                raise ValueError(f"{label} escaped the project workspace") from error
            if not path.is_file():
                raise FileNotFoundError(path)
            content = path.read_bytes()
            if hashlib.sha256(content).hexdigest() != expected_hash:
                raise RuntimeError(f"{label} hash drifted")
            return path, content

        scenario_path, scenario_bytes = verified_file(
            scenarios.get("scenario_rows_path"),
            scenarios.get("scenario_rows_sha256"),
            "scenario rows",
        )
        flow_path, flow_bytes = verified_file(
            entities.get("flow_validation", {}).get("valid_rows_path"),
            entities.get("flow_validation", {}).get("valid_rows_sha256"),
            "canonical flow rows",
        )
        source_path, source_bytes = verified_file(
            entities.get("source_validation", {}).get("valid_rows_path"),
            entities.get("source_validation", {}).get("valid_rows_sha256"),
            "canonical source rows",
        )
        try:
            scenario_rows = self._load_jsonl_objects(scenario_path)
            flow_rows = self._load_jsonl_objects(flow_path)
            source_rows = self._load_jsonl_objects(source_path)
        except (OSError, UnicodeError, ValueError) as error:
            raise ValueError("Canonical reference inputs are not valid JSONL") from error
        if not self._entity_rows_match("flow", flow_rows, flow_rows):
            raise ValueError("Canonical flow rows contain duplicate or missing identities")
        if not self._entity_rows_match("source", source_rows, source_rows):
            raise ValueError("Canonical source rows contain duplicate or missing identities")
        if len(scenario_rows) != 2:
            raise ValueError("Reference integration requires exactly two scenario rows")

        for decision in identities.get("flow_decisions", []):
            if not isinstance(decision, dict):
                raise ValueError("Flow identity decision must be an object")
            verified_file(
                decision.get("report_path"),
                decision.get("report_sha256"),
                f"{decision.get('flow_key')} identity report",
            )
        materialized_flow_rows: List[JsonObject] = []
        for result in entities.get("flow_results", []):
            if not isinstance(result, dict):
                raise ValueError("Flow materialization result must be an object")
            _, materialized_flow_bytes = verified_file(
                result.get("flow_path"),
                result.get("flow_sha256"),
                f"{result.get('flow_key')} canonical flow",
            )
            try:
                materialized_flow = json.loads(materialized_flow_bytes)
            except (UnicodeError, json.JSONDecodeError) as error:
                raise ValueError("Materialized canonical flow is not JSON") from error
            if not isinstance(materialized_flow, dict):
                raise ValueError("Materialized canonical flow must be an object")
            materialized_flow_rows.append(materialized_flow)
            verified_file(
                result.get("gate_report_path"),
                result.get("gate_report_sha256"),
                f"{result.get('flow_key')} flow gate",
            )
        if not self._entity_rows_match("flow", materialized_flow_rows, flow_rows):
            raise RuntimeError("Validated canonical flow rows drifted from materialization")
        _, source_input_bytes = verified_file(
            entities.get("source_validation", {}).get("input_path"),
            entities.get("source_validation", {}).get("input_sha256"),
            "canonical source validation input",
        )
        try:
            source_input_rows = [
                json.loads(line)
                for line in source_input_bytes.decode("utf-8").splitlines()
                if line.strip()
            ]
        except (UnicodeError, json.JSONDecodeError) as error:
            raise ValueError("Canonical source validation input is invalid") from error
        if not self._entity_rows_match("source", source_input_rows, source_rows):
            raise RuntimeError("Validated canonical source rows drifted from authoring")
        for path, digest, label in (
            (
                entities.get("flow_validation", {}).get("report_path"),
                entities.get("flow_validation", {}).get("report_sha256"),
                "canonical flow validation report",
            ),
            (
                entities.get("source_validation", {}).get("report_path"),
                entities.get("source_validation", {}).get("report_sha256"),
                "canonical source validation report",
            ),
            (
                entities.get("flow_qa", {}).get("report_path"),
                entities.get("flow_qa", {}).get("report_sha256"),
                "canonical flow QA report",
            ),
            (
                entities.get("curation", {}).get("report_path"),
                entities.get("curation", {}).get("report_sha256"),
                "canonical curation report",
            ),
        ):
            verified_file(path, digest, label)
        entity_evidence = {
            "entity_contract": entities.get("contract"),
            "flow_rows_path": entities["flow_validation"]["valid_rows_path"],
            "flow_rows_sha256": entities["flow_validation"][
                "valid_rows_sha256"
            ],
            "source_rows_path": entities["source_validation"]["valid_rows_path"],
            "source_rows_sha256": entities["source_validation"][
                "valid_rows_sha256"
            ],
            "flow_qa_report_path": entities["flow_qa"]["report_path"],
            "flow_qa_report_sha256": entities["flow_qa"]["report_sha256"],
            "curation_report_path": entities["curation"]["report_path"],
            "curation_report_sha256": entities["curation"]["report_sha256"],
        }
        compiled_patch = compile_inventory_reference_integration(
            scenario_rows,
            flow_rows,
            source_rows,
            scenarios.get("scenario_processes", []),
            entity_evidence=entity_evidence,
        )
        expected_rows = apply_inventory_reference_patch(
            scenario_rows, compiled_patch
        )
        expected_rows_sha256 = hashlib.sha256(
            _jsonl_bytes(expected_rows)
        ).hexdigest()
        protected_before = compiled_patch["protected_scenario_sha256_before"]
        protected_after = protected_scenario_sha256(expected_rows)
        if protected_before != protected_after:
            raise RuntimeError("Reference compiler changed protected scientific content")

        prefix = command_prefix or [
            "npm",
            "exec",
            "--yes",
            f"--package={self.TIANGONG_CLI_PACKAGE}",
            "--",
            "tiangong-lca",
        ]
        tool_invocation_sha256 = self._tool_invocation_sha256(prefix)
        patch_sha256 = hashlib.sha256(_json_bytes(compiled_patch)).hexdigest()
        integration_version = hashlib.sha256(
            (
                f"{scenarios['scenario_rows_sha256']}|"
                f"{entities['flow_validation']['valid_rows_sha256']}|"
                f"{entities['source_validation']['valid_rows_sha256']}|"
                f"{patch_sha256}|{self.TIANGONG_CLI_PACKAGE}|"
                f"{REFERENCE_INTEGRATION_CONTRACT}|{tool_invocation_sha256}"
            ).encode("ascii")
        ).hexdigest()[:16]
        base_id = f"inventory-reference-patch:{scope_key}:{integration_version}"
        attempt = self._semantic_attempt(base_id)
        activity_id = f"{base_id}:attempt-{attempt}"
        root = (
            self.workspace
            / "artifacts"
            / "inventory-reference-integration"
            / f"{scope_id}-{revision}"
            / integration_version
            / f"attempt-{attempt}"
        )
        inputs = root / "inputs"
        outputs = root / "outputs"
        scenario_input = inputs / "scenario-processes.jsonl"
        flow_input = inputs / "canonical-flows.jsonl"
        source_input = inputs / "canonical-sources.jsonl"
        patch_input = inputs / "reference-patches.json"
        integrated_output = outputs / "integrated-scenario-processes.jsonl"
        self.record(
            "milestone.started",
            {
                "milestone_id": "canonical-inventory-reference-integration",
                "title": "把本地 canonical Flow/Source 引用接入隔离场景",
                "status": "running",
                "next_action": (
                    "只改写 identity reference，再做 2/2 validation 与逐路线 Process QA"
                ),
                "terms": [
                    {
                        "term": "引用治理",
                        "explanation": (
                            "把 process 中的临时 UUID/version/URI 指向已验证实体；"
                            "不改变清单数值或科学假设。"
                        ),
                    }
                ],
            },
            actor="controller",
            idempotency_key=(
                f"milestone:inventory-reference-integration:{scope_key}:"
                f"{integration_version}:started"
            ),
        )
        if self._completed_activity(activity_id) is None:
            inputs.mkdir(parents=True, exist_ok=True)
            scenario_input.write_bytes(scenario_bytes)
            flow_input.write_bytes(flow_bytes)
            source_input.write_bytes(source_bytes)
            _write_json(patch_input, compiled_patch)
        activity = self.run_activity(
            activity_id=activity_id,
            name="用 TianGong dataset patch apply 治理隔离场景实体引用",
            skill_ref="process-automated-builder/dataset-patch-apply",
            command=[
                *prefix,
                "dataset",
                "patch",
                "apply",
                "--input",
                str(scenario_input),
                "--patch",
                str(patch_input),
                "--out",
                str(integrated_output),
                "--out-dir",
                str(root),
                "--json",
            ],
            artifact_root=root,
            expected_outputs=[
                "inputs/scenario-processes.jsonl",
                "inputs/canonical-flows.jsonl",
                "inputs/canonical-sources.jsonl",
                "inputs/reference-patches.json",
                "outputs/integrated-scenario-processes.jsonl",
                "outputs/patch-evidence.jsonl",
                "outputs/dataset-patch-apply-report.json",
            ],
            effect="local_write",
        )
        artifacts = {row["path"]: row for row in activity["artifacts"]}
        patch_report_artifact = artifacts[
            "outputs/dataset-patch-apply-report.json"
        ]
        patch_report = self._load_native_json_report(
            report_path=outputs / "dataset-patch-apply-report.json",
            report_artifact=patch_report_artifact,
            activity_base_id=base_id,
            activity_id=activity_id,
            attempt=attempt,
            scope_key=scope_key,
            gate="inventory-reference-patch",
        )
        try:
            patch_evidence = self._load_jsonl_objects(
                outputs / "patch-evidence.jsonl"
            )
            integrated_rows = self._load_jsonl_objects(integrated_output)
        except (OSError, UnicodeError, ValueError) as error:
            self._record_native_semantic_failure(
                activity_base_id=base_id,
                activity_id=activity_id,
                attempt=attempt,
                scope_key=scope_key,
                gate="inventory-reference-patch",
                summary=f"引用 patch 输出不是有效 JSONL：{error}",
                report_path=patch_report_artifact["workspace_path"],
                report_sha256=patch_report_artifact["sha256"],
            )
            raise RuntimeError("Native reference patch output is invalid") from error
        patch_valid = (
            self._scenario_patch_report_is_valid(
                patch_report, patch_evidence, compiled_patch
            )
            and self._process_rows_match(expected_rows, integrated_rows)
            and hashlib.sha256(_jsonl_bytes(integrated_rows)).hexdigest()
            == expected_rows_sha256
            and protected_scenario_sha256(integrated_rows) == protected_before
        )
        if not patch_valid:
            self._record_native_semantic_failure(
                activity_base_id=base_id,
                activity_id=activity_id,
                attempt=attempt,
                scope_key=scope_key,
                gate="inventory-reference-patch",
                summary="原生 patch 报告、证据、canonical refs 或保护字段未匹配编译合同。",
                report_path=patch_report_artifact["workspace_path"],
                report_sha256=patch_report_artifact["sha256"],
            )
            raise RuntimeError("Native reference patch failed semantic validation")
        self._record_native_semantic_acceptance(
            activity_base_id=base_id,
            activity_id=activity_id,
            attempt=attempt,
            scope_key=scope_key,
            gate="inventory-reference-patch",
            report_path=patch_report_artifact["workspace_path"],
            report_sha256=patch_report_artifact["sha256"],
        )
        integrated_artifact = artifacts[
            "outputs/integrated-scenario-processes.jsonl"
        ]

        validation_version = hashlib.sha256(
            (
                f"{integrated_artifact['sha256']}|{self.TIANGONG_CLI_PACKAGE}|"
                f"inventory-reference-validation/v1|{tool_invocation_sha256}"
            ).encode("ascii")
        ).hexdigest()[:16]
        validation_base_id = (
            f"inventory-reference-validation:{scope_key}:{validation_version}"
        )
        validation_attempt = self._semantic_attempt(validation_base_id)
        validation_activity_id = (
            f"{validation_base_id}:attempt-{validation_attempt}"
        )
        validation_root = (
            root
            / "dataset-validation"
            / validation_version
            / f"attempt-{validation_attempt}"
        )
        validation_input = validation_root / "inputs" / "scenario-processes.jsonl"
        if self._completed_activity(validation_activity_id) is None:
            validation_input.parent.mkdir(parents=True, exist_ok=True)
            validation_input.write_bytes(integrated_output.read_bytes())
        validation_activity = self.run_activity(
            activity_id=validation_activity_id,
            name="验证 canonical reference 场景 TIDAS schema",
            skill_ref="tidas-data-import/dataset-validate",
            command=[
                *prefix,
                "dataset",
                "validate",
                "--input",
                str(validation_input),
                "--type",
                "process",
                "--out-dir",
                str(validation_root),
                "--json",
            ],
            artifact_root=validation_root,
            expected_outputs=[
                "inputs/scenario-processes.jsonl",
                "outputs/validation-report.json",
                "outputs/valid-rows.jsonl",
                "outputs/invalid-rows.jsonl",
            ],
            effect="local_write",
            accepted_exit_codes={0, 1},
        )
        validation_artifacts = {
            row["path"]: row for row in validation_activity["artifacts"]
        }
        validation_report_artifact = validation_artifacts[
            "outputs/validation-report.json"
        ]
        validation_report = self._load_native_json_report(
            report_path=validation_root / "outputs" / "validation-report.json",
            report_artifact=validation_report_artifact,
            activity_base_id=validation_base_id,
            activity_id=validation_activity_id,
            attempt=validation_attempt,
            scope_key=scope_key,
            gate="inventory-reference-validation",
        )
        counts = validation_report.get("counts")
        report_rows = validation_report.get("rows")
        scenario_ids = {
            row["scenario_process_id"]
            for row in compiled_patch["scenario_processes"]
        }
        try:
            valid_rows = self._load_jsonl_objects(
                validation_root / "outputs" / "valid-rows.jsonl"
            )
            invalid_rows = self._load_jsonl_objects(
                validation_root / "outputs" / "invalid-rows.jsonl"
            )
        except (OSError, UnicodeError, ValueError):
            valid_rows = []
            invalid_rows = [{}]
        validation_valid = (
            validation_report.get("requested_type") == "process"
            and validation_report.get("status") == "completed"
            and isinstance(counts, dict)
            and counts.get("total") == 2
            and counts.get("valid") == 2
            and counts.get("invalid") == 0
            and isinstance(report_rows, list)
            and len(report_rows) == 2
            and {
                row.get("id")
                for row in report_rows
                if isinstance(row, dict)
                and row.get("type") == "process"
                and row.get("status") == "valid"
                and row.get("issue_count") == 0
                and row.get("issues") == []
            }
            == scenario_ids
            and self._process_rows_match(integrated_rows, valid_rows)
            and invalid_rows == []
        )
        if not validation_valid:
            self._record_native_semantic_failure(
                activity_base_id=validation_base_id,
                activity_id=validation_activity_id,
                attempt=validation_attempt,
                scope_key=scope_key,
                gate="inventory-reference-validation",
                summary="Canonical reference 场景未通过 2/2 原生 validation。",
                report_path=validation_report_artifact["workspace_path"],
                report_sha256=validation_report_artifact["sha256"],
            )
            raise RuntimeError("Integrated reference scenarios failed validation")
        self._record_native_semantic_acceptance(
            activity_base_id=validation_base_id,
            activity_id=validation_activity_id,
            attempt=validation_attempt,
            scope_key=scope_key,
            gate="inventory-reference-validation",
            report_path=validation_report_artifact["workspace_path"],
            report_sha256=validation_report_artifact["sha256"],
        )

        rows_by_id = {
            self._process_payload_id(row): row for row in integrated_rows
        }
        route_qa: List[JsonObject] = []
        qa_expected_outputs = [
            "inputs/scenario-process.jsonl",
            "qa-input-summary.json",
            "qa-input/materialization-summary.json",
            "one_flow_rerun_timing.md",
            "one_flow_rerun_qa_v2_1_zh.md",
            "one_flow_rerun_qa_v2_1_en.md",
            "flow_unit_issue_log.md",
            "qa_summary_v2_1.json",
            "process-qa-rule-findings.jsonl",
            "process-qa-ruleset-gate.json",
            "process-qa-report.json",
        ]
        for scenario_ref in compiled_patch["scenario_processes"]:
            route_id = scenario_ref["route_id"]
            scenario_id = scenario_ref["scenario_process_id"]
            scenario_row = rows_by_id.get(scenario_id)
            if not isinstance(scenario_row, dict):
                raise RuntimeError(f"Integrated scenario missing for {route_id}")
            row_sha256 = hashlib.sha256(_json_bytes(scenario_row)).hexdigest()
            qa_version = hashlib.sha256(
                (
                    f"{row_sha256}|{self.TIANGONG_CLI_PACKAGE}|"
                    f"{PROCESS_QA_LOGIC_VERSION}|{PROCESS_QA_RULESET_ID}/"
                    f"{PROCESS_QA_RULESET_VERSION}|canonical-reference-v1|"
                    f"{tool_invocation_sha256}"
                ).encode("ascii")
            ).hexdigest()[:16]
            qa_base_id = (
                f"inventory-reference-qa:{scope_key}:{route_id}:{qa_version}"
            )
            qa_attempt = self._semantic_attempt(qa_base_id)
            qa_activity_id = f"{qa_base_id}:attempt-{qa_attempt}"
            qa_root = (
                root
                / "process-qa"
                / route_id
                / qa_version
                / f"attempt-{qa_attempt}"
            )
            qa_input = qa_root / "inputs" / "scenario-process.jsonl"
            if self._completed_activity(qa_activity_id) is None:
                qa_input.parent.mkdir(parents=True, exist_ok=True)
                qa_input.write_bytes(_jsonl_bytes([scenario_row]))
            qa_activity = self.run_activity(
                activity_id=qa_activity_id,
                name=f"运行 {route_id} canonical-reference Process QA",
                skill_ref="lifecycleinventory-review/process",
                command=[
                    *prefix,
                    "qa",
                    "process",
                    "--rows-file",
                    str(qa_input),
                    "--out-dir",
                    str(qa_root),
                    "--logic-version",
                    PROCESS_QA_LOGIC_VERSION,
                    "--json",
                ],
                artifact_root=qa_root,
                expected_outputs=qa_expected_outputs,
                effect="local_write",
            )
            qa_artifacts = {
                row["path"]: row for row in qa_activity["artifacts"]
            }
            qa_report_artifact = qa_artifacts["process-qa-report.json"]
            qa_report = self._load_native_json_report(
                report_path=qa_root / "process-qa-report.json",
                report_artifact=qa_report_artifact,
                activity_base_id=qa_base_id,
                activity_id=qa_activity_id,
                attempt=qa_attempt,
                scope_key=scope_key,
                gate="inventory-reference-process-qa",
                route_id=route_id,
            )
            gate_artifact = qa_artifacts["process-qa-ruleset-gate.json"]
            gate = self._load_native_json_report(
                report_path=qa_root / "process-qa-ruleset-gate.json",
                report_artifact=gate_artifact,
                activity_base_id=qa_base_id,
                activity_id=qa_activity_id,
                attempt=qa_attempt,
                scope_key=scope_key,
                gate="inventory-reference-process-qa",
                route_id=route_id,
            )
            materialization_artifact = qa_artifacts[
                "qa-input/materialization-summary.json"
            ]
            materialization = self._load_native_json_report(
                report_path=qa_root / "qa-input" / "materialization-summary.json",
                report_artifact=materialization_artifact,
                activity_base_id=qa_base_id,
                activity_id=qa_activity_id,
                attempt=qa_attempt,
                scope_key=scope_key,
                gate="inventory-reference-process-qa",
                route_id=route_id,
            )
            try:
                findings = self._load_jsonl_objects(
                    qa_root / "process-qa-rule-findings.jsonl"
                )
            except (OSError, UnicodeError, ValueError):
                findings = [{}]
            profile = self._process_inventory_profiles([scenario_row])[0]
            qa_valid = (
                self._process_qa_report_is_valid(
                    qa_report, findings, gate, {scenario_id}
                )
                and self._process_qa_target_is_valid(
                    materialization,
                    expected_process_id=scenario_id,
                    expected_version=scenario_ref["dataset_version"],
                    expected_input_path=qa_input,
                )
                and self._scenario_qa_matches_expectations(
                    qa_report, findings, profile, scenario_ref
                )
            )
            if not qa_valid:
                self._record_native_semantic_failure(
                    activity_base_id=qa_base_id,
                    activity_id=qa_activity_id,
                    attempt=qa_attempt,
                    scope_key=scope_key,
                    gate="inventory-reference-process-qa",
                    route_id=route_id,
                    summary=f"{route_id} canonical-reference QA 未绑定预期目标/汇总。",
                    report_path=qa_report_artifact["workspace_path"],
                    report_sha256=qa_report_artifact["sha256"],
                )
                raise RuntimeError(f"Integrated scenario QA failed for {route_id}")
            self._record_native_semantic_acceptance(
                activity_base_id=qa_base_id,
                activity_id=qa_activity_id,
                attempt=qa_attempt,
                scope_key=scope_key,
                gate="inventory-reference-process-qa",
                route_id=route_id,
                report_path=qa_report_artifact["workspace_path"],
                report_sha256=qa_report_artifact["sha256"],
            )
            totals = qa_report["totals"]
            route_qa.append(
                {
                    "route_id": route_id,
                    "scenario_process_id": scenario_id,
                    "status": qa_report["status"],
                    "gate_status": qa_report["ruleset_gate"]["status"],
                    "finding_count": qa_report["rule_finding_count"],
                    "blocker_count": qa_report["blocker_count"],
                    "raw_input": totals["raw_input"],
                    "product_output": totals[
                        "product_plus_byproduct_plus_waste"
                    ],
                    "energy_excluded": totals["energy_excluded"],
                    "positive_input_exchange_count": profile[
                        "positive_input_exchange_count"
                    ],
                    "positive_output_exchange_count": profile[
                        "positive_output_exchange_count"
                    ],
                    "has_positive_input": profile["has_positive_input"],
                    "has_positive_output": profile["has_positive_output"],
                    "report_path": qa_report_artifact["workspace_path"],
                    "report_sha256": qa_report_artifact["sha256"],
                    "findings_path": qa_artifacts[
                        "process-qa-rule-findings.jsonl"
                    ]["workspace_path"],
                    "ruleset_gate_path": gate_artifact["workspace_path"],
                }
            )

        total_findings = sum(row["finding_count"] for row in route_qa)
        total_blockers = sum(row["blocker_count"] for row in route_qa)
        for process_ref in scenarios.get("base_processes", []):
            if not isinstance(process_ref, dict):
                raise ValueError("Registered base process reference is malformed")
            verified_file(
                process_ref.get("process_path"),
                process_ref.get("process_sha256"),
                f"{process_ref.get('route_id')} base process",
            )
        status = (
            "canonical_references_integrated_qa_blocked"
            if total_blockers
            else (
                "canonical_references_integrated_schema_valid_qa_needs_review"
                if total_findings
                else "canonical_references_integrated_schema_valid_qa_passed"
            )
        )
        next_action = (
            "按对路线比较结论的影响排序科学缺口，优先实现最高影响的证据/模型切片；"
            "继续保留本地 canonical 与远程发布边界。"
        )
        result = {
            "schema_version": 1,
            "contract": REFERENCE_INTEGRATION_CONTRACT,
            "scope_id": scope_id,
            "revision": revision,
            "status": status,
            "tool_invocation_sha256": tool_invocation_sha256,
            "previous_scenario_rows_path": scenarios["scenario_rows_path"],
            "previous_scenario_rows_sha256": scenarios["scenario_rows_sha256"],
            "integrated_scenario_rows_path": integrated_artifact["workspace_path"],
            "integrated_scenario_rows_sha256": integrated_artifact["sha256"],
            "scenario_processes": compiled_patch["scenario_processes"],
            "reference_counts": compiled_patch["reference_counts"],
            "canonical_entity_counts": compiled_patch["canonical_entity_counts"],
            "referenced_source_count": compiled_patch["referenced_source_count"],
            "patch_apply": {
                "status": patch_report["status"],
                "operation_count": patch_report["operation_count"],
                "applied_operation_count": patch_report[
                    "applied_operation_count"
                ],
                "evidence_count": patch_report["evidence_count"],
                "patch_path": artifacts["inputs/reference-patches.json"][
                    "workspace_path"
                ],
                "patch_sha256": artifacts["inputs/reference-patches.json"][
                    "sha256"
                ],
                "report_path": patch_report_artifact["workspace_path"],
                "report_sha256": patch_report_artifact["sha256"],
                "evidence_path": artifacts["outputs/patch-evidence.jsonl"][
                    "workspace_path"
                ],
                "evidence_sha256": artifacts["outputs/patch-evidence.jsonl"][
                    "sha256"
                ],
            },
            "dataset_validation": {
                "status": validation_report["status"],
                "total": counts["total"],
                "valid": counts["valid"],
                "invalid": counts["invalid"],
                "report_path": validation_report_artifact["workspace_path"],
                "report_sha256": validation_report_artifact["sha256"],
            },
            "route_qa": route_qa,
            "qa_finding_count": total_findings,
            "qa_blocker_count": total_blockers,
            "preservation": {
                "protected_scenario_sha256_before": protected_before,
                "protected_scenario_sha256_after": protected_scenario_sha256(
                    integrated_rows
                ),
                "scientific_values_changed": False,
                "base_processes_unchanged": True,
            },
            "remote_duplicate_coverage": entities["remote_duplicate_coverage"],
            "support_reference_status": entities["support_reference_status"],
            "remote_save_authorized": False,
            "scientific_comparison_ready": False,
            "next_action": next_action,
        }
        result_version = hashlib.sha256(_json_bytes(result)).hexdigest()[:16]
        if f"screening-scenario-identity:{scope_key}" in {
            risk.get("risk_id")
            for risk in self._project(self.events())["unresolved_risks"]
        }:
            self.record(
                "risk.resolved",
                {
                    "risk_id": f"screening-scenario-identity:{scope_key}",
                    "resolution": "local_canonical_references_integrated",
                    "result_version": result_version,
                },
                actor="controller",
                idempotency_key=(
                    f"risk:screening-scenario-identity:{scope_key}:resolved:"
                    f"{result_version}"
                ),
            )
        self.record(
            "risk.flagged",
            {
                "risk_id": f"canonical-reference-local-only:{scope_key}",
                "severity": "medium",
                "summary": (
                    "隔离场景已使用本地 canonical refs，但远程 duplicate/support "
                    "coverage 仍未闭合，remote save 与发布保持关闭。"
                ),
                "remote_duplicate_coverage": result["remote_duplicate_coverage"],
                "support_reference_status": result["support_reference_status"],
            },
            actor="controller",
            idempotency_key=(
                f"risk:canonical-reference-local-only:{scope_key}:{result_version}"
            ),
        )
        self._sync_screening_scenario_qa_risk(
            scope_key=scope_key,
            total_findings=total_findings,
            total_blockers=total_blockers,
            route_qa=route_qa,
            result_version=result_version,
        )
        self.record(
            "decision.recorded",
            {
                "decision_id": (
                    f"inventory-reference-integration:{scope_key}:{result_version}"
                ),
                "decision_type": "inventory.canonical_references.integrated",
                "status": status,
                "scientific_values_changed": False,
                "integrated_scenario_rows_path": result[
                    "integrated_scenario_rows_path"
                ],
                "integrated_scenario_rows_sha256": result[
                    "integrated_scenario_rows_sha256"
                ],
            },
            actor="controller",
            idempotency_key=(
                f"decision:inventory-reference-integration:{scope_key}:"
                f"{result_version}"
            ),
        )
        event = self.record(
            "research.inventory_references.integrated",
            result,
            actor="controller",
            idempotency_key=(
                f"inventory-references:{scope_key}:{result_version}:integrated"
            ),
        )
        if total_blockers:
            self.record(
                "milestone.started",
                {
                    "milestone_id": "canonical-inventory-reference-qa-repair",
                    "title": "Canonical reference 场景需要修复 QA blocker",
                    "status": "running",
                    "next_action": "先修复 QA blocker，再进入科学缺口排序。",
                },
                actor="controller",
                idempotency_key=(
                    f"milestone:inventory-reference-qa-repair:{scope_key}:"
                    f"{result_version}:started"
                ),
            )
        else:
            self.record(
                "milestone.completed",
                {
                    "milestone_id": "canonical-inventory-reference-integration",
                    "title": "本地 canonical refs 已接入隔离场景并通过原生复验",
                    "status": "completed",
                    "next_action": next_action,
                },
                actor="controller",
                idempotency_key=(
                    f"milestone:inventory-reference-integration:{scope_key}:"
                    f"{result_version}:completed"
                ),
            )
        self.materialize_views()
        return event["payload"]

    @staticmethod
    def _evidence_record_matches_performance(
        record: JsonObject, performance: JsonObject
    ) -> bool:
        if not isinstance(record, dict):
            return False
        source = performance["source"]
        if (
            record.get("url") != source["record_url"]
            or record.get("title") != source["title"]
        ):
            return False
        snippet = record.get("snippet")
        if not isinstance(snippet, str):
            return False
        required_phrases = [
            performance["value_unit"],
            performance["protocol"]["current_density"]["unit"],
            performance["protocol"]["product_modification"],
            performance["protocol"]["carbon_precursor"],
            *[row["route_id"] for row in performance["measurements"]],
        ]
        if any(phrase.lower() not in snippet.lower() for phrase in required_phrases):
            return False

        def contains_number(value: float) -> bool:
            token = format(float(value), ".15g")
            return bool(
                re.search(
                    rf"(?<![\d.]){re.escape(token)}(?:\.0+)?(?![\d.])",
                    snippet,
                )
            )

        for measurement in performance["measurements"]:
            route_token = re.escape(measurement["route_id"])
            value_token = re.escape(format(float(measurement["value"]), ".15g"))
            value_unit = re.escape(performance["value_unit"])
            if not re.search(
                rf"\b{route_token}\s*[:=]\s*{value_token}(?:\.0+)?\s*{value_unit}\b",
                snippet,
                flags=re.IGNORECASE,
            ):
                return False

        numbers = [
            *[row["value"] for row in performance["measurements"]],
            performance["protocol"]["c_rate"],
            performance["protocol"]["current_density"]["value"],
            performance["protocol"]["cycle"],
        ]
        return all(contains_number(value) for value in numbers)

    def _record_native_semantic_failure(
        self,
        *,
        activity_base_id: str,
        activity_id: str,
        attempt: int,
        scope_key: str,
        gate: str,
        summary: str,
        report_path: str,
        report_sha256: str,
        route_id: Optional[str] = None,
    ) -> None:
        subject = route_id or "scope"
        version = report_sha256[:16]
        risk_id = f"native-semantic-check:{scope_key}:{gate}:{subject}"
        self.record(
            "activity.semantic_rejected",
            {
                "activity_base_id": activity_base_id,
                "activity_id": activity_id,
                "attempt": attempt,
                "gate": gate,
                "route_id": route_id,
                "report_path": report_path,
                "report_sha256": report_sha256,
                "reason": summary,
            },
            actor="controller",
            idempotency_key=(
                f"activity:{activity_id}:semantic-rejected:{version}"
            ),
        )
        self.record(
            "risk.flagged",
            {
                "risk_id": risk_id,
                "severity": "high",
                "summary": summary,
                "gate": gate,
                "route_id": route_id,
                "report_path": report_path,
                "report_sha256": report_sha256,
            },
            actor="controller",
            idempotency_key=f"risk:{risk_id}:{version}",
        )
        self.record(
            "milestone.started",
            {
                "milestone_id": "release-gate-semantic-repair",
                "title": "原生 Release Gate 报告语义绑定失败",
                "status": "blocked",
                "next_action": (
                    f"修复 {gate} 的来源/目标绑定后，以同一输入运行新的 attempt"
                ),
            },
            actor="controller",
            idempotency_key=f"milestone:{risk_id}:{version}:started",
        )
        self.materialize_views()

    def _semantic_attempt(self, activity_base_id: str) -> int:
        attempts: set[int] = set()
        failed_pattern = re.compile(
            rf"^{re.escape(activity_base_id)}:attempt-(\d+)$"
        )
        for event in self.events():
            payload = event.get("payload", {})
            if (
                event.get("event_type") == "activity.semantic_rejected"
                and payload.get("activity_base_id") == activity_base_id
                and isinstance(payload.get("attempt"), int)
                and not isinstance(payload.get("attempt"), bool)
            ):
                attempts.add(payload["attempt"])
                continue
            if event.get("event_type") != "activity.failed":
                continue
            activity_id = payload.get("activity_id")
            if not isinstance(activity_id, str):
                continue
            match = failed_pattern.fullmatch(activity_id)
            if match:
                self._verify_failed_activity_evidence(payload)
                attempts.add(int(match.group(1)))
        return max(attempts, default=0) + 1

    def _record_native_semantic_acceptance(
        self,
        *,
        activity_base_id: str,
        activity_id: str,
        attempt: int,
        scope_key: str,
        gate: str,
        report_path: str,
        report_sha256: str,
        route_id: Optional[str] = None,
    ) -> None:
        subject = route_id or "scope"
        self.record(
            "activity.semantic_accepted",
            {
                "activity_base_id": activity_base_id,
                "activity_id": activity_id,
                "attempt": attempt,
                "gate": gate,
                "route_id": route_id,
                "report_path": report_path,
                "report_sha256": report_sha256,
            },
            actor="controller",
            idempotency_key=(
                f"activity:{activity_id}:semantic-accepted:{report_sha256[:16]}"
            ),
        )
        risk_id = f"native-semantic-check:{scope_key}:{gate}:{subject}"
        if any(
            risk.get("risk_id") == risk_id
            for risk in self._project(self.events())["unresolved_risks"]
        ):
            self.record(
                "risk.resolved",
                {
                    "risk_id": risk_id,
                    "resolution": "new_semantic_attempt_accepted",
                    "accepted_activity_id": activity_id,
                    "accepted_attempt": attempt,
                    "report_sha256": report_sha256,
                },
                actor="controller",
                idempotency_key=(
                    f"risk:{risk_id}:resolved:{report_sha256[:16]}"
                ),
            )

    def _load_native_json_report(
        self,
        *,
        report_path: Path,
        report_artifact: JsonObject,
        activity_base_id: str,
        activity_id: str,
        attempt: int,
        scope_key: str,
        gate: str,
        route_id: Optional[str] = None,
    ) -> JsonObject:
        try:
            report = json.loads(report_path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError) as error:
            self._record_native_semantic_failure(
                activity_base_id=activity_base_id,
                activity_id=activity_id,
                attempt=attempt,
                scope_key=scope_key,
                gate=gate,
                route_id=route_id,
                summary=f"{gate} 原生报告无法解析为 JSON object：{error}",
                report_path=report_artifact["workspace_path"],
                report_sha256=report_artifact["sha256"],
            )
            raise RuntimeError(f"Native {gate} report is not valid JSON") from error
        if not isinstance(report, dict):
            self._record_native_semantic_failure(
                activity_base_id=activity_base_id,
                activity_id=activity_id,
                attempt=attempt,
                scope_key=scope_key,
                gate=gate,
                route_id=route_id,
                summary=f"{gate} 原生报告不是 JSON object。",
                report_path=report_artifact["workspace_path"],
                report_sha256=report_artifact["sha256"],
            )
            raise RuntimeError(f"Native {gate} report must be a JSON object")
        return report

    def resolve_release_gates(
        self,
        scope: JsonObject,
        *,
        revision: str,
        performance_evidence: JsonObject,
        search_results: JsonObject,
        command_prefix: Optional[List[str]] = None,
        scope_source_ref: Optional[JsonObject] = None,
        performance_source_ref: Optional[JsonObject] = None,
        search_results_source_ref: Optional[JsonObject] = None,
    ) -> JsonObject:
        """Resolve identity and mass-functional-unit gates with native evidence artifacts."""
        canonical = self.define_comparative_scope(
            scope, revision=revision, source_ref=scope_source_ref
        )
        scope_provenance = self._project(self.events())["scope_provenance"]
        performance = evaluate_route_performance(
            performance_evidence, canonical, performance_source_ref
        )
        search_source = _verified_json_source(
            search_results,
            search_results_source_ref,
            "search_results_source_ref",
        )
        prefix = command_prefix or [
            "npm",
            "exec",
            "--yes",
            f"--package={self.TIANGONG_CLI_PACKAGE}",
            "--",
            "tiangong-lca",
        ]
        scope_key = f"{canonical['scope_id']}:{canonical['revision']}"
        evidence_hash = performance["provenance"]["canonical_sha256"]
        search_hash = hashlib.sha256(_json_bytes(search_results)).hexdigest()
        evidence_version = hashlib.sha256(
            f"{evidence_hash}|{search_hash}".encode("ascii")
        ).hexdigest()[:16]
        evidence_activity_base_id = (
            f"performance-evidence:{scope_key}:{evidence_version}"
        )
        evidence_attempt = self._semantic_attempt(evidence_activity_base_id)
        evidence_activity_id = (
            f"{evidence_activity_base_id}:attempt-{evidence_attempt}"
        )
        evidence_root = (
            self.workspace
            / "artifacts"
            / "release-gates"
            / f"{canonical['scope_id']}-{canonical['revision']}"
            / "performance"
            / evidence_version
            / f"attempt-{evidence_attempt}"
        )
        evidence_input_dir = evidence_root / "inputs"
        evidence_path = evidence_input_dir / "performance-evidence.json"
        search_results_path = evidence_input_dir / "search-results.json"
        search_request_path = evidence_input_dir / "evidence-search-request.json"
        request = evidence_search_request(performance)
        if self._completed_activity(evidence_activity_id) is None:
            evidence_input_dir.mkdir(parents=True, exist_ok=True)
            _write_json(evidence_path, performance["provenance"]["original_input"])
            _write_json(search_results_path, search_results)
            _write_json(search_request_path, request)
        evidence_activity = self.run_activity(
            activity_id=evidence_activity_id,
            name="用 TianGong 规范化双路线性能证据",
            skill_ref="process-automated-builder/dataset-evidence-search",
            command=[
                *prefix,
                "dataset",
                "evidence-search",
                "run",
                "--input",
                str(search_request_path),
                "--results",
                str(search_results_path),
                "--out-dir",
                str(evidence_root),
                "--json",
            ],
            artifact_root=evidence_root,
            expected_outputs=[
                "inputs/performance-evidence.json",
                "inputs/search-results.json",
                "inputs/evidence-search-request.json",
                "outputs/evidence-search-plan.json",
                "outputs/evidence-search-results.jsonl",
                "outputs/evidence-search-report.json",
            ],
            effect="local_write",
        )
        evidence_artifacts = {
            artifact["path"]: artifact for artifact in evidence_activity["artifacts"]
        }
        evidence_report_path = evidence_root / "outputs" / "evidence-search-report.json"
        report_artifact = evidence_artifacts[
            "outputs/evidence-search-report.json"
        ]
        evidence_report = self._load_native_json_report(
            report_path=evidence_report_path,
            report_artifact=report_artifact,
            activity_base_id=evidence_activity_base_id,
            activity_id=evidence_activity_id,
            attempt=evidence_attempt,
            scope_key=scope_key,
            gate="evidence-search",
        )
        normalized_result_artifact = evidence_artifacts[
            "outputs/evidence-search-results.jsonl"
        ]
        try:
            normalized_result_text = (
                evidence_root / "outputs" / "evidence-search-results.jsonl"
            ).read_text(encoding="utf-8")
            normalized_records = []
            for line_number, line in enumerate(
                normalized_result_text.splitlines(), start=1
            ):
                if not line.strip():
                    continue
                row = json.loads(line)
                if not isinstance(row, dict):
                    raise ValueError(
                        f"line {line_number} is not a JSON object"
                    )
                normalized_records.append(row)
            if not normalized_records:
                raise ValueError("evidence-search results contain no records")
        except (
            OSError,
            UnicodeError,
            json.JSONDecodeError,
            ValueError,
        ) as error:
            self._record_native_semantic_failure(
                activity_base_id=evidence_activity_base_id,
                activity_id=evidence_activity_id,
                attempt=evidence_attempt,
                scope_key=scope_key,
                gate="evidence-search",
                summary=f"TianGong evidence-search 规范化结果不是有效 JSONL object 记录：{error}",
                report_path=normalized_result_artifact["workspace_path"],
                report_sha256=normalized_result_artifact["sha256"],
            )
            raise RuntimeError(
                "Native evidence-search results are not valid JSONL objects"
            ) from error
        evidence_quality = evidence_report.get("evidence_quality")
        if (
            evidence_report.get("schema_version") != 1
            or evidence_report.get("status") != "completed_with_evidence"
            or not isinstance(evidence_quality, dict)
            or evidence_quality.get("sufficient") is not True
            or not any(
                self._evidence_record_matches_performance(row, performance)
                for row in normalized_records
            )
        ):
            self._record_native_semantic_failure(
                activity_base_id=evidence_activity_base_id,
                activity_id=evidence_activity_id,
                attempt=evidence_attempt,
                scope_key=scope_key,
                gate="evidence-search",
                summary="TianGong evidence-search 未保留已批准性能协议所需的来源、数值或单位。",
                report_path=report_artifact["workspace_path"],
                report_sha256=report_artifact["sha256"],
            )
            raise RuntimeError(
                "Native evidence search did not preserve the cited primary source"
            )
        self._record_native_semantic_acceptance(
            activity_base_id=evidence_activity_base_id,
            activity_id=evidence_activity_id,
            attempt=evidence_attempt,
            scope_key=scope_key,
            gate="evidence-search",
            report_path=report_artifact["workspace_path"],
            report_sha256=report_artifact["sha256"],
        )
        performance = {
            **performance,
            "evidence_path": evidence_artifacts[
                "inputs/performance-evidence.json"
            ]["workspace_path"],
            "evidence_sha256": evidence_artifacts[
                "inputs/performance-evidence.json"
            ]["sha256"],
            "search_results_source": search_source,
            "search_report_path": evidence_artifacts[
                "outputs/evidence-search-report.json"
            ]["workspace_path"],
            "search_report_sha256": evidence_artifacts[
                "outputs/evidence-search-report.json"
            ]["sha256"],
        }
        performance_version = hashlib.sha256(_json_bytes(performance)).hexdigest()[:16]
        self.record(
            "decision.recorded",
            {
                "decision_id": f"performance-equivalence:{scope_key}:{performance_version}",
                "decision_type": "performance.equivalence.derived",
                "scope_id": canonical["scope_id"],
                "revision": canonical["revision"],
                "decision": performance["decision"],
                "relative_difference_percent": performance[
                    "relative_difference_percent"
                ],
                "threshold_percent": performance["threshold_percent"],
                "source_doi": performance["source"]["doi"],
                "evidence_path": performance["evidence_path"],
                "evidence_sha256": performance["evidence_sha256"],
                "search_report_path": performance["search_report_path"],
                "search_report_sha256": performance["search_report_sha256"],
            },
            actor="controller",
            idempotency_key=(
                f"decision:performance-equivalence:{scope_key}:{performance_version}"
            ),
        )

        if not performance["equivalence_result"]:
            scaling = service_unit_scaling_decision(performance)
            self.record(
                "risk.resolved",
                {
                    "risk_id": f"performance-equivalence:{scope_key}",
                    "resolution": "service_unit_scaling_derived",
                },
                actor="controller",
                idempotency_key=(
                    f"risk:performance-equivalence:{scope_key}:resolved:service-unit-v1"
                ),
            )
            result = {
                "scope_id": canonical["scope_id"],
                "revision": canonical["revision"],
                "gate_status": "service_unit_scaling_required",
                "performance_decision": performance,
                "service_unit_scaling": scaling,
                "next_action": (
                    "compile service-unit-aware route plans and run native build-plan gates"
                ),
            }
            route_version = hashlib.sha256(_json_bytes(result)).hexdigest()[:16]
            event = self.record(
                "research.release_gates.routed",
                result,
                actor="controller",
                idempotency_key=(
                    f"release-gates:{scope_key}:{evidence_version}:{route_version}:routed"
                ),
            )
            self.record(
                "milestone.completed",
                {
                    "milestone_id": "performance-service-unit-routing",
                    "title": "性能门已转入等服务量功能单位路线",
                    "status": "completed",
                    "next_action": result["next_action"],
                },
                actor="controller",
                idempotency_key=(
                    f"milestone:performance-service-unit-routing:{scope_key}:{route_version}:completed"
                ),
            )
            self.materialize_views()
            return event["payload"]

        effective_scope = effective_scope_for_local_prototype(canonical, performance)

        preliminary_plans = {
            route["route_id"]: build_process_plan(
                effective_scope["effective_scope"],
                route,
                provenance=scope_provenance,
                identity_scope_sha256=effective_scope["scope_amendment"][
                    "effective_scope_sha256"
                ],
            )
            for route in effective_scope["effective_scope"]["routes"]
        }
        identity_decisions: List[JsonObject] = []
        for route in effective_scope["effective_scope"]["routes"]:
            route_id = route["route_id"]
            plan = preliminary_plans[route_id]
            identity_request = {
                "schema_version": 1,
                "route_id": route_id,
                "target": {
                    "id": plan["target"]["id"],
                    "name": plan["name_plan"]["base_name"],
                    "reference_flow_id": plan["quantitative_reference_plan"][
                        "reference_flow_id"
                    ],
                    "reference_flow_name": plan["quantitative_reference_plan"][
                        "reference_flow_name"
                    ],
                    "quantitative_reference": plan["name_plan"][
                        "functional_unit_flow_properties"
                    ],
                    "geography": plan["target"]["geography"],
                    "reference_year": plan["time"]["reference_year"],
                    "technology_route": plan["target"]["technology_route"],
                    "system_boundary": plan["system_boundary"]["type"],
                    "classification": plan["target"]["classification_path"],
                    "operation": "produce",
                    "provider_role": "foreground_research_model",
                },
                "candidates": [],
                "candidate_coverage": {
                    "native_remote_search": "not_requested_in_this_activity",
                    "local_candidate_sources": [],
                },
            }
            request_hash = hashlib.sha256(_json_bytes(identity_request)).hexdigest()
            identity_version = request_hash[:16]
            activity_base_id = (
                f"identity-preflight:{scope_key}:{route_id}:{identity_version}"
            )
            identity_attempt = self._semantic_attempt(activity_base_id)
            activity_id = f"{activity_base_id}:attempt-{identity_attempt}"
            identity_root = (
                self.workspace
                / "artifacts"
                / "release-gates"
                / f"{canonical['scope_id']}-{canonical['revision']}"
                / "identity"
                / route_id
                / identity_version
                / f"attempt-{identity_attempt}"
            )
            identity_input = identity_root / "inputs" / "process-preflight.json"
            if self._completed_activity(activity_id) is None:
                identity_input.parent.mkdir(parents=True, exist_ok=True)
                _write_json(identity_input, identity_request)
            identity_activity = self.run_activity(
                activity_id=activity_id,
                name=f"运行 {route['name']} TianGong identity-preflight",
                skill_ref="process-automated-builder/identity-preflight",
                command=[
                    *prefix,
                    "process",
                    "identity-preflight",
                    "--input",
                    str(identity_input),
                    "--out-dir",
                    str(identity_root),
                    "--json",
                ],
                artifact_root=identity_root,
                expected_outputs=[
                    "inputs/process-preflight.json",
                    "outputs/identity-decision.json",
                    "outputs/identity-candidates.jsonl",
                    "outputs/identity-candidate-sources.json",
                ],
                effect="external_read",
            )
            identity_artifacts = {
                artifact["path"]: artifact
                for artifact in identity_activity["artifacts"]
            }
            report_artifact = identity_artifacts[
                "outputs/identity-decision.json"
            ]
            identity_report = self._load_native_json_report(
                report_path=(
                    identity_root / "outputs" / "identity-decision.json"
                ),
                report_artifact=report_artifact,
                activity_base_id=activity_base_id,
                activity_id=activity_id,
                attempt=identity_attempt,
                scope_key=scope_key,
                gate="identity-preflight",
                route_id=route_id,
            )
            automatic_decisions = {
                "reuse",
                "update_same_row",
                "version_bump",
                "create_new",
            }
            blockers = identity_report.get("blockers")
            candidates = identity_report.get("candidates")
            candidate_sources = identity_report.get("candidate_sources")
            if (
                identity_report.get("schema_version") != 1
                or identity_report.get("kind") != "process"
                or identity_report.get("status") != "passed"
                or identity_report.get("decision") not in automatic_decisions
                or identity_report.get("confidence")
                not in {"low", "medium", "high"}
                or not isinstance(blockers, list)
                or blockers
                or not isinstance(candidates, list)
                or not isinstance(candidate_sources, list)
                or not self._identity_report_matches_request(
                    identity_report, identity_request
                )
            ):
                self._record_native_semantic_failure(
                    activity_base_id=activity_base_id,
                    activity_id=activity_id,
                    attempt=identity_attempt,
                    scope_key=scope_key,
                    gate="identity-preflight",
                    route_id=route_id,
                    summary=(
                        f"{route['name']} 的 TianGong identity-preflight 报告未通过或未绑定到本次目标。"
                    ),
                    report_path=report_artifact["workspace_path"],
                    report_sha256=report_artifact["sha256"],
                )
                raise RuntimeError(
                    f"Route '{route_id}' did not receive an automatic native identity decision"
                )
            self._record_native_semantic_acceptance(
                activity_base_id=activity_base_id,
                activity_id=activity_id,
                attempt=identity_attempt,
                scope_key=scope_key,
                gate="identity-preflight",
                route_id=route_id,
                report_path=report_artifact["workspace_path"],
                report_sha256=report_artifact["sha256"],
            )
            identity = {
                "route_id": route_id,
                "status": identity_report["status"],
                "decision": identity_report["decision"],
                "confidence": identity_report["confidence"],
                "candidate_count": len(candidates),
                "candidate_source_count": len(candidate_sources),
                "report_path": identity_artifacts[
                    "outputs/identity-decision.json"
                ]["workspace_path"],
                "report_sha256": identity_artifacts[
                    "outputs/identity-decision.json"
                ]["sha256"],
                "candidate_sources_path": identity_artifacts[
                    "outputs/identity-candidate-sources.json"
                ]["workspace_path"],
            }
            self.record(
                "decision.recorded",
                {
                    "decision_id": (
                        f"identity-preflight:{scope_key}:{route_id}:{identity_version}:"
                        f"{identity['report_sha256'][:16]}"
                    ),
                    "decision_type": "process.identity.preflight",
                    **identity,
                },
                actor="controller",
                idempotency_key=(
                    f"decision:identity-preflight:{scope_key}:{route_id}:{identity_version}:"
                    f"{identity['report_sha256'][:16]}"
                ),
            )
            identity_decisions.append(identity)

        self.record(
            "risk.resolved",
            {
                "risk_id": f"identity-preflight:{scope_key}",
                "resolution": "native_automatic_decisions_recorded",
                "superseded_by": f"identity-candidate-coverage:{scope_key}",
            },
            actor="controller",
            idempotency_key=(
                f"risk:identity-preflight:{scope_key}:resolved:native-automatic-v1"
            ),
        )
        self.record(
            "risk.resolved",
            {
                "risk_id": f"performance-equivalence:{scope_key}",
                "resolution": "provisional_effective_scope_created",
                "superseded_by": f"performance-protocol-gap:{scope_key}",
            },
            actor="controller",
            idempotency_key=(
                f"risk:performance-equivalence:{scope_key}:resolved:provisional-scope-v1"
            ),
        )
        uncovered_routes = [
            row["route_id"]
            for row in identity_decisions
            if row["candidate_source_count"] == 0
        ]
        if uncovered_routes:
            coverage_version = hashlib.sha256(
                "|".join(
                    row["report_sha256"] for row in identity_decisions
                ).encode("ascii")
            ).hexdigest()[:16]
            self.record(
                "risk.flagged",
                {
                    "risk_id": f"identity-candidate-coverage:{scope_key}",
                    "severity": "medium",
                    "summary": "原生 identity-preflight 对无候选集合给出 create_new；本次活动没有 TianGong 远程或本地候选来源。AI 继续本地建模，但发布前必须用可用凭证重跑远程去重。",
                    "route_ids": uncovered_routes,
                },
                actor="controller",
                idempotency_key=(
                    f"risk:identity-candidate-coverage:{scope_key}:{coverage_version}"
                ),
            )
        if performance["protocol_gaps"]:
            gap_version = hashlib.sha256(
                "|".join(performance["protocol_gaps"]).encode("utf-8")
            ).hexdigest()[:16]
            self.record(
                "risk.flagged",
                {
                    "risk_id": f"performance-protocol-gap:{scope_key}",
                    "severity": "medium",
                    "summary": "来源公开摘要未报告电化学测试温度，且只支持实验室碳包覆候选；8.51% 等效结论可驱动本地原型，公开结论前需全文复核。",
                    "gaps": performance["protocol_gaps"],
                },
                actor="controller",
                idempotency_key=(
                    f"risk:performance-protocol-gap:{scope_key}:{gap_version}"
                ),
            )

        gate_resolution = {
            "scope_id": canonical["scope_id"],
            "revision": canonical["revision"],
            "performance_decision": performance,
            "identity_decisions": identity_decisions,
            **effective_scope,
        }
        build_plans = self.validate_process_build_plans(
            scope,
            revision=revision,
            command_prefix=command_prefix,
            source_ref=scope_source_ref,
            gate_resolution=gate_resolution,
        )
        gate_statuses = {row["status"] for row in build_plans}
        if gate_statuses != {"passed"}:
            raise RuntimeError("Resolved process build plans did not pass the native gate")
        result = {
            "scope_id": canonical["scope_id"],
            "revision": canonical["revision"],
            "gate_status": "passed",
            "performance_decision": performance,
            "identity_decisions": identity_decisions,
            **effective_scope,
            "build_plans": build_plans,
            "next_action": "物化两条本地 process payload 并运行原生 schema/reference QA",
        }
        resolution_version = hashlib.sha256(_json_bytes(result)).hexdigest()[:16]
        event = self.record(
            "research.release_gates.resolved",
            result,
            actor="controller",
            idempotency_key=(
                f"release-gates:{scope_key}:{evidence_version}:{resolution_version}:resolved"
            ),
        )
        self.materialize_views()
        return event["payload"]

    def materialize_views(self) -> JsonObject:
        events = self.events()
        snapshot = self._project(events)
        _write_json(self.workspace / self.SNAPSHOT_FILE, snapshot)
        _write_json(self.workspace / self.MACHINE_FILE, self._machine_view(snapshot))
        if snapshot.get("lifecycle") is not None:
            _write_json(self.workspace / "lifecycle-state.json", snapshot["lifecycle"])
        director_status_path = self.workspace / "director-status.json"
        if snapshot.get("director") is not None:
            _write_json(director_status_path, snapshot["director"])
        elif director_status_path.exists():
            director_status_path.unlink()
        (self.workspace / self.HUMAN_FILE).write_text(
            self._human_view(snapshot), encoding="utf-8"
        )
        return snapshot

