    def clean_research_council_projection_bytes(
        self,
        events: Sequence[JsonObject],
        artifacts: Mapping[str, bytes],
    ) -> Dict[str, bytes]:
        """Materialize Council projections in an isolated project through this port."""

        with tempfile.TemporaryDirectory() as temporary:
            clean_workspace = Path(temporary) / "project"
            clean_workspace.mkdir()
            event_bytes = "".join(
                json.dumps(event, ensure_ascii=False, sort_keys=True) + "\n"
                for event in events
            ).encode("utf-8")
            (clean_workspace / self.EVENT_FILE).write_bytes(event_bytes)
            for relative_text, content in artifacts.items():
                relative = Path(relative_text)
                if (
                    relative.is_absolute()
                    or ".." in relative.parts
                    or relative.parts[:1] != ("research-council-benchmark",)
                ):
                    raise ValueError("Council clean replay artifact path is invalid")
                destination = clean_workspace / relative
                destination.parent.mkdir(parents=True, exist_ok=True)
                destination.write_bytes(content)
            clean = type(self).open(clean_workspace)
            clean.materialize_views()
            return {
                name: (clean_workspace / name).read_bytes()
                for name in (
                    self.SNAPSHOT_FILE,
                    self.MACHINE_FILE,
                    self.HUMAN_FILE,
                )
            }

