    def _completed_activity(self, activity_id: str) -> Optional[JsonObject]:
        for event in self.events():
            if event.get("event_type") != "activity.completed":
                continue
            payload = event.get("payload", {})
            if payload.get("activity_id") == activity_id:
                return payload
        return None

    def _verify_completed_artifacts(self, payload: JsonObject) -> None:
        activity_id = payload.get("activity_id", "unknown")
        for artifact in payload.get("artifacts", []):
            workspace_path = artifact.get("workspace_path")
            expected_hash = artifact.get("sha256")
            if not isinstance(workspace_path, str) or not isinstance(
                expected_hash, str
            ):
                raise RuntimeError(
                    f"Completed activity '{activity_id}' has an invalid artifact record"
                )
            candidate = (self.workspace / workspace_path).resolve()
            try:
                candidate.relative_to(self.workspace)
            except ValueError as error:
                raise RuntimeError(
                    f"Completed activity '{activity_id}' points outside its workspace"
                ) from error
            if not candidate.is_file():
                raise RuntimeError(
                    f"Completed activity '{activity_id}' artifact is missing: {workspace_path}"
                )
            actual_hash = hashlib.sha256(candidate.read_bytes()).hexdigest()
            if actual_hash != expected_hash:
                raise RuntimeError(
                    f"Completed activity '{activity_id}' artifact hash drifted: {workspace_path}"
                )

    def _verify_failed_activity_evidence(self, payload: JsonObject) -> None:
        artifact = payload.get("execution_artifact")
        if artifact is None:
            return
        activity_id = payload.get("activity_id", "unknown")
        if not isinstance(artifact, dict):
            raise RuntimeError(
                f"Failed activity '{activity_id}' has an invalid execution artifact"
            )
        workspace_path = artifact.get("workspace_path")
        expected_hash = artifact.get("sha256")
        expected_bytes = artifact.get("bytes")
        expected_command_hash = artifact.get("command_sha256")
        if (
            not isinstance(workspace_path, str)
            or not isinstance(expected_hash, str)
            or isinstance(expected_bytes, bool)
            or not isinstance(expected_bytes, int)
            or not isinstance(expected_command_hash, str)
        ):
            raise RuntimeError(
                f"Failed activity '{activity_id}' has an incomplete execution artifact"
            )
        candidate = (self.workspace / workspace_path).resolve()
        try:
            candidate.relative_to(self.workspace)
        except ValueError as error:
            raise RuntimeError(
                f"Failed activity '{activity_id}' points outside its workspace"
            ) from error
        if not candidate.is_file():
            raise RuntimeError(
                f"Failed activity '{activity_id}' execution evidence is missing"
            )
        content = candidate.read_bytes()
        if (
            len(content) != expected_bytes
            or hashlib.sha256(content).hexdigest() != expected_hash
        ):
            raise RuntimeError(
                f"Failed activity '{activity_id}' execution evidence hash drifted"
            )
        try:
            execution_report = json.loads(content)
        except (UnicodeError, json.JSONDecodeError) as error:
            raise RuntimeError(
                f"Failed activity '{activity_id}' execution evidence is not valid JSON"
            ) from error
        if (
            not isinstance(execution_report, dict)
            or hashlib.sha256(
                _json_bytes(execution_report.get("command"))
            ).hexdigest()
            != expected_command_hash
        ):
            raise RuntimeError(
                f"Failed activity '{activity_id}' command evidence drifted"
            )

    def run_activity(
        self,
        *,
        activity_id: str,
        name: str,
        skill_ref: str,
        command: List[str],
        artifact_root: Path,
        expected_outputs: List[str],
        effect: str = "local_write",
        authorization_request_id: Optional[str] = None,
        accepted_exit_codes: Optional[Iterable[int]] = None,
    ) -> JsonObject:
        """Run one idempotent command and register its durable output artifacts."""
        if not command or not all(isinstance(part, str) and part for part in command):
            raise ValueError("command must be a non-empty list of strings")
        if not expected_outputs:
            raise ValueError("expected_outputs must contain at least one relative path")
        if effect not in self.ACTIVITY_EFFECTS:
            raise ValueError(
                f"Unsupported activity effect '{effect}'; expected one of "
                f"{sorted(self.ACTIVITY_EFFECTS)}"
            )
        accepted_codes = set(
            {0} if accepted_exit_codes is None else accepted_exit_codes
        )
        if not accepted_codes or any(
            not isinstance(code, int) or code < 0 for code in accepted_codes
        ):
            raise ValueError(
                "accepted_exit_codes must be a non-empty iterable of non-negative integers"
            )

        events = self.events()
        completed = self._completed_activity(activity_id)
        if completed is not None:
            completed_effect = completed.get("effect", "local_write")
            if completed_effect != effect:
                raise ValueError(
                    f"Activity '{activity_id}' was completed with effect "
                    f"'{completed_effect}', not '{effect}'"
                )
            completed_exit_code = completed.get("exit_code", 0)
            if completed_exit_code not in accepted_codes:
                raise ValueError(
                    f"Activity '{activity_id}' completed with exit code "
                    f"{completed_exit_code}, which is not accepted by this invocation"
                )
            self._verify_completed_artifacts(completed)
            return completed

        authorization_id = authorization_request_id or f"authorize:{activity_id}"
        if effect in self.AUTHORIZED_EFFECTS:
            request_event = next(
                (
                    event
                    for event in events
                    if event.get("event_type") == "authorization.requested"
                    and event.get("payload", {}).get("request_id") == authorization_id
                ),
                None,
            )
            if request_event is not None:
                request = request_event.get("payload", {})
                if (
                    request.get("activity_id") != activity_id
                    or request.get("effect") != effect
                ):
                    raise PermissionError(
                        f"Authorization '{authorization_id}' is bound to activity "
                        f"'{request.get('activity_id')}' with effect '{request.get('effect')}'"
                    )
            else:
                self.record(
                    "authorization.requested",
                    {
                        "request_id": authorization_id,
                        "activity_id": activity_id,
                        "activity_name": name,
                        "effect": effect,
                        "reason": "该动作会改变外部或不可逆的共享状态，需要人承担责任。",
                    },
                    actor="controller",
                    idempotency_key=f"authorization:{authorization_id}:requested",
                )
                self.materialize_views()
                raise PermissionError(
                    f"Activity '{activity_id}' requires authorization '{authorization_id}'"
                )
            granted = any(
                event.get("event_type") == "authorization.granted"
                and event.get("actor") == "human"
                and event.get("payload", {}).get("request_id") == authorization_id
                and event.get("sequence", 0) > request_event.get("sequence", 0)
                for event in events
            )
            if not granted:
                self.materialize_views()
                raise PermissionError(
                    f"Activity '{activity_id}' requires authorization '{authorization_id}'"
                )

        resolved_artifact_root = artifact_root.resolve()
        try:
            resolved_artifact_root.relative_to(self.workspace)
        except ValueError as error:
            raise ValueError("artifact_root must be inside the research project workspace") from error
        resolved_artifact_root.mkdir(parents=True, exist_ok=True)
        execution_report_path = resolved_artifact_root / "activity-execution.json"
        started = next(
            (
                event
                for event in events
                if event.get("event_type") == "activity.started"
                and event.get("payload", {}).get("activity_id") == activity_id
            ),
            None,
        )
        failed = any(
            event.get("event_type") == "activity.failed"
            and event.get("payload", {}).get("activity_id") == activity_id
            for event in events
        )
        execution_report = None
        if started is not None and not failed:
            started_payload = started.get("payload", {})
            expected_started = {
                "name": name,
                "skill_ref": skill_ref,
                "effect": effect,
                "authorization_request_id": (
                    authorization_id if effect in self.AUTHORIZED_EFFECTS else None
                ),
                "accepted_exit_codes": sorted(accepted_codes),
                "artifact_root": str(
                    resolved_artifact_root.relative_to(self.workspace)
                ),
            }
            if any(
                started_payload.get(key) != value
                for key, value in expected_started.items()
            ):
                raise RuntimeError(
                    f"Interrupted activity '{activity_id}' start evidence drifted"
                )
            if not execution_report_path.is_file():
                raise RuntimeError(
                    f"Interrupted activity '{activity_id}' has no execution evidence; "
                    "use a new attempt instead of rerunning the same activity identity"
                )
            try:
                execution_report = json.loads(
                    execution_report_path.read_text(encoding="utf-8")
                )
            except (OSError, UnicodeError, json.JSONDecodeError) as error:
                raise RuntimeError(
                    f"Interrupted activity '{activity_id}' execution evidence is invalid"
                ) from error
            if (
                not isinstance(execution_report, dict)
                or execution_report.get("activity_id") != activity_id
                or execution_report.get("name") != name
                or execution_report.get("skill_ref") != skill_ref
                or execution_report.get("effect") != effect
                or execution_report.get("command") != command
                or isinstance(execution_report.get("exit_code"), bool)
                or not isinstance(execution_report.get("exit_code"), int)
                or not isinstance(execution_report.get("stdout"), str)
                or not isinstance(execution_report.get("stderr"), str)
            ):
                raise RuntimeError(
                    f"Interrupted activity '{activity_id}' execution evidence drifted"
                )
        else:
            self.record(
                "activity.started",
                {
                    "activity_id": activity_id,
                    "name": name,
                    "skill_ref": skill_ref,
                    "effect": effect,
                    "authorization_request_id": (
                        authorization_id if effect in self.AUTHORIZED_EFFECTS else None
                    ),
                    "accepted_exit_codes": sorted(accepted_codes),
                    "artifact_root": str(
                        resolved_artifact_root.relative_to(self.workspace)
                    ),
                },
                actor="controller",
                idempotency_key=f"activity:{activity_id}:started",
            )
            result = subprocess.run(
                command,
                cwd=str(self.workspace),
                capture_output=True,
                text=True,
                check=False,
            )
            execution_report = {
                "activity_id": activity_id,
                "name": name,
                "skill_ref": skill_ref,
                "effect": effect,
                "command": command,
                "exit_code": result.returncode,
                "stdout": result.stdout,
                "stderr": result.stderr,
            }
            _write_json(execution_report_path, execution_report)
        execution_content = execution_report_path.read_bytes()
        execution_artifact = {
            "workspace_path": str(execution_report_path.relative_to(self.workspace)),
            "sha256": hashlib.sha256(execution_content).hexdigest(),
            "bytes": len(execution_content),
            "command_sha256": hashlib.sha256(_json_bytes(command)).hexdigest(),
        }

        exit_code = execution_report["exit_code"]
        if exit_code not in accepted_codes:
            failure = {
                "activity_id": activity_id,
                "name": name,
                "skill_ref": skill_ref,
                "effect": effect,
                "status": "failed",
                "exit_code": exit_code,
                "execution_report": execution_artifact["workspace_path"],
                "execution_artifact": execution_artifact,
            }
            self.record("activity.failed", failure, actor="controller")
            self.materialize_views()
            raise RuntimeError(
                f"Research activity '{activity_id}' failed with exit code {exit_code}"
            )

        artifacts: List[JsonObject] = []
        for relative_output in expected_outputs:
            candidate = (resolved_artifact_root / relative_output).resolve()
            try:
                candidate.relative_to(resolved_artifact_root)
            except ValueError as error:
                raise ValueError(
                    f"expected output must stay inside artifact_root: {relative_output}"
                ) from error
            if not candidate.is_file():
                self.record(
                    "activity.failed",
                    {
                        "activity_id": activity_id,
                        "name": name,
                        "skill_ref": skill_ref,
                        "effect": effect,
                        "status": "failed",
                        "reason": f"missing expected output: {relative_output}",
                        "exit_code": exit_code,
                        "execution_report": execution_artifact[
                            "workspace_path"
                        ],
                        "execution_artifact": execution_artifact,
                    },
                    actor="controller",
                )
                self.materialize_views()
                raise FileNotFoundError(
                    f"Research activity '{activity_id}' did not create {relative_output}"
                )
            content = candidate.read_bytes()
            artifact = {
                "artifact_id": str(uuid.uuid5(uuid.NAMESPACE_URL, f"{activity_id}:{relative_output}")),
                "activity_id": activity_id,
                "skill_ref": skill_ref,
                "path": relative_output,
                "workspace_path": str(candidate.relative_to(self.workspace)),
                "sha256": hashlib.sha256(content).hexdigest(),
                "bytes": len(content),
            }
            artifacts.append(artifact)
            self.record(
                "artifact.registered",
                artifact,
                actor="controller",
                idempotency_key=f"activity:{activity_id}:artifact:{relative_output}",
            )

        completed = {
            "activity_id": activity_id,
            "name": name,
            "skill_ref": skill_ref,
            "effect": effect,
            "status": "completed",
            "exit_code": exit_code,
            "artifacts": artifacts,
            "execution_report": str(
                (resolved_artifact_root / "activity-execution.json").relative_to(self.workspace)
            ),
        }
        event = self.record(
            "activity.completed",
            completed,
            actor="controller",
            idempotency_key=f"activity:{activity_id}:completed",
        )
        self.materialize_views()
        return event["payload"]

    def fetch_tidas_context(
        self,
        *,
        kind: str,
        revision: str = "cli-0.0.25",
        command_prefix: Optional[List[str]] = None,
    ) -> JsonObject:
        """Fetch and pin an authoritative TianGong TIDAS AI context pack."""
        if kind not in self.TIDAS_TYPES:
            raise ValueError(
                f"Unsupported TIDAS type '{kind}'; expected one of {sorted(self.TIDAS_TYPES)}"
            )
        if not revision.strip():
            raise ValueError("revision must be non-empty")
        prefix = command_prefix or [
            "npm",
            "exec",
            "--yes",
            f"--package={self.TIANGONG_CLI_PACKAGE}",
            "--",
            "tiangong-lca",
        ]
        activity_id = f"tidas-context:{kind}:{revision}"
        artifact_root = self.workspace / "artifacts" / "tidas-context" / f"{kind}-{revision}"
        self.record(
            "milestone.started",
            {
                "milestone_id": "tidas-contract-context",
                "title": f"读取 TIDAS {kind} 权威合同",
                "status": "running",
                "next_action": f"通过 TianGong CLI 生成 {kind} AI context pack",
                "terms": [
                    {
                        "term": "TIDAS",
                        "explanation": "天工生命周期评价数据交换格式。",
                    },
                    {
                        "term": "Context pack",
                        "explanation": "供 AI 使用的结构、方法和运行规则组合包。",
                    },
                ],
            },
            actor="controller",
            idempotency_key=f"milestone:{activity_id}:started",
        )
        expected_outputs = [
            "outputs/contract-manifest.json",
            "outputs/contract-report.json",
            "outputs/schema.json",
            "outputs/methodology.yaml",
            "outputs/runtime-ruleset.json",
            "outputs/ai-context.json",
            "outputs/ai-context.md",
        ]
        activity = self.run_activity(
            activity_id=activity_id,
            name=f"生成 TIDAS {kind} AI context pack",
            skill_ref="tidas-contract-context",
            command=[
                *prefix,
                "dataset",
                "context-pack",
                "--type",
                kind,
                "--profile",
                "ai-import",
                "--include",
                "schema,methodology,ruleset",
                "--out-dir",
                str(artifact_root),
                "--json",
            ],
            artifact_root=artifact_root,
            expected_outputs=expected_outputs,
            effect="external_read",
        )
        manifest_path = artifact_root / "outputs" / "contract-manifest.json"
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        decision = {
            "decision_id": f"tidas-contract:{kind}:{revision}",
            "decision_type": "tidas.contract.pinned",
            "kind": kind,
            "revision": revision,
            "tool_identity": self.TIANGONG_CLI_PACKAGE,
            "manifest_path": str(manifest_path.relative_to(self.workspace)),
            "schema_sha256": manifest.get("schema", {}).get("sha256"),
            "methodology_sha256": manifest.get("methodology", {}).get("sha256"),
            "ruleset_sha256": manifest.get("ruleset", {}).get("sha256"),
        }
        self.record(
            "decision.recorded",
            decision,
            actor="controller",
            idempotency_key=f"decision:{decision['decision_id']}",
        )
        self.record(
            "milestone.completed",
            {
                "milestone_id": "tidas-contract-context",
                "title": f"已固定 TIDAS {kind} 权威合同",
                "status": "completed",
                "next_action": "使用已固定合同准备第一个 process build plan",
            },
            actor="controller",
            idempotency_key=f"milestone:{activity_id}:completed",
        )
        self.materialize_views()
        return activity

    def _project(self, events: Iterable[JsonObject]) -> JsonObject:
        events = list(events)
        from .council_project import (
            initial_council_projection,
            reduce_council_event,
            validate_project_council_events,
        )
        from .research_council_workflow import (
            validate_research_council_event_stream,
        )
        from .lifecycle import (
            initial_lifecycle_projection,
            reduce_lifecycle_event,
            validate_project_lifecycle_events,
        )
        from .responsibility_boundary import validate_responsibility_events

        validate_research_council_event_stream(self, events)
        validate_project_council_events(self, events)
        responsibility_errors = validate_responsibility_events(events, self)
        if responsibility_errors:
            raise ValueError(
                "responsibility event history is invalid: "
                + "; ".join(responsibility_errors)
            )
        has_lifecycle = any(
            isinstance(event.get("event_type"), str)
            and event["event_type"].startswith("research.lifecycle.")
            for event in events
        )
        if has_lifecycle:
            validate_project_lifecycle_events(events)
        state: JsonObject = {
            "project_id": "",
            "title": "",
            "objective": "",
            "status": "planned",
            "state_version": 0,
            "active_milestone": None,
            "unresolved_risks": [],
            "artifacts": [],
            "decisions": [],
            "authorization_requests": [],
            "terms": [],
            "last_event_id": None,
            "research_scope": None,
            "scope_provenance": None,
            "gate_resolution": None,
            "gate_routing": None,
            "process_materialization": None,
            "inventory_evidence_plan": None,
            "inventory_scenarios": None,
            "inventory_identities": None,
            "inventory_entities": None,
            "inventory_references": None,
            "scientific_gaps": None,
            "residual_outputs": None,
            "energy_sensitivity": None,
            "lineage_assurance": None,
            "evidence_acquisition": None,
            "public_discovery": None,
            "source_expansion": None,
            "author_institution_routes": None,
            "record_export_probe": None,
            "korean_scholarly_routes": None,
            "author_hosted_file_routes": None,
            "acquisition_options": None,
            "stoichiometric_consistency": None,
            "claim_matrix": None,
            "replacement_map": None,
            "replacement_dry_run": None,
            "evidence_intake_harness": None,
            "evidence_candidate_ledger": None,
            "evidence_admission_transaction": None,
            "comparison_readiness": None,
            "lifecyclemodel_assembly_plan": None,
            "lifecyclemodel_shells": None,
            "resulting_process_dry_run": None,
            "model_execution_package": None,
            "model_package_replay": None,
            "portable_runtime_closure": None,
            "provider_network_gap_map": None,
            "provider_candidate_resolution": None,
            "provider_evidence_requirements": None,
            "uslci_provider_probe": None,
            "uslci_provider_normalization": None,
            "uslci_generation_closure": None,
            "uslci_unit_provider_batch": None,
            "uslci_unit_provider_batch_2": None,
            "uslci_unit_provider_cumulative_batch": None,
            "uslci_current_breadth_closure": None,
            "uslci_depth_4_provider_batch": None,
            "uslci_depth_4_layer_closure": None,
            "uslci_background_inventory_integration": None,
            "uslci_native_slice_preflight_plan": None,
            "uslci_native_slice_preflight_batch": None,
            "uslci_reference_flow_resolution": None,
            "uslci_reference_flow_authoring_plan": None,
            "uslci_reference_flow_authoring_execution": None,
            "uslci_reference_flow_dependent_process_action_recompile": None,
            "uslci_native_slice_process_action_execution": None,
            "uslci_flow_identity_resolution_plan": None,
            "uslci_flow_identity_resolution_batch": None,
            "uslci_flow_authoring_plan": None,
            "uslci_flow_authoring_canary_supports": None,
            "uslci_flow_authoring_canary_saved_plans": None,
            "uslci_flow_authoring_canary_native_gates": None,
            "uslci_elementary_flow_native_qa_harness": None,
            "uslci_flow_authoring_bulk_batch_supports": None,
            "uslci_flow_authoring_bulk_batch_saved_plans": None,
            "uslci_flow_authoring_bulk_batch_native_gates": None,
            "uslci_flow_authoring_corpus_closure": None,
            "uslci_flow_authoring_corpus_release_plan": None,
            "uslci_flow_authoring_corpus_release_canary": None,
            "minimum_lifepo4_comparison_graph": None,
            "minimum_lifepo4_comparison_model": None,
            "minimum_lifepo4_comparative_lcia": None,
            "minimum_lifepo4_screening_final_package": None,
            "benchmark_portfolio": None,
            "tiangong_authority_following": {
                "status": "not_started",
                "capability_adoption": None,
                "catalog_capture": None,
                "selection": None,
                "current_receipt_id": None,
                "current_dataset_version": None,
                "current_binding_id": None,
                "native_case": None,
                "transition": None,
                "package": None,
                "acceptance": None,
                "blocker": None,
                "next_route": None,
            },
            "research_council": {
                "status": "not_started",
                "qualification_id": None,
                "freeze_id": None,
                "cell_id": None,
                "portfolio_id": None,
                "portfolio_status": None,
                "council_disposition": None,
                "portfolio_lineage_contract": None,
                "portfolio_lineage_id": None,
                "portfolio_manifest": None,
                "portfolio_review_status": None,
                "legacy_unaccepted_portfolio_ids": [],
                "baseline_trial_count": 0,
                "council_trial_count": 0,
                "evaluation_id": None,
                "decision_id": None,
                "acceptance_id": None,
                "artifact_refs": [],
                "blocker": None,
                "next_route": None,
            },
            "council": initial_council_projection(),
        }
        if has_lifecycle:
            state["lifecycle"] = initial_lifecycle_projection()
        for event in events:
            payload = event.get("payload", {})
            event_type = event.get("event_type")
            reduce_council_event(self, state["council"], event)
            if has_lifecycle:
                reduce_lifecycle_event(state["lifecycle"], event)
            if event_type == "research.lifecycle.phase_ready_to_complete":
                state["artifacts"].extend(
                    copy.deepcopy(payload.get("registered_artifacts") or [])
                )
            state["state_version"] = event.get("sequence", state["state_version"] + 1)
            state["last_event_id"] = event.get("event_id")
            if event_type in {
                "research.uslci_background_inventory_integration.compiled",
                "research.uslci_native_slice_preflight_plan.compiled",
                "research.uslci_native_slice_preflight_batch.completed",
                "research.uslci_reference_flow_resolution.compiled",
                "research.uslci_reference_flow_authoring_plan.compiled",
                "research.uslci_reference_flow_authoring_execution.completed",
                "research.uslci_reference_flow_dependent_process_actions.recompiled",
                "research.uslci_native_slice_process_action_execution.completed",
                "research.uslci_flow_identity_resolution_plan.compiled",
                "research.uslci_flow_identity_resolution_batch.completed",
                "research.uslci_flow_authoring_plan.compiled",
                "research.uslci_flow_authoring_canary_supports.resolved",
            }:
                state["uslci_flow_authoring_canary_supports"] = None
                state["uslci_flow_authoring_canary_saved_plans"] = None
                state["uslci_flow_authoring_canary_native_gates"] = None
                state["uslci_elementary_flow_native_qa_harness"] = None
                state["uslci_flow_authoring_bulk_batch_supports"] = None
                state["uslci_flow_authoring_bulk_batch_saved_plans"] = None
